-- Seed 7x10 dataset for NewsAppJS (real-source edition)
-- Source news + media: https://alikhbariah.com (WP REST + video_list pages)
-- Source video metadata: YouTube oEmbed for extracted IDs

begin;

-- =============================
-- 0) Compatibility columns
-- =============================
alter table if exists public.locations
  add column if not exists name_en text,
  add column if not exists slug text;

alter table if exists public.categories
  add column if not exists name_en text,
  add column if not exists type text not null default 'news',
  add column if not exists cover_image_url text;

alter table if exists public.news
  add column if not exists title_en text,
  add column if not exists summary text,
  add column if not exists summary_en text,
  add column if not exists content_en text,
  add column if not exists image_url text,
  add column if not exists source_url text,
  add column if not exists category_id bigint,
  add column if not exists location_id bigint,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists is_hidden boolean not null default false,
  add column if not exists is_featured boolean not null default false,
  add column if not exists sent_notification boolean not null default true,
  add column if not exists view_count integer not null default 0;

alter table if exists public.breaking_news
  add column if not exists title text,
  add column if not exists title_en text,
  add column if not exists content text,
  add column if not exists content_en text,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists start_time timestamptz,
  add column if not exists end_time timestamptz,
  add column if not exists send_notification boolean not null default true,
  add column if not exists is_active boolean not null default true,
  add column if not exists view_count integer not null default 0;

alter table if exists public.videos
  add column if not exists title text,
  add column if not exists title_en text,
  add column if not exists youtube_url text,
  add column if not exists category_id bigint,
  add column if not exists thumbnail_url text,
  add column if not exists order_index integer not null default 0,
  add column if not exists published_at timestamptz,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists is_hidden boolean not null default false;

-- Accept program type in categories
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'categories_type_check'
      and conrelid = 'public.categories'::regclass
  ) then
    alter table public.categories drop constraint categories_type_check;
  end if;

  alter table public.categories
    add constraint categories_type_check
    check (type in ('news', 'video', 'program'));
exception when duplicate_object then
  null;
end $$;

-- =============================
-- 1) Clear existing rows
-- =============================
truncate table public.ticker_news restart identity cascade;
truncate table public.breaking_news restart identity cascade;
truncate table public.news restart identity cascade;
truncate table public.videos restart identity cascade;
truncate table public.locations restart identity cascade;
delete from public.categories where coalesce(type, 'news') in ('news', 'video', 'program');

-- =============================
-- 2) Locations (Syrian governorates)
-- =============================
insert into public.locations (name, name_en, slug)
values
  ('دمشق', 'Damascus', 'damascus'),
  ('ريف دمشق', 'Rif Dimashq', 'rif-dimashq'),
  ('حلب', 'Aleppo', 'aleppo'),
  ('حمص', 'Homs', 'homs'),
  ('حماة', 'Hama', 'hama'),
  ('اللاذقية', 'Latakia', 'latakia'),
  ('طرطوس', 'Tartus', 'tartus'),
  ('إدلب', 'Idlib', 'idlib'),
  ('الرقة', 'Raqqa', 'raqqa'),
  ('دير الزور', 'Deir ez-Zor', 'deir-ez-zor'),
  ('الحسكة', 'Al-Hasakah', 'al-hasakah'),
  ('درعا', 'Daraa', 'daraa'),
  ('السويداء', 'As-Suwayda', 'as-suwayda'),
  ('القنيطرة', 'Quneitra', 'quneitra'),
  ('سوريا', 'Syria', 'syria'),
  ('المملكة المتحدة', 'United Kingdom', 'united-kingdom'),
  ('لندن', 'London', 'london'),
  ('الولايات المتحدة', 'United States', 'united-states'),
  ('واشنطن', 'Washington', 'washington'),
  ('لبنان', 'Lebanon', 'lebanon'),
  ('العراق', 'Iraq', 'iraq'),
  ('إيران', 'Iran', 'iran'),
  ('الأردن', 'Jordan', 'jordan'),
  ('فلسطين', 'Palestine', 'palestine'),
  ('غزة', 'Gaza', 'gaza'),
  ('إسرائيل', 'Israel', 'israel'),
  ('الكويت', 'Kuwait', 'kuwait'),
  ('الإمارات العربية المتحدة', 'United Arab Emirates', 'uae'),
  ('قطر', 'Qatar', 'qatar'),
  ('السعودية', 'Saudi Arabia', 'saudi-arabia'),
  ('مصر', 'Egypt', 'egypt'),
  ('ألمانيا', 'Germany', 'germany'),
  ('تركيا', 'Turkey', 'turkey')
on conflict (slug) do update
set name = excluded.name, name_en = excluded.name_en;

-- =============================
-- 3) News categories (7)
-- =============================
insert into public.categories (name, name_en, slug, order_index, type)
values
  ('سياسي', 'Politics', 'news-politics', 1, 'news'),
  ('اقتصاد', 'Economy', 'news-economy', 2, 'news'),
  ('محلي', 'Local', 'news-local', 3, 'news'),
  ('عربي ودولي', 'Arab and International', 'news-arab-international', 4, 'news'),
  ('رياضة', 'Sports', 'news-sports', 5, 'news'),
  ('ثقافة', 'Culture', 'news-culture', 6, 'news'),
  ('صحة', 'Health', 'news-health', 7, 'news')
on conflict (slug) do update
set name = excluded.name, name_en = excluded.name_en, order_index = excluded.order_index, type = excluded.type;

-- =============================
-- 4) 70 real news items (7 x 10)
-- =============================
insert into public.news (
  title, title_en, summary, summary_en, content, content_en,
  image_url, category_id, location_id, created_at,
  is_hidden, is_featured, sent_notification, view_count
)
values
  ('المبعوثة البريطانية: زيارة الرئيس الشرع للندن محطة مفصلية في العلاقات مع سوريا', 'The British envoy: President Al-Shara''s visit to London is a turning point in relations with Syria', 'أكدت الممثّلة الخاصة للمملكة المتحدة آن سنو، الخميس 2 نيسان، أن الزيارة الأخيرة، التي أجراها السيد الرئيس أحمد الشرع، إلى لندن شكّلت محطة مفصلية في مسار العلاقات بين المملكة وسوريا. وقالت سنو في منشور عبر منصة “إكس” إن الزيارة تضمنت لقاءات عدة وجولة في البرلمان ومناقشات حول سيادة القانون والتعددية السياسية، إضافةً إلى لقاء مع […]', 'The Special Representative of the United Kingdom, Anne Snow, confirmed on Thursday, April 2, that the recent visit by President Ahmed Al-Sharaa to London constituted a turning point in the course of relations between the Kingdom and Syria. Snow said in a post on the “X” platform: The visit included several meetings, a tour of Parliament, and discussions on the rule of law and political pluralism, in addition to a meeting with […]', 'أكدت الممثّلة الخاصة للمملكة المتحدة آن سنو، الخميس 2 نيسان، أن الزيارة الأخيرة، التي أجراها السيد الرئيس أحمد الشرع، إلى لندن شكّلت محطة مفصلية في مسار العلاقات بين المملكة وسوريا. وقالت سنو في منشور عبر منصة “إكس” إن الزيارة تضمنت لقاءات عدة وجولة في البرلمان ومناقشات حول سيادة القانون والتعددية السياسية، إضافةً إلى لقاء مع الملك في قصر باكنغهام. وأشارت إلى مشاركتها في فعالية للاحتفاء بالتجارة بين سوريا والمملكة المتحدة، موضحةً أن حجم التبادل التجاري سجّل زيادة بنسبة 400 بالمئة مقارنة بالعام الماضي. وشدّدت سنو على التزام بلادها بدعم سوريا في إعادة بناء اقتصادها وتعزيز بيئة التجارة والاستثمار. وقالت: إن هذه الزيارة لم يكن من الممكن تصوّرها عند توليها مهامها عام 2023، مشيرةً إلى أن المرحلة الماضية شهدت تغيرات كبيرة أسهمت في إحداث تحوّل في العلاقات بين البلدين. وأعربت سنو عن تطلّعها لمواصلة تطوير هذه العلاقة والوقوف إلى جانب السوريين في ال', 'The Special Representative of the United Kingdom, Anne Snow, confirmed on Thursday, April 2, that the recent visit by President Ahmed Al-Sharaa to London constituted a turning point in the course of relations between the Kingdom and Syria. Snow said in a post on the “X” platform: The visit included several meetings, a tour of Parliament, discussions on the rule of law and political pluralism, in addition to a meeting with the King at Buckingham Palace. She referred to her participation in an event to celebrate trade between Syria and the United Kingdom, explaining that The volume of trade exchange recorded an increase of 400 percent compared to last year. Snow stressed her country''s commitment to supporting Syria in rebuilding its economy and enhancing the trade and investment environment. She said: This visit was unimaginable She will assume her duties in 2023, noting that the past period witnessed major changes that contributed to a transformation in relations between the two countries. Snow expressed her aspiration to continue developing this relationship and to stand by the Syrians in the country', 'https://alikhbariah.com/wp-content/uploads/2026/04/British-envoy-President-al-Sharaas-visit-to-London-is-a-pivotal-moment-in-relations-with-Syria.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T20:20:27+03:00'::timestamptz, false, true, false, 190),
  ('الرئيس الشرع يبحث مع عضو بالكونغرس الأوضاع الإقليمية والدولية', 'President Al-Sharaa discusses with a member of Congress the regional and international situation', 'بحث السيد الرئيس أحمد الشرع، مع عضو الكونغرس الأمريكي كوري لي ميلز، الأوضاع الإقليمية والدولية الراهنة، وعدداً من القضايا ذات الاهتمام المشترك. جاء ذلك خلال استقبال الرئيس الشرع، عضو الكونغرس في قصر الشعب بدمشق، الخميس 2 نيسان، وفق ما نشرت رئاسة الجمهورية على معرّفاتها الرسمية. وخلال الساعات الماضية، كان الرئيس الشرع قد ناقش مع وكيل […]', 'Mr. President Ahmed Al-Sharaa discussed, with US Congressman Corey Lee Mills, the current regional and international situations, and a number of issues of common interest. This came during President Al-Sharaa’s reception, a member of Congress, at the People’s Palace in Damascus, on Thursday April 2, according to what the Presidency of the Republic published on its official websites. During the past hours, President Al-Sharaa had discussed with the Undersecretary [...]', 'بحث السيد الرئيس أحمد الشرع، مع عضو الكونغرس الأمريكي كوري لي ميلز، الأوضاع الإقليمية والدولية الراهنة، وعدداً من القضايا ذات الاهتمام المشترك. جاء ذلك خلال استقبال الرئيس الشرع، عضو الكونغرس في قصر الشعب بدمشق، الخميس 2 نيسان، وفق ما نشرت رئاسة الجمهورية على معرّفاتها الرسمية. وخلال الساعات الماضية، كان الرئيس الشرع قد ناقش مع وكيل الأمين العام للأمم المتحدة للشؤون الإنسانية ومنسّق الإغاثة في حالات الطوارئ توم فيلتشر، آليات تطوير التنسيق بين الجهات المعنية ومنظمات الأمم المتحدة، بما يسهم في تحسين كفاءة العمل الإنساني في سوريا. وجرى النقاش خلال لقاء عقد في قصر الشعب بدمشق، بحضور وزير الخارجية والمغتربين أسعد الشيباني، والوفد المرافق لوكيل الأمين العام للأمم المتحدة، حيث تم التطرق إلى الواقع الإنساني وسبل التعامل مع التحدّيات الراهنة والحد من آثارها، بحسب ما نشرت رئاسة الجمهورية عبر معرّفاتها الرسمية. وكان الوفد الأممي، برئاسة فيلتشر، قد ب', 'Mr. President Ahmed Al-Sharaa discussed, with US Congressman Corey Lee Mills, the current regional and international situations, and a number of issues of common interest. This came during President Al-Sharaa’s reception, a member of Congress, at the People’s Palace in Damascus, on Thursday April 2, according to what the Presidency of the Republic published on its official websites. During the past hours, President Al-Sharaa had discussed with the United Nations Under-Secretary-General for Humanitarian Affairs and Emergency Relief Coordinator Tom Fletcher, mechanisms for developing... Coordination between concerned parties and United Nations organizations, which contributes to improving the efficiency of humanitarian work in Syria. The discussion took place during a meeting held at the People’s Palace in Damascus, in the presence of the Minister of Foreign Affairs and Expatriates, Asaad Al-Shaibani, and the delegation accompanying the Under-Secretary. The year of the United Nations, where the humanitarian reality and ways to deal with current challenges and limit their effects were addressed, according to what the Presidency of the Republic published through its official accounts. The UN delegation, headed by Felcher, had b', 'https://alikhbariah.com/wp-content/uploads/2026/04/President-Al-Sharaa-discusses-regional-and-international-issues-with-a-member-of-Congress.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T19:54:11+03:00'::timestamptz, false, true, false, 189),
  ('الأمم المتحدة: سوريا يمكن أن تتحول إلى قصة نجاح بدعم دولي', 'United Nations: Syria can turn into a success story with international support', 'قال مدير برنامج الأمم المتحدة الإنمائي ألكسندر دي كرو، الخميس 2 نيسان، إن سوريا قادرة على التحول إلى قصة نجاح في مرحلة ما بعد الحرب، إذا توفر الدعم الدولي بالوقوف إلى جانب الشعب السوري. وأشار دي كرو، في منشور له على منصة “إكس”، إلى أن المرحلة الحالية تتطلب زيادة الدعم التنموي، بما يتيح إعادة بناء […]', 'Director of the United Nations Development Programme, Alexander De Croo, said on Thursday, April 2, that Syria is capable of turning into a success story in the post-war phase, if international support is available to stand by the Syrian people. De Croo noted, in his post on: The “X” platform indicated that the current stage requires increased development support, allowing the rebuilding of […]', 'قال مدير برنامج الأمم المتحدة الإنمائي ألكسندر دي كرو، الخميس 2 نيسان، إن سوريا قادرة على التحول إلى قصة نجاح في مرحلة ما بعد الحرب، إذا توفر الدعم الدولي بالوقوف إلى جانب الشعب السوري. وأشار دي كرو، في منشور له على منصة “إكس” ، إلى أن المرحلة الحالية تتطلب زيادة الدعم التنموي، بما يتيح إعادة بناء البنية التحتية الأساسية، ولا سيما المستشفيات والمدارس، وتهيئة الظروف المناسبة لعودة السوريين إلى ديارهم بشكل آمن. وناقش السيد الرئيس أحمد الشرع، في وقت سابق من اليوم، مع وكيل الأمين العام للأمم المتحدة للشؤون الإنسانية ومنسق الإغاثة في حالات الطوارئ توم فليتشر، آليات تطوير التنسيق بين الجهات المعنية ومنظمات الأمم المتحدة، بما يسهم في تحسين كفاءة العمل الإنساني في سوريا. وكان الوفد الأممي، برئاسة فليتشر، قد بحث أمس خلال اجتماع في فندق داما روز بدمشق الأولويات الوطنية والرؤية الحكومية السورية ، وذلك في إطار مبادرة “سوريا بلا مخيمات”. وفي السياق، ا', 'Director of the United Nations Development Programme, Alexander De Croo, said on Thursday, April 2, that Syria is capable of turning into a success story in the post-war phase, if international support is available to stand by the Syrian people. De Croo noted, in his post on: The “X” platform noted that the current stage requires increased development support, allowing the rebuilding of basic infrastructure, especially hospitals and schools, and creating the appropriate conditions for the safe return of Syrians to their homes. Mr. President discussed Ahmed Al-Sharaa, earlier today, with the United Nations Under-Secretary-General for Humanitarian Affairs and Emergency Relief Coordinator Tom Fletcher, discussed mechanisms for developing coordination between concerned parties and United Nations organizations, which contributes to improving the efficiency of... Humanitarian work in Syria. Yesterday, during a meeting at the Dama Rose Hotel in Damascus, the UN delegation, headed by Fletcher, discussed national priorities and the Syrian government vision, within the framework of the “Syria Without Camps” initiative. In the context, A', 'https://alikhbariah.com/wp-content/uploads/2026/04/United-Nations-Development-Programme-Director.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T19:30:07+03:00'::timestamptz, false, false, false, 188),
  ('وزارة الخارجية والمغتربين ترحب بخطة الاحتياجات الإنسانية لعام 2026', 'The Ministry of Foreign Affairs and Expatriates welcomes the 2026 Humanitarian Needs Plan', 'رحّب مدير إدارة التعاون الدولي في وزارة الخارجية والمغتربين قتيبة قاديش، بخطة الاحتياجات الإنسانية والاستجابة لعام 2026 الخاصة بسوريا، التي أطلقها وكيل الأمين العام للأمم المتحدة للشؤون الإنسانية ومنسق الإغاثة في حالات الطوارئ توم فيلتشر. وأكد قاديش خلال لقاء صحفي، الخميس 2 نيسان، التزام الوزارة بالعمل والتشاور والتنسيق مع مؤسسات الدولة، بما يحافظ على سيادة […]', 'Director of the International Cooperation Department at the Ministry of Foreign Affairs and Expatriates, Qutaiba Qadish, welcomed the 2026 humanitarian needs and response plan for Syria, launched by the United Nations Under-Secretary-General for Humanitarian Affairs and Relief Coordinator in Emergency Situations. Emergency Tom Fletcher. During a press interview, Thursday, April 2, Kadish affirmed the ministry’s commitment to working, consulting, and coordinating with state institutions, in a way that preserves the sovereignty of […]', 'رحّب مدير إدارة التعاون الدولي في وزارة الخارجية والمغتربين قتيبة قاديش، بخطة الاحتياجات الإنسانية والاستجابة لعام 2026 الخاصة بسوريا، التي أطلقها وكيل الأمين العام للأمم المتحدة للشؤون الإنسانية ومنسق الإغاثة في حالات الطوارئ توم فيلتشر. وأكد قاديش خلال لقاء صحفي، الخميس 2 نيسان، التزام الوزارة بالعمل والتشاور والتنسيق مع مؤسسات الدولة، بما يحافظ على سيادة سوريا ووحدتها وسلامة أراضيها واستقلالها. وأشار إلى أن الزيارة المشتركة لتوم فيلتشر ومدير برنامج الأمم المتحدة الإنمائي ألكسندر دي كرو إلى دمشق، تمثل الأولى من نوعها التي يجتمع فيها رئيسا ركيزتي العمل الإنساني والتنموي في الأمم المتحدة، وتعكس التزاماً باتباع نهج أكثر تكاملاً في تقديم الدعم الدولي. ورحّب مدير إدارة التعاون الدولي بمواصلة تقديم الدعم الإنساني لتلبية الاحتياجات العاجلة، مع التأكيد على ضرورة أن يسهم العمل الإنساني في تحقيق أولويات التعافي المحددة وطنياً، وأن يتماشى معها. ود', 'Director of the International Cooperation Department at the Ministry of Foreign Affairs and Expatriates, Qutaiba Qadish, welcomed the 2026 humanitarian needs and response plan for Syria, launched by the United Nations Under-Secretary-General for Humanitarian Affairs and Relief Coordinator in Emergency Situations. Emergency Tom Fletcher. During a press interview, Thursday, April 2, Kadish affirmed the ministry’s commitment to working, consulting, and coordinating with state institutions, in a way that preserves Syria’s sovereignty, unity, territorial integrity, and independence. He noted that Tom''s joint visit Feltscher and UNDP Director Alexander De Croo to Damascus, representing the first of its kind in which the heads of the humanitarian and development pillars of the United Nations meet, and reflects a commitment to a more integrated approach in providing support. International. The Director of the International Cooperation Department welcomed the continued provision of humanitarian support to meet urgent needs, while emphasizing the need for humanitarian work to contribute to achieving nationally identified recovery priorities, and to be consistent with them. friendship', 'https://alikhbariah.com/wp-content/uploads/2026/04/Syrian-Ministry-of-Foreign-Affairs.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T18:45:47+03:00'::timestamptz, false, false, false, 187),
  ('محافظ السويداء يبحث مع القائم بأعمال سفارة فرنسا تعزيز الأمن والاستقرار', 'The Governor of Suwayda discusses with the Chargé d''Affaires of the French Embassy the strengthening of security and stability', 'التقى محافظ السويداء مصطفى البكور، الخميس 2 نيسان، مع القائم بأعمال سفارة فرنسا في سوريا جان باتيست فافر، لبحث سبل تعزيز الأمن والاستقرار في المحافظة، وآفاق تطوير التعاون المشترك في مختلف المجالات. وأكد الجانبان خلال اللقاء أهمية تكثيف الجهود بما يسهم في دعم الاستقرار، وترسيخ مقومات التعافي على المستويين المحلي والوطني، بحسب ما نشرت محافظة […]', 'On Thursday, April 2, the Governor of Suwayda, Mustafa Al-Bakour, met with the Chargé d''Affaires of the French Embassy in Syria, Jean-Baptiste Favre, to discuss ways to enhance security and stability in the governorate, and prospects for developing joint cooperation in various fields. Both sides confirmed during The meeting emphasized the importance of intensifying efforts to contribute to supporting stability and consolidating the elements of recovery at the local and national levels, according to what the Governorate […]', 'التقى محافظ السويداء مصطفى البكور، الخميس 2 نيسان، مع القائم بأعمال سفارة فرنسا في سوريا جان باتيست فافر، لبحث سبل تعزيز الأمن والاستقرار في المحافظة، وآفاق تطوير التعاون المشترك في مختلف المجالات. وأكد الجانبان خلال اللقاء أهمية تكثيف الجهود بما يسهم في دعم الاستقرار، وترسيخ مقومات التعافي على المستويين المحلي والوطني، بحسب ما نشرت محافظة السويداء عبر منصاتها الرسمية. وقال المحافظ إن تعزيز الوحدة الوطنية يشكّل الركيزة الأساسية لصون استقرار سوريا وسيادتها، مشدداً على ضرورة الحفاظ على تماسك النسيج الاجتماعي، وتعزيز قيم التآخي بين مختلف مكونات الشعب السوري. من جهته، جدّد القائم بالأعمال الفرنسي دعم بلاده لوحدة سوريا وسيادتها، مؤكداً موقف باريس الداعم لكل ما يسهم في تعزيز أمن واستقرار الأراضي السورية. وقال المحافظ في وقت سابق: “إن ملف السويداء يقترب من الانتهاء رغم وجود بعض المنغصات ومحاولات منع التقدم”، مشيراً إلى وجود مؤشرات لحلول في المحا', 'On Thursday, April 2, the Governor of Suwayda, Mustafa Al-Bakour, met with the Chargé d''Affaires of the French Embassy in Syria, Jean-Baptiste Favre, to discuss ways to enhance security and stability in the governorate, and prospects for developing joint cooperation in various fields. Both sides confirmed during The meeting emphasized the importance of intensifying efforts to contribute to supporting stability and consolidating the elements of recovery at the local and national levels, according to what Suwayda Governorate published on its official platforms. The governor said that strengthening national unity constitutes the basic foundation of safeguarding Syria''s stability and sovereignty, stressing the need to maintain the cohesion of the social fabric and enhance the values ​​of brotherhood among the various components of the Syrian people. For his part, the French Chargé d''Affaires renewed his country''s support for Syria''s unity and sovereignty, stressing Paris'' supportive position For everything that contributes to enhancing the security and stability of the Syrian territories. The governor said earlier: “The As-Suwayda file is close to being completed, despite the presence of some problems and attempts to prevent progress,” noting that there are indicators of solutions in the area.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Syrian-French-meeting-to-discuss-joint-aid-cooperation-2.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T18:00:38+03:00'::timestamptz, false, false, false, 186),
  ('توغل وإطلاق نار.. اعتداءات جديدة لجيش الاحتلال الإسرائيلي في ريف القنيطرة الغربي', 'Incursion and shooting... new attacks by the Israeli occupation army in the western countryside of Quneitra', 'توغل جيش الاحتلال الإسرائيلي، الخميس 2 نيسان، برتل يضم أربع آليات وجرافة في شمال قرية الأصبح بريف القنيطرة الجنوبي. وفي التفاصيل، أفاد مراسل الإخبارية بأن جيش الاحتلال نصب حاجزاً وأغلق الطريق بساتر ترابي، إضافة إلى قيامه بإطلاق النار لترويع المدنيين. وفي السياق، أضاف المراسل أن جيش الاحتلال منع مرور المدنيين عبر الطريق الذي يصل إلى […]', 'On Thursday, April 2, the Israeli occupation army entered a convoy of four vehicles and a bulldozer north of the village of Al-Asbah in the southern countryside of Quneitra. In detail, Al-Ekhbariya correspondent reported that the occupation army set up a checkpoint and closed the road with a dirt berm, in addition to He opened fire to terrorize civilians. In this context, the correspondent added that the occupation army prevented civilians from passing through the road that reaches […]', 'توغل جيش الاحتلال الإسرائيلي، الخميس 2 نيسان، برتل يضم أربع آليات وجرافة في شمال قرية الأصبح بريف القنيطرة الجنوبي. وفي التفاصيل، أفاد مراسل الإخبارية بأن جيش الاحتلال نصب حاجزاً وأغلق الطريق بساتر ترابي، إضافة إلى قيامه بإطلاق النار لترويع المدنيين. وفي السياق، أضاف المراسل أن جيش الاحتلال منع مرور المدنيين عبر الطريق الذي يصل إلى بلدة كودنة بالقرب من تل الأحمر الغربي. وقالت مديرية إعلام القنيطرة إن جيش الاحتلال قام بإغلاق طريق رويحينة المؤدي إلى الأراضي الزراعية غرب القرية، إضافة إلى طريق أم العظام الشولي في ريف القنيطرة الغربي، مستخدماً السواتر الترابية. وكان جيش الاحتلال الإسرائيلي قد اعتقل، الإثنين 30 آذار الماضي، شاباً من قرية الأصبح في ريف القنيطرة الجنوبي. وأفاد مراسل الإخبارية حينها أن جيش الاحتلال الإسرائيلي اعتقل الشاب من قرية الأصبح في ريف القنيطرة أثناء رعيه الأغنام. ويواصل جيش الاحتلال الإسرائيلي اعتداءاته وخرقه اتفاق فض الا', 'On Thursday, April 2, the Israeli occupation army entered a convoy of four vehicles and a bulldozer north of the village of Al-Asbah in the southern countryside of Quneitra. In detail, Al-Ekhbariya correspondent reported that the occupation army set up a checkpoint and closed the road with a dirt berm, in addition to He opened fire to terrorize civilians. In this context, the reporter added that the occupation army prevented civilians from passing through the road that reaches the town of Kudna near Tal al-Ahmar al-Gharbi. The Quneitra Information Directorate said that the occupation army closed a road Ruwayhina, which leads to agricultural lands west of the village, in addition to the Umm al-Azm al-Shuli road in the western countryside of Quneitra, using dirt berms. On Monday, March 30, the Israeli occupation army arrested a young man from the village of Al-Asbah in Southern Quneitra countryside. An Al-Ekhbariya correspondent reported at the time that the Israeli occupation army arrested the young man from the village of Al-Asbah in the Quneitra countryside while he was herding sheep. The Israeli occupation army continues its attacks and violations of the dispersal agreement', 'https://alikhbariah.com/wp-content/uploads/2026/02/Israeli-occupation-16.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T17:47:44+03:00'::timestamptz, false, false, false, 185),
  ('رئيس الهيئة العامة للمنافذ والجمارك يفتتح منفذ التنف – الوليد الحدودي مع العراق', 'The head of the General Authority of Ports and Customs opens the Al-Tanf - Al-Walid border crossing with Iraq', 'افتتح رئيس الهيئة العامة للمنافذ والجمارك قتيبة بدوي، الخميس 2 نيسان، منفذ التنف – الوليد الحدودي، بمشاركة رئيس هيئة المنافذ الحدودية العراقي عمر عدنان الوائلي والوفد المرافق له. وقال بدوي في منشور عبر منصة “إكس“: “افتتاح منفذ التنف – الوليد اليوم مع الأشقاء في جمهورية العراق يشكل خطوة مهمة في مسار تعزيز التعاون المشترك وتفعيل […]', 'On Thursday, April 2, the head of the General Authority of Ports and Customs, Qutaiba Badawi, opened the Al-Tanf-Al-Walid border crossing, with the participation of the head of the Iraqi Border Ports Authority, Omar Adnan Al-Waeli, and his accompanying delegation. Badawi said in a post on the “X” platform: “The opening of the Al-Tanf-Al-Waleed crossing today with our brothers in the Republic of Iraq constitutes an important step in the path of strengthening joint cooperation and activating […]', 'افتتح رئيس الهيئة العامة للمنافذ والجمارك قتيبة بدوي، الخميس 2 نيسان، منفذ التنف – الوليد الحدودي، بمشاركة رئيس هيئة المنافذ الحدودية العراقي عمر عدنان الوائلي والوفد المرافق له. وقال بدوي في منشور عبر منصة “ إكس “: “افتتاح منفذ التنف – الوليد اليوم مع الأشقاء في جمهورية العراق يشكل خطوة مهمة في مسار تعزيز التعاون المشترك وتفعيل حركة الترانزيت بين بلدينا، ونعمل على تأمين انسيابية عالية لحركة القوافل، ورفع جاهزية المنفذ بما يواكب متطلبات المرحلة، ويسهم في دعم حركة التجارة والطاقة عبر الأراضي السورية”. من جانبه، قال مدير العلاقات في الهيئة العامة للمنافذ والجمارك مازن علوش: إن الجانبين أكدا على أهمية المنفذ الحيوي في دعم حركة التبادل التجاري، وتأمين انسيابية عبور البضائع والطاقة. وأكد علوش أن افتتاح المنفذ يُعد خطوة استراتيجية لتفعيل المنافذ الحدودية، بما يعزز دور سوريا كممر رئيسي لحركة الترانزيت في المنطقة. وكانت الهيئة العامة للمنافذ والج', 'On Thursday, April 2, the head of the General Authority of Ports and Customs, Qutaiba Badawi, opened the Al-Tanf-Al-Walid border crossing, with the participation of the head of the Iraqi Border Ports Authority, Omar Adnan Al-Waeli, and his accompanying delegation. Badawi said in a post on the “X” platform: “The opening of the Al-Tanf-Al-Waleed port today with our brothers in the Republic of Iraq constitutes an important step in the path of strengthening joint cooperation and activating transit movement between our two countries. We are working to ensure a high flow of convoy movement and raise the readiness of the port in line with requirements of the stage, and contributes to supporting the movement of trade and energy through Syrian territory.” For his part, the Director of Relations at the General Authority of Ports and Customs, Mazen Alloush, said: The two sides stressed the importance of the vital port in supporting the movement of trade exchange. And ensuring the smooth transit of goods and energy. Alloush stressed that the opening of the port is a strategic step to activate the border crossings, thus enhancing Syria’s role as a major transit corridor in the region. The General Authority for Ports and Tourism was', 'https://alikhbariah.com/wp-content/uploads/2026/04/Al-Tanf-border-crossing.webp', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T17:30:36+03:00'::timestamptz, false, false, false, 184),
  ('وزارة الخارجية والمغتربين تحدد 4 أولويات للتعافي في سوريا وخطة الاستجابة لعام 2026', 'The Ministry of Foreign Affairs and Expatriates sets 4 priorities for recovery in Syria and the response plan for 2026', 'أعلن مدير إدارة التعاون الدولي في وزارة الخارجية والمغتربين قتيبة قاديش، الخميس 2 نيسان، عن تحديد أربعة مجالات ذات أولوية للتعافي في سوريا وخطة الاستجابة للاحتياجات الإنسانية لعام 2026. وشملت المجالات التي حددت: استعادة البنية التحتية، وإعادة بناء المؤسسات العامة، والصمود الاجتماعي، وإزالة الألغام. وأوضح قاديش أن بيان أولويات التعافي في سوريا وخطة الاستجابة للاحتياجات […]', 'On Thursday, April 2, Director of the International Cooperation Department at the Ministry of Foreign Affairs and Expatriates, Qutaiba Kadish, announced the identification of four priority areas for recovery in Syria and the humanitarian needs response plan for 2026. The areas identified included: Infrastructure, rebuilding public institutions, social resilience, and mine clearance. Kadish explained that the statement of recovery priorities in Syria and the plan to respond to the needs […]', 'أعلن مدير إدارة التعاون الدولي في وزارة الخارجية والمغتربين قتيبة قاديش، الخميس 2 نيسان، عن تحديد أربعة مجالات ذات أولوية للتعافي في سوريا وخطة الاستجابة للاحتياجات الإنسانية لعام 2026. وشملت المجالات التي حددت : استعادة البنية التحتية، وإعادة بناء المؤسسات العامة، والصمود الاجتماعي، وإزالة الألغام. وأوضح قاديش أن بيان أولويات التعافي في سوريا وخطة الاستجابة للاحتياجات الإنسانية لعام 2026 يحددان أربعة مجالات رئيسية ذات أولوية، وهي: استعادة البنية التحتية الحيوية، واستئناف الخدمات الأساسية، وتعزيز الصمود الاجتماعي والاقتصادي، وإعادة بناء المؤسسات العامة. وأضاف أن هذه الجهود تسير بالتوازي مع أعمال إزالة الألغام والمواد المتفجرة ومخلفات الحرب، بهدف تهيئة البيئة الآمنة لعملية التعافي الشامل في سوريا. وأعرب مدير إدارة التعاون الدولي في الوزارة عن ترحيب سوريا بخطة الاحتياجات الإنسانية والاستجابة لعام 2026 الخاصة بها، والتي أطلقها وكيل الأمين ال', 'On Thursday, April 2, Director of the International Cooperation Department at the Ministry of Foreign Affairs and Expatriates, Qutaiba Kadish, announced the identification of four priority areas for recovery in Syria and the humanitarian needs response plan for 2026. The areas identified included: Infrastructure restoration, rebuilding public institutions, social resilience, and mine clearance. Kadish explained that the Statement of Recovery Priorities in Syria and the 2026 Humanitarian Needs Response Plan identify four main priority areas, These are: restoring vital infrastructure, resuming basic services, enhancing social and economic resilience, and rebuilding public institutions. He added that these efforts go in parallel with the work of removing mines, explosive materials and remnants of war. With the aim of creating a safe environment for the comprehensive recovery process in Syria. The Director of the Ministry''s International Cooperation Department expressed Syria''s welcome of its 2026 humanitarian needs and response plan, which was launched by the Under-Secretary.', 'https://alikhbariah.com/wp-content/uploads/2026/04/The-Ministry-of-Foreign-Affairs-and-Expatriates-discusses-recovery-priorities-in-Syria.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T16:30:11+03:00'::timestamptz, false, false, false, 183),
  ('سوريا والمجر تبحثان تعزيز التعاون في الطيران المدني', 'Syria and Hungary are discussing enhancing cooperation in civil aviation', 'التقى رئيس الهيئة العامة للطيران المدني والنقل الجوي عمر الحصري، الخميس 2 نيسان، مع القائم بأعمال سفارة المجر في دمشق أشتفان جيولاشوش، لبحث سبل تعزيز التعاون الثنائي في مجال الطيران المدني. وتناول اللقاء آفاق تطوير العلاقات المشتركة بين البلدين، بما يخدم مصالح الجانبين، ويسهم في دعم قطاع النقل الجوي وتطويره، بحسب ما نشرت الهيئة العامة […]', 'The head of the General Authority of Civil Aviation and Air Transport, Omar Al-Husri, met on Thursday, April 2, with the Chargé d''Affaires of the Embassy of Hungary in Damascus, István Gyulasz, to discuss ways to enhance bilateral cooperation in the field of civil aviation. The meeting discussed development prospects The joint relations between the two countries, in a way that serves the interests of both sides, and contributes to supporting and developing the air transport sector, according to what was published by the General Authority […]', 'التقى رئيس الهيئة العامة للطيران المدني والنقل الجوي عمر الحصري، الخميس 2 نيسان، مع القائم بأعمال سفارة المجر في دمشق أشتفان جيولاشوش، لبحث سبل تعزيز التعاون الثنائي في مجال الطيران المدني. وتناول اللقاء آفاق تطوير العلاقات المشتركة بين البلدين، بما يخدم مصالح الجانبين، ويسهم في دعم قطاع النقل الجوي وتطويره، بحسب ما نشرت الهيئة العامة للطيران المدني عبر معرفاتها الرسمية. وكانت سوريا وقعت، في 30 آذار، بحضور السيد الرئيس أحمد الشرع، اتفاقية تعاون في مجال النقل الجوي مع جمهورية ألمانيا الاتحادية في العاصمة برلين وذلك بهدف تعزيز التعاون وتوسيع الشراكات بين البلدين. وسبق أن ناقش الحصري، مع القائم بأعمال سفارة أذربيجان في دمشق، ألنور شاه حسينوف، في 4 آذار، آفاق تطوير التعاون المشترك بين البلدين في مجالات الطيران المدني والنقل الجوي. وكانت الهيئة العامة للطيران المدني والنقل الجوي في سوريا قد وقعت، بتاريخ 13 شباط، مذكرة تفاهم مع كلية الملكة نور ', 'The head of the General Authority of Civil Aviation and Air Transport, Omar Al-Husri, met on Thursday, April 2, with the Chargé d''Affaires of the Embassy of Hungary in Damascus, István Gyulasz, to discuss ways to enhance bilateral cooperation in the field of civil aviation. The meeting discussed development prospects The joint relations between the two countries, in a way that serves the interests of both sides, and contributes to supporting and developing the air transport sector, according to what the General Authority of Civil Aviation published through its official accounts. Syria signed, on March 30, in the presence of Mr. President Ahmed Al-Sharaa, A cooperation agreement in the field of air transport with the Federal Republic of Germany in the capital, Berlin, with the aim of enhancing cooperation and expanding partnerships between the two countries. Al-Husri previously discussed with the Chargé d''Affairs of the Azerbaijani Embassy in Damascus, Alnur Shahhuseynov, on 4 March: Prospects for developing joint cooperation between the two countries in the fields of civil aviation and air transport. On February 13, the General Authority of Civil Aviation and Air Transport in Syria signed a memorandum of understanding with Queen Noor College.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Civil-Aviation-Development-Research.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T16:00:53+03:00'::timestamptz, false, false, false, 182),
  ('مباحثات سورية – أردنية لتعزيز التعاون وتبادل الخبرات في مجال البريد', 'Syrian-Jordanian discussions to enhance cooperation and exchange of experiences in the field of mail', 'زار وفد من شركة البريد الأردني برئاسة رئيس مجلس الإدارة سامي الداوود، والمدير العام هنادي الطيب، المؤسسة السورية للبريد، لبحث تعزيز التعاون وتبادل الخبرات والاطلاع على واقع العمل البريدي في سوريا. وشهدت الزيارة لقاء مع وزير الاتصالات وتقانة المعلومات عبد السلام هيكل، بحضور سفير المملكة الأردنية الهاشمية في دمشق سفيان القضاة، ومدير عام المؤسسة السورية […]', 'A delegation from the Jordan Post Company, headed by Chairman of the Board of Directors, Sami Al-Daoud, and General Manager, Hanadi Al-Tayeb, visited the Syrian Postal Corporation, to discuss enhancing cooperation, exchanging experiences, and learning about the reality of postal work in Syria. The visit included a meeting with Minister of Communications and Information Technology, Abdul Salam Heikal, in the presence of the Ambassador of the Hashemite Kingdom of Jordan in Damascus, Sufyan Al-Qudah, and the Director General of the Syrian Foundation […]', 'زار وفد من شركة البريد الأردني برئاسة رئيس مجلس الإدارة سامي الداوود، والمدير العام هنادي الطيب، المؤسسة السورية للبريد، لبحث تعزيز التعاون وتبادل الخبرات والاطلاع على واقع العمل البريدي في سوريا. وشهدت الزيارة لقاء مع وزير الاتصالات وتقانة المعلومات عبد السلام هيكل، بحضور سفير المملكة الأردنية الهاشمية في دمشق سفيان القضاة، ومدير عام المؤسسة السورية للبريد عماد الدين حمد، بحسب ما نشرت المؤسسة السورية للبريد عبر معرفاتها الرسمية الأربعاء 1 نيسان. وجرى نقاش واقع المؤسسة وسبل تطويرها وبناء القدرات وتنفيذ برامج تدريبية والاستفادة من التجربة الأردنية في التدريب والتجارة الإلكترونية. كما عقد اجتماع عمل برئاسة مدير عام المؤسسة السورية للبريد، تم خلاله عرض الخطط المستقبلية، إلى جانب تنفيذ زيارة ميدانية للصالة المركزية بدمشق ومتحف الطوابع، حيث أبدى الوفد اهتماماً بالخدمات والمقتنيات. وأكد رئيس مجلس إدارة شركة البريد الأردني سامي الداوود أن الزيار', 'A delegation from the Jordan Post Company, headed by Chairman of the Board of Directors, Sami Al-Daoud, and General Manager, Hanadi Al-Tayeb, visited the Syrian Postal Corporation, to discuss enhancing cooperation, exchanging experiences, and learning about the reality of postal work in Syria. The visit included a meeting with Minister of Communications and Information Technology, Abdul Salam Heikal, in the presence of the Ambassador of the Hashemite Kingdom of Jordan in Damascus, Sufyan Al-Qudah, and the Director General of the Syrian Postal Corporation, Imad al-Din Hamad, according to what the Syrian Postal Corporation published through its official accounts. Wednesday, April 1. The reality of the institution and ways to develop it, build capabilities, implement training programs, and benefit from the Jordanian experience in training and e-commerce were discussed. A working meeting was also held under the chairmanship of the Director General of the Syrian Postal Corporation During which, future plans were presented, in addition to carrying out a field visit to the central hall in Damascus and the Stamp Museum, where the delegation expressed interest in the services and collectibles. Chairman of the Board of Directors of the Jordan Post Company, Sami Al-Dawoud, confirmed that the visit', 'https://alikhbariah.com/wp-content/uploads/2026/04/Syrian-Jordanian-talks-to-enhance-cooperation-and-exchange-expertise-in-the-postal-sector.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T22:39:04+03:00'::timestamptz, false, false, false, 181),
  ('هيئة دعم وتنمية الإنتاج المحلي والصادرات تطلق السجل الوطني للتصدير', 'The Authority for Support and Development of Local Production and Exports launches the National Export Register', 'أعلنت هيئة دعم وتنمية الإنتاج المحلي والصادرات، الجمعة 3 نيسان، عن الإطلاق الرسمي للسجل الوطني للتصدير، وذلك لتنظيم قطاع التصدير وضبط بيانات المصدرين، مع تحديد مهلة تنتهي في 30 حزيران القادم لتسجيل البيانات. ودعت الهيئة كافة المصدرين للمبادرة بالتسجيل خلال المهلة المحددة، مؤكدة أنه لن يُسمح لأي شخص أو شركة بمزاولة التصدير بعد انتهاء المهلة […]', 'The Authority for Support and Development of Local Production and Exports announced, on Friday, April 3, the official launch of the National Export Register, in order to organize the export sector and control exporters’ data, setting a deadline of next June 30 to register data. The authority called All exporters of the initiative must register within the specified deadline, stressing that no person or company will be allowed to engage in exports after the expiration of the deadline […]', 'أعلنت هيئة دعم وتنمية الإنتاج المحلي والصادرات، الجمعة 3 نيسان، عن الإطلاق الرسمي للسجل الوطني للتصدير، وذلك لتنظيم قطاع التصدير وضبط بيانات المصدرين، مع تحديد مهلة تنتهي في 30 حزيران القادم لتسجيل البيانات. ودعت الهيئة كافة المصدرين للمبادرة بالتسجيل خلال المهلة المحددة، مؤكدة أنه لن يُسمح لأي شخص أو شركة بمزاولة التصدير بعد انتهاء المهلة ما لم يتم تجديد القيد وفق الأصول المعتمدة، بحسب ما نشرت وزارة الاقتصاد والصناعة عبر معرفاتها الرسمية. وأوضحت أن عملية التسجيل تستوجب تعبئة كافة البيانات المطلوبة إلكترونياً ورفع نسخ إلكترونية للوثائق التي تشمل: صورة مصدقة حديثة عن السجل التجاري بالنسبة للمصدر بالنيابة عن الغير، وصورة مصدقة حديثة عن السجل الصناعي للمصدر المنتج، بالإضافة إلى وثيقة عضوية في غرفة التجارة والصناعة حسب التخصص وصورة عن الهوية الشخصية للمالك. وحددت الهيئة رسم التسجيل بخمسين ألف ليرة سورية بالعملة الجديد، يتم تسديدها عبر منظومة ', 'The Authority for Support and Development of Local Production and Exports announced, on Friday, April 3, the official launch of the National Export Register, in order to organize the export sector and control exporters’ data, setting a deadline of next June 30 to register data. The authority called All exporters of the initiative are required to register within the specified deadline, stressing that no person or company will be allowed to engage in exports after the expiry of the deadline unless the registration is renewed in accordance with the approved procedures, according to what the Ministry of Economy and Industry published through its identifiers. Official. She explained that the registration process requires filling out all the required data electronically and uploading electronic copies of the documents that include: a recent certified copy of the commercial registry for the exporter on behalf of others, and a recent certified copy of the registry. Industrial certificate for the product source, in addition to a membership document in the Chamber of Commerce and Industry according to specialty and a copy of the owner’s personal ID. The authority set the registration fee at fifty thousand Syrian pounds in the new currency, to be paid through the system', 'https://alikhbariah.com/wp-content/uploads/2026/04/Syrian-Authority-for-Supporting-and-Developing-Local-Production-and-Exports.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T11:12:31+03:00'::timestamptz, false, true, false, 180),
  ('الاتحاد الأوروبي: أسعار الطاقة ستبقى مرتفعة لفترة طويلة بسبب صراع الشرق الأوسط', 'European Union: Energy prices will remain high for a long time due to the Middle East conflict', 'أعلن الاتحاد الأوروبي، الجمعة 3 نيسان، أن أسعار الطاقة ستبقى مرتفعة لفترة زمنية طويلة بسبب الصراع في الشرق الأوسط. وأكد مفوض الطاقة بالاتحاد الأوروبي دان يورغنسن، في تصريح نقلته صحيفة فايننشال تايمز، أن أسعار الطاقة ستبقى مرتفعة لفترة زمنية طويلة جداً، مشدداً على أن الاتحاد الأوروبي يستعد لأسوأ السيناريوهات المحتملة جراء الصراع في الشرق الأوسط. […]', 'The European Union announced, on Friday, April 3, that energy prices will remain high for a long period of time due to the conflict in the Middle East. European Union Energy Commissioner Dan Jorgensen confirmed, in a statement reported by the Financial Times, that energy prices... It will remain high for a very long period of time, stressing that the European Union is preparing for the worst possible scenarios resulting from the conflict in the Middle East. […]', 'أعلن الاتحاد الأوروبي، الجمعة 3 نيسان، أن أسعار الطاقة ستبقى مرتفعة لفترة زمنية طويلة بسبب الصراع في الشرق الأوسط. وأكد مفوض الطاقة بالاتحاد الأوروبي دان يورغنسن، في تصريح نقلته صحيفة فايننشال تايمز، أن أسعار الطاقة ستبقى مرتفعة لفترة زمنية طويلة جداً، مشدداً على أن الاتحاد الأوروبي يستعد لأسوأ السيناريوهات المحتملة جراء الصراع في الشرق الأوسط. وكان المدير التنفيذي لوكالة الطاقة الدولية فاتح بيرول قد أعلن أن الأزمة الحالية في الشرق الأوسط أدت إلى خسارة أكثر من 12 مليون برميل يومياً من إمدادات النفط حتى الآن. وقال بيرول، الأربعاء 1 نيسان: إن هذه الأزمة تعد “أسوأ من أزمتي النفط في السبعينيات وفقدان الغاز الروسي عام 2022 مجتمعتين”، لافتاً إلى تضرر نحو 40 من أصول الطاقة الرئيسية في المنطقة. وأوضح أن الخسائر في إنتاج النفط قد تتفاقم في شهر نيسان مقارنة بمستوياتها في شهر آذار الماضي. وفي 23 آذار الفائت، قال بيرول: إن الاقتصاد العالمي يواجه اليو', 'The European Union announced, on Friday, April 3, that energy prices will remain high for a long period of time due to the conflict in the Middle East. European Union Energy Commissioner Dan Jorgensen confirmed, in a statement reported by the Financial Times, that energy prices... It will remain high for a very long period of time, stressing that the European Union is preparing for the worst possible scenarios resulting from the conflict in the Middle East. The Executive Director of the International Energy Agency, Fatih Birol, announced that the current crisis is in the East The Middle East region has led to a loss of more than 12 million barrels per day of oil supplies so far. Birol said, on Wednesday, April 1: This crisis is “worse than the two oil crises in the 1970s and the loss of Russian gas in 2022 combined,” pointing out that... About 40 major energy assets in the region. He explained that losses in oil production may worsen in April compared to their levels last March. Last March 23, Birol said: The global economy is facing the crisis', 'https://alikhbariah.com/wp-content/uploads/2026/04/Energy.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T10:30:00+03:00'::timestamptz, false, true, false, 179),
  ('تجارة دمشق تعترض على رسوم الحماية الأردنية: تحدّ من تنافسية الصادرات السورية', 'Damascus trade objects to Jordanian protection fees: they limit the competitiveness of Syrian exports', 'اعترضت غرفة تجارة دمشق على الرسوم التي فرضتها المملكة الأردنية الهاشمية على بعض المنتجات السورية، وخاصة في قطاعات الصناعات الغذائية والمنسوجات. وأكدت الغرفة في بيان لها، الخميس 2 نيسان، أن ارتفاع هذه الرسوم يحد بشكل واضح من القدرة التنافسية للصادرات السورية ويعيق دخولها إلى السوق الأردنية بالشكل المطلوب. وأوضحت أن الرسوم المفروضة تؤثر سلباً على […]', 'The Damascus Chamber of Commerce objected to the fees imposed by the Hashemite Kingdom of Jordan on some Syrian products, especially in the food and textile industries sectors. The Chamber confirmed in a statement, Thursday, April 2, that the increase in these fees is limited It is clear from the competitiveness of Syrian exports and hinders their entry into the Jordanian market as required. She explained that the imposed fees negatively affect [...]', 'اعترضت غرفة تجارة دمشق على الرسوم التي فرضتها المملكة الأردنية الهاشمية على بعض المنتجات السورية، وخاصة في قطاعات الصناعات الغذائية والمنسوجات. وأكدت الغرفة في بيان لها، الخميس 2 نيسان، أن ارتفاع هذه الرسوم يحد بشكل واضح من القدرة التنافسية للصادرات السورية ويعيق دخولها إلى السوق الأردنية بالشكل المطلوب. وأوضحت أن الرسوم المفروضة تؤثر سلباً على حركة التجارة، وتحد من فرص الشركات السورية في الاستفادة من السوق الأردنية، مشددة على أنها ستتابع الملف مع الجهات المعنية في الأردن عبر القنوات الرسمية واللقاءات الاقتصادية للوصول إلى صيغة متوازنة تحقق مصالح المصدرين السوريين. ورحّبت الغرفة في الوقت نفسه بالسماح بدخول المنتجات السورية إلى السوق الأردنية، مؤكدة أهمية فتح الأسواق أمام المنتجات الوطنية، لتوفير فرص للشركات السورية، وتعزيز نشاط القطاع التجاري والصناعي. وأعلنت وزارة الصناعة والتجارة والتموين الأردنية، أمس الأربعاء، السماح بدخول منتجات سوري', 'The Damascus Chamber of Commerce objected to the fees imposed by the Hashemite Kingdom of Jordan on some Syrian products, especially in the food and textile industries sectors. The Chamber confirmed in a statement, Thursday, April 2, that the increase in these fees is limited It is clear from the competitiveness of Syrian exports and hinders their entry into the Jordanian market as required. She explained that the imposed fees negatively affect the movement of trade and limit the opportunities of Syrian companies to benefit from the Jordanian market, stressing that they The file will be followed up with the relevant authorities in Jordan through official channels and economic meetings to reach a balanced formula that achieves the interests of Syrian exporters. At the same time, the Chamber welcomed allowing Syrian products to enter the Jordanian market. Emphasizing the importance of opening markets to national products, to provide opportunities for Syrian companies, and to enhance the activity of the commercial and industrial sector. Yesterday, Wednesday, the Jordanian Ministry of Industry, Trade and Supply announced allowing the entry of Syrian products', 'https://alikhbariah.com/wp-content/uploads/2026/04/Damascus-Chamber-of-Commerce.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T17:23:05+03:00'::timestamptz, false, false, false, 178),
  ('وزير الطاقة يبحث مع وزير النفط العراقي آليات بدء تصدير النفط عبر الأراضي السورية', 'The Minister of Energy discusses with the Iraqi Oil Minister the mechanisms for starting oil exports through Syrian territory', 'أجرى وزير الطاقة محمد البشير، الخميس 2 نيسان، اتصالاً هاتفياً مع وزير النفط العراقي حيان عبد الغني، بحثا خلاله آليات بدء تصدير النفط العراقي عبر الأراضي السورية. وبحسب ما نشرت وزارة الطاقة عبر معرفاتها الرسمية، فقد ناقش الجانبان توريد الغاز المنزلي إلى سوريا، وتأهيل خط كركوك – بانياس، في خطوة تعكس عمق التعاون المشترك بين […]', 'On Thursday, April 2, Energy Minister Muhammad al-Bashir made a phone call with Iraqi Oil Minister Hayan Abdul-Ghani, during which they discussed mechanisms for starting the export of Iraqi oil through Syrian territory. According to what the Ministry of Energy published through its official accounts, he discussed The two sides supply domestic gas to Syria, and rehabilitate the Kirkuk-Baniyas line, in a step that reflects the depth of joint cooperation between […]', 'أجرى وزير الطاقة محمد البشير، الخميس 2 نيسان، اتصالاً هاتفياً مع وزير النفط العراقي حيان عبد الغني، بحثا خلاله آليات بدء تصدير النفط العراقي عبر الأراضي السورية. وبحسب ما نشرت وزارة الطاقة عبر معرفاتها الرسمية، فقد ناقش الجانبان توريد الغاز المنزلي إلى سوريا، وتأهيل خط كركوك – بانياس، في خطوة تعكس عمق التعاون المشترك بين البلدين. وأشاد الوزيران خلال الاتصال بالجهود المشتركة والمتضافرة لبدء تصدير النفط العراقي عبر أراضي الجمهورية العربية السورية. كما بحث الجانبان سبل تعزيز التعاون في قطاع الطاقة بما يحقق المصالح المشتركة ويخدم الشعبين الشقيقين. وناقش الوزيران إمكانية توريد الغاز المنزلي إلى سوريا في إطار تعزيز أمن الطاقة وتلبية الاحتياجات المحلية، وبحثا إعادة تأهيل أنابيب نقل النفط، ولا سيما خط كركوك – بانياس، بما يسهم في تطوير وتعزيز عملية تصدير النفط. من جانبه، بين وزير النفط العراقي أن هذا التعاون سيستمر بشكل مستدام ولن يكون مرتبطاً بال', 'On Thursday, April 2, Energy Minister Muhammad al-Bashir made a phone call with Iraqi Oil Minister Hayan Abdul-Ghani, during which they discussed mechanisms for starting the export of Iraqi oil through Syrian territory. According to what the Ministry of Energy published through its official accounts, he discussed The two sides supply domestic gas to Syria, and rehabilitate the Kirkuk-Baniyas line, in a step that reflects the depth of joint cooperation between the two countries. During the call, the two ministers praised the joint and concerted efforts to begin exporting Iraqi oil through the territory of the Republic Syrian Arabic. The two sides also discussed ways to enhance cooperation in the energy sector in a way that achieves common interests and serves the two brotherly peoples. The two ministers discussed the possibility of supplying domestic gas to Syria within the framework of enhancing energy security and meeting needs Locally, they discussed the rehabilitation of oil transport pipelines, especially the Kirkuk-Baniyas line, which contributes to developing and enhancing the oil export process. For his part, the Iraqi Oil Minister stated that this cooperation will continue in a sustainable manner and will not be linked to...', 'https://alikhbariah.com/wp-content/uploads/2026/01/Minister-of-Energy.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T14:00:58+03:00'::timestamptz, false, false, false, 177),
  ('أسعار النفط ترتفع إلى 108 دولارات للبرميل بعد خطاب ترامب', 'Oil prices rise to $108 a barrel after Trump''s speech', 'ارتفعت أسعار النفط، الخميس 2 نيسان، إلى أكثر من 6 بالمئة لتصل إلى 108 دولارات للبرميل بعد خطاب الرئيس الأمريكي دونالد ترامب، وفقاً لوكالة أسوشيتد برس الأمريكية. وكان ترامب وجه، في وقت سابق من اليوم، خطاباً للشعب الأمريكي بشأن الحرب على إيران، مؤكداً أن الأهداف الاستراتيجية اقتربت من التحقق، لكنه لم يحدد موعداً لنهاية الحرب. […]', 'On Thursday, April 2, oil prices rose by more than 6 percent, reaching $108 a barrel, after US President Donald Trump’s speech, according to the American Associated Press. Earlier today, Trump addressed the people US Secretary of State regarding the war on Iran, stressing that the strategic goals are close to being achieved, but he did not set a date for the end of the war. […]', 'ارتفعت أسعار النفط، الخميس 2 نيسان، إلى أكثر من 6 بالمئة لتصل إلى 108 دولارات للبرميل بعد خطاب الرئيس الأمريكي دونالد ترامب، وفقاً لوكالة أسوشيتد برس الأمريكية. وكان ترامب وجه، في وقت سابق من اليوم، خطاباً للشعب الأمريكي بشأن الحرب على إيران، مؤكداً أن الأهداف الاستراتيجية اقتربت من التحقق، لكنه لم يحدد موعداً لنهاية الحرب. ولفت في خطابه إلى أن الارتفاع الأخير في أسعار البنزين داخل الولايات المتحدة هو زيادة قصيرة الأمد، محمّلاً النظام الإيراني المسؤولية عن ارتفاع أسعار الوقود بسبب “هجماته الجنونية” على ناقلات النفط. ودعا ترامب دول العالم التي تستورد النفط عبر مضيق هرمز إلى تحمّل مسؤولية حماية هذا الممر الملاحي.', 'On Thursday, April 2, oil prices rose by more than 6 percent, reaching $108 a barrel, after US President Donald Trump’s speech, according to the American Associated Press. Earlier today, Trump addressed the people US Secretary of State regarding the war on Iran, stressing that the strategic goals are close to being achieved, but he did not set a date for the end of the war. He pointed out in his speech that the recent rise in gasoline prices in the United States is a short-term increase The Iranian regime is responsible for the rise in fuel prices due to its “crazy attacks” on oil tankers. Trump called on countries around the world that import oil through the Strait of Hormuz to bear responsibility for protecting this shipping lane.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Oil-prices-rise.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T10:10:08+03:00'::timestamptz, false, false, false, 176),
  ('مباحثات سورية – لبنانية لتعزيز التعاون الاقتصادي بين البلدين', 'Syrian-Lebanese discussions to enhance economic cooperation between the two countries', 'استقبل حاكم مصرف سوريا المركزي عبدالقادر الحصرية، الأربعاء 1 نيسان، سفير لبنان في سوريا هنري قسطون في إطار بحث سبل تعزيز التعاون المشترك بين الجانبين. وجرى خلال اللقاء بحث سبل تعزيز التعاون القطاع المصرفي والمالي، ضمن رؤية جديدة للتعاون الاقتصادي بين البلدين، بحسب ما نشر مصرف سوريا المركزي عبر معرفاته الرسمية. وكان حاكم مصرف سوريا […]', 'On Wednesday, April 1, the Governor of the Central Bank of Syria, Abdul Qader Al-Husria, received the Lebanese Ambassador to Syria, Henry Costoun, within the framework of discussing ways to enhance joint cooperation between the two sides. During the meeting, ways to enhance cooperation in the banking and financial sectors were discussed, including A new vision for economic cooperation between the two countries, according to what the Central Bank of Syria published through its official accounts. The Governor of the Bank of Syria was […]', 'استقبل حاكم مصرف سوريا المركزي عبدالقادر الحصرية، الأربعاء 1 نيسان، سفير لبنان في سوريا هنري قسطون في إطار بحث سبل تعزيز التعاون المشترك بين الجانبين. وجرى خلال اللقاء بحث سبل تعزيز التعاون القطاع المصرفي والمالي، ضمن رؤية جديدة للتعاون الاقتصادي بين البلدين، بحسب ما نشر مصرف سوريا المركزي عبر معرفاته الرسمية. وكان حاكم مصرف سوريا المركزي، قد بحث في 17 آذار، مع غرفة التجارة العربية النمساوية في فيينا، وضع خارطة طريق لمناقشة إعادة تفعيل قنوات التعامل المصرفي بين البنوك السورية والنمساوية. وجرى في الاجتماع بحث أبرز التحديات الإجرائية والتنظيمية التي تعيق التحويلات المالية، ولا سيما ما يتعلق بمتطلبات الامتثال، وأنظمة العقوبات، والبنوك المراسلة.', 'On Wednesday, April 1, the Governor of the Central Bank of Syria, Abdul Qader Al-Husria, received the Lebanese Ambassador to Syria, Henry Costoun, within the framework of discussing ways to enhance joint cooperation between the two sides. During the meeting, ways to enhance cooperation in the banking and financial sectors were discussed, including A new vision for economic cooperation between the two countries, according to what the Central Bank of Syria published through its official accounts. On March 17, the Governor of the Central Bank of Syria discussed, with the Arab-Austrian Chamber of Commerce in Vienna, a road map to discuss the return of... Activating banking channels between Syrian and Austrian banks. The meeting discussed the most prominent procedural and regulatory challenges that hinder financial transfers, especially those related to compliance requirements, sanctions regulations, and correspondent banks.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Governor-of-the-Central-Bank-of-Syria-3.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T21:00:34+03:00'::timestamptz, false, false, false, 175),
  ('خطوة إيجابية.. غرفة تجارة دمشق تثني على قرار فتح التبادل التجاري مع الأردن', 'A positive step.. The Damascus Chamber of Commerce praises the decision to open trade exchange with Jordan', 'أعلنت وزارة الصناعة والتجارة والتموين الأردنية، الأربعاء 1 نيسان، السماح بدخول منتجات سورية كانت خاضعة سابقاً لقيود الاستيراد، وذلك ضمن تنظيم التبادل التجاري بين البلدين. وينص القرار على إلغاء بعض قرارات الحظر ورخص الاستيراد السابقة، مقابل اعتماد رسوم حماية على قائمة من المستوردات ذات المنشأ السوري، مع التركيز على الصناعات الغذائية والمنسوجات باعتبارها من السلع […]', 'The Jordanian Ministry of Industry, Trade and Supply announced, on Wednesday, April 1, allowing the entry of Syrian products that were previously subject to import restrictions, as part of regulating trade exchange between the two countries. The decision stipulates the cancellation of some bans and licenses Previous imports, in exchange for the adoption of protection fees on a list of imports of Syrian origin, with a focus on food industries and textiles as commodities […]', 'أعلنت وزارة الصناعة والتجارة والتموين الأردنية، الأربعاء 1 نيسان، السماح بدخول منتجات سورية كانت خاضعة سابقاً لقيود الاستيراد، وذلك ضمن تنظيم التبادل التجاري بين البلدين. وينص القرار على إلغاء بعض قرارات الحظر ورخص الاستيراد السابقة، مقابل اعتماد رسوم حماية على قائمة من المستوردات ذات المنشأ السوري، مع التركيز على الصناعات الغذائية والمنسوجات باعتبارها من السلع الحساسة في السوق الأردني. وأوضحت الوزارة أن القرار جاء بعد متابعة مطالبات غرفة تجارة دمشق المتكررة لإعادة فتح السوق الأردنية أمام المنتجات السورية. وأكدت أن هذا الملف نوقش خلال لقاءات مع السفير الأردني في دمشق ورئيس اتحاد غرف التجارة الأردنية، إضافة إلى طرحه أمام وزير الصناعة والتجارة الأردني خلال الملتقى الاقتصادي في عمّان. وتوقعت أن يسهم القرار في تعزيز حركة التبادل التجاري بين البلدين، وأن يتيح للمصدّرين السوريين فرصاً أوسع لدخول السوق الأردنية، مع الحفاظ على حماية بعض القطاعات ', 'The Jordanian Ministry of Industry, Trade and Supply announced, on Wednesday, April 1, allowing the entry of Syrian products that were previously subject to import restrictions, as part of regulating trade exchange between the two countries. The decision stipulates the cancellation of some bans and licenses Previous imports, in exchange for adopting protection fees on a list of imports of Syrian origin, with a focus on the food and textile industries as sensitive commodities in the Jordanian market. The Ministry explained that the decision came after follow-up Damascus Chamber of Commerce''s repeated demands to reopen the Jordanian market to Syrian products. She confirmed that this file was discussed during meetings with the Jordanian ambassador in Damascus and the head of the Federation of Jordanian Chambers of Commerce, in addition to presenting it to the Minister of Industry and Trade. Jordanian during the Economic Forum in Amman. She expected that the decision would contribute to enhancing trade exchange between the two countries, and would provide Syrian exporters with broader opportunities to enter the Jordanian market, while maintaining the protection of some sectors.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Jordanian-Ministry-of-Industry-Trade-and-Supply.jpeg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T14:33:25+03:00'::timestamptz, false, false, false, 174),
  ('سوريا تعيد تفعيل ممرات الطاقة الإقليمية مع بدء دخول “الفيول” العراقي', 'Syria reactivates regional energy corridors with the start of the entry of Iraqi “fuel”.', 'أكدت وزارة الطاقة أن سوريا بدأت بإعادة تفعيل ممرات الطاقة الإقليمية مع بدء دخول صهاريج “الفيول العراقي” أراضيها، متجهة إلى مصب بانياس. ولفتت الوزارة عبر معرفاتها الرسمية، الأربعاء 1 نيسان، إلى أن هذه الخطوة “تؤشر إلى انطلاق مرحلة جديدة من تفعيل حركة ترانزيت الطاقة خلال سوريا وتعزيز دورها الحيوي في الربط بين الأسواق الإقليمية”. وبينت […]', 'The Ministry of Energy confirmed that Syria has begun to reactivate regional energy corridors with the start of “Iraqi fuel” tanks entering its territory, heading to the mouth of Baniyas. The Ministry pointed out through its official accounts, on Wednesday, April 1, that this step “indicates... Launching a new phase of activating the energy transit movement through Syria and enhancing its vital role in linking regional markets.” She indicated […]', 'أكدت وزارة الطاقة أن سوريا بدأت بإعادة تفعيل ممرات الطاقة الإقليمية مع بدء دخول صهاريج “الفيول العراقي” أراضيها، متجهة إلى مصب بانياس. ولفتت الوزارة عبر معرفاتها الرسمية، الأربعاء 1 نيسان، إلى أن هذه الخطوة “تؤشر إلى انطلاق مرحلة جديدة من تفعيل حركة ترانزيت الطاقة خلال سوريا وتعزيز دورها الحيوي في الربط بين الأسواق الإقليمية”. وبينت وزارة الطاقة أن بدء تدفق هذه الشحنات يعكس استعادة سوريا لموقعها الاستراتيجي بوصفها ممراً آمناً وموثوقاً للطاقة. وأوضحت الوزارة أن ذلك يسهم في دعم استقرار أسواق المنطقة وتوفير مسارات نقل فعّالة في ظل المتغيرات الإقليمية الراهنة؛ بما يخدم المصالح الوطنية ويعزز حضور البلاد في خريطة الطاقة الإقليمية. وذكرت الوزارة أن أولى قوافل صهاريج الفيول العراقي بدأت بالدخول إلى الأراضي السورية من خلال منفذ التنف/ الوليد الحدودي متجهة نحو مصفاة بانياس. ولفتت إلى أن عمليات تفريغ الشحنات في الخزانات المخصّصة ضمن المصفاة تجري في ', 'The Ministry of Energy confirmed that Syria has begun to reactivate regional energy corridors with the start of “Iraqi fuel” tanks entering its territory, heading to the mouth of Baniyas. The Ministry pointed out through its official accounts, on Wednesday, April 1, that this step “indicates... Launching a new phase of activating energy transit movement through Syria and enhancing its vital role in linking regional markets.” The Ministry of Energy stated that the start of the flow of these shipments reflects Syria’s restoration of its strategic position as a safe corridor. And energy reliable. The Ministry explained that this contributes to supporting the stability of the region’s markets and providing effective transportation paths in light of the current regional changes. In a way that serves national interests and enhances the country’s presence in the regional energy map. The Ministry stated that The first convoys of Iraqi fuel tanks began entering Syrian territory through the Al-Tanf/Al-Walid border crossing, heading towards the Baniyas refinery. She pointed out that the operations of unloading shipments into designated tanks within the refinery are taking place in...', 'https://alikhbariah.com/wp-content/uploads/2026/04/Iraqi-fuel-enters-Syria.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T10:34:09+03:00'::timestamptz, false, false, false, 173),
  ('الحرب الأمريكية – الإيرانية تضغط على اقتصادات دول المنطقة والعالم', 'The American-Iranian war is putting pressure on the economies of countries in the region and the world', 'تسبّب تعطل الملاحة في مضيق هرمز، الذي يمر به نحو 20% من الإمدادات العالمية من النفط والغاز، في ارتفاع أسعار الطاقة، وبالتالي تضخم عام في الأسعار في كثير من دول العالم. وجاء إغلاق المضيق نتيجة الحرب المندلعة في الشرق الأوسط بين إسرائيل والولايات المتحدة من جهة، وإيران من جهة أخرى منذ 28 شباط الماضي. وبحسب […]', 'The disruption of navigation in the Strait of Hormuz, through which about 20% of global supplies of oil and gas passes, has caused energy prices to rise, and thus a general inflation in prices in many countries of the world. The closure of the strait came as a result of the war raging in the east The Middle East conflict between Israel and the United States on the one hand, and Iran on the other hand, has been ongoing since February 28. According to […]', 'تسبّب تعطل الملاحة في مضيق هرمز، الذي يمر به نحو 20% من الإمدادات العالمية من النفط والغاز، في ارتفاع أسعار الطاقة، وبالتالي تضخم عام في الأسعار في كثير من دول العالم. وجاء إغلاق المضيق نتيجة الحرب المندلعة في الشرق الأوسط بين إسرائيل والولايات المتحدة من جهة، وإيران من جهة أخرى منذ 28 شباط الماضي. وبحسب تقرير لقناة الجزيرة صدر في 30 آذار الماضي، قفز سعر النفط من خام برنت بنسبة 53% منذ 27 شباط الفائت، وبلغت العقود الآجلة لخام برنت 112.57 دولاراً للبرميل الجمعة الماضية، مع تراجع الآمال بنهاية سريعة للحرب، فيما ارتفع سعر الغاز الطبيعي في الأسواق الأوروبية بأكثر من 50% ليصل إلى ما بين 55 و62 يورو للميغاواط/ساعة. ويلفت التقرير الانتباه إلى أن الحكومات حول العالم لجأت إلى اتخاذ مجموعة من الإجراءات لمواجهة القفزة في أسعار الطاقة ودعم مواطنيها للتخفيف من آثارها، فضلاً عن إجراءات حكومية للحد من النفقات. وفي العراق، على سبيل المثال، أفاد مسؤولون ل', 'The disruption of navigation in the Strait of Hormuz, through which about 20% of global supplies of oil and gas passes, has caused energy prices to rise, and thus a general inflation in prices in many countries of the world. The closure of the strait came as a result of the war raging in the east The Middle East conflict between Israel and the United States on the one hand, and Iran on the other hand, has been ongoing since February 28. According to a report by Al Jazeera issued on March 30, the price of Brent crude oil has jumped by 53% since February 27, and Brent crude futures contracts reached... $112.57 per barrel last Friday, with hopes for a quick end to the war declining, while the price of natural gas in European markets rose by more than 50% to reach between 55 and 62 euros per megawatt-hour. The report draws attention to that Governments around the world have resorted to taking a set of measures to confront the jump in energy prices and support their citizens to mitigate its effects, as well as government measures to reduce expenses. In Iraq, for example, officials reported...', 'https://alikhbariah.com/wp-content/uploads/2026/04/The-American-Iranian-war.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T09:20:41+03:00'::timestamptz, false, false, false, 172),
  ('المالية تعلن بدء التسجيل الإلكتروني لإعادة صرف المعاشات التقاعدية المتوقفة', 'Finance announces the start of electronic registration to repay suspended pensions', 'أعلنت وزارة المالية، الأربعاء 1 نيسان، بدء التسجيل الإلكتروني لاستكمال عملية صرف المعاشات التقاعدية المتوقفة، وذلك في إطار جهودها لمعالجة ملفات المتقاعدين وضمان وصول المستحقات المالية إلى أصحابها. وأوضحت الوزارة عبر معرفاتها الرسمية، أن عملية التسجيل متاحة من خلال الرسائل النصية المجانية (SMS) إلى الرقم 3346، على أن يتضمن محتوى الرسالة الاسم الثلاثي والرقم الوطني […]', 'On Wednesday, April 1, the Ministry of Finance announced the start of electronic registration to complete the process of disbursing suspended pensions, as part of its efforts to address retirees’ files and ensure that financial entitlements reach their owners. The Ministry explained via According to its official IDs, the registration process is available through free text messages (SMS) to the number 3346, provided that the content of the message includes the full name and the national number […]', 'أعلنت وزارة المالية، الأربعاء 1 نيسان، بدء التسجيل الإلكتروني لاستكمال عملية صرف المعاشات التقاعدية المتوقفة، وذلك في إطار جهودها لمعالجة ملفات المتقاعدين وضمان وصول المستحقات المالية إلى أصحابها. وأوضحت الوزارة عبر معرفاتها الرسمية، أن عملية التسجيل متاحة من خلال الرسائل النصية المجانية (SMS) إلى الرقم 3346، على أن يتضمن محتوى الرسالة الاسم الثلاثي والرقم الوطني والصفة واسم الأم، مؤكدةً أن صاحب العلاقة يتحمل مسؤولية صحة البيانات المقدمة. وبيّنت أن الطلبات تقبل من صاحب العلاقة حصراً دون الوكلاء، داعيةً إلى التأكد من صحة رقم الهاتف المرسل منه الطلب كونه وسيلة التواصل المعتمدة، حيث ستجري عملية تدقيق الطلبات واستكمال الإجراءات اللازمة لاحقاً. وأشارت وزارة المالية إلى أن هذه الخطوة تندرج ضمن خطة تنظيم بيانات المتقاعدين وتسريع إجراءات إعادة صرف المعاشات التقاعدية المتوقفة وفق الآليات المعتمدة. وأكد وزير المالية محمد يسر برنية، في 28 آذار، أن ا', 'On Wednesday, April 1, the Ministry of Finance announced the start of electronic registration to complete the process of disbursing suspended pensions, as part of its efforts to address retirees’ files and ensure that financial entitlements reach their owners. The Ministry explained via According to its official IDs, the registration process is available through free text messages (SMS) to the number 3346, provided that the content of the message includes the full name, national number, title, and mother’s name, stressing that the person concerned bears responsibility for the accuracy of the data. the introduction. She indicated that applications are accepted exclusively from the person concerned, not agents, calling for ensuring that the phone number from which the request is sent is correct, as it is the approved means of communication, as the process of verifying the applications and completing the necessary procedures will take place later. The Ministry of Finance indicated that this step falls within the plan to organize retirees’ data and accelerate the procedures for repaying suspended pensions according to the approved mechanisms. Finance Minister Muhammad Yusser Barneyah confirmed on March 28 that Mr', 'https://alikhbariah.com/wp-content/uploads/2026/04/Ministry-of-Finance.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T09:15:25+03:00'::timestamptz, false, false, false, 171),
  ('مظاهرات شعبية في عدة مدن سورية تنديداً بقانون إعدام الأسرى الفلسطينيين', 'Popular demonstrations in several Syrian cities denouncing the law on executing Palestinian prisoners', 'خرجت مظاهرات شعبية في عدة مدن ومناطق سورية، الجمعة 3 نيسان، تنديداً بقانون إعدام الأسرى الفلسطينيين الذي أقرّه الكنيست الإسرائيلي قبل أيام. وبحسب مراسلي الإخبارية، شهد حي الرمل الجنوبي في اللاذقية مظاهرة كبيرة، كما نظّم الأهالي في مدينة جرابلس شرق حلب وقفة تضامنية مع الشعب الفلسطيني، مؤكدين دعمهم للأسرى ورفضهم لممارسات الاحتلال الإسرائيلي. وشملت التظاهرات […]', 'Popular demonstrations took place in several Syrian cities and regions, Friday, April 3, denouncing the law on executing Palestinian prisoners that was approved by the Israeli Knesset a few days ago. According to my news correspondent, the southern Raml neighborhood in Latakia witnessed and organized a large demonstration The people of the city of Jarabulus, east of Aleppo, stand in solidarity with the Palestinian people, affirming their support for the prisoners and their rejection of the practices of the Israeli occupation. The demonstrations included […]', 'خرجت مظاهرات شعبية في عدة مدن ومناطق سورية، الجمعة 3 نيسان، تنديداً بقانون إعدام الأسرى الفلسطينيين الذي أقرّه الكنيست الإسرائيلي قبل أيام. وبحسب مراسلي الإخبارية، شهد حي الرمل الجنوبي في اللاذقية مظاهرة كبيرة، كما نظّم الأهالي في مدينة جرابلس شرق حلب وقفة تضامنية مع الشعب الفلسطيني، مؤكدين دعمهم للأسرى ورفضهم لممارسات الاحتلال الإسرائيلي. وشملت التظاهرات مناطق أخرى مثل قلعة المضيق في ريف حماة وكفربطنا في ريف دمشق ومدينة إدلب وحي التضامن الدمشقي، حيث رفع المشاركون لافتات وشعارات تطالب المجتمع الدولي بالتدخل لحماية الأسرى الفلسطينيين وضمان سلامتهم. وأكد المشاركون في الوقفات الاحتجاجية استمرار دعمهم للأسرى الفلسطينيين والتعبير عن رفضهم للإجراءات الإسرائيلية، مؤكدين على ضرورة التضامن الشعبي لمواجهة السياسات الإسرائيلية بحق الأسرى. وجاءت هذه الفعاليات ضمن “جمعة الأسرى والمسرى” التي نظمتها تنسيقيات المدن السورية المختلفة، للتأكيد على التضامن ا', 'Popular demonstrations took place in several Syrian cities and regions, Friday, April 3, denouncing the law on executing Palestinian prisoners that was approved by the Israeli Knesset a few days ago. According to my news correspondent, the southern Raml neighborhood in Latakia witnessed and organized a large demonstration The people of the city of Jarabulus, east of Aleppo, stand in solidarity with the Palestinian people, affirming their support for the prisoners and their rejection of the practices of the Israeli occupation. The demonstrations included other areas, such as Qalaat al-Madiq in the Hama countryside, Kafr Batna in the Damascus countryside, the city of Idlib, and the neighborhood of Damascene Solidarity, where participants raised banners and slogans calling on the international community to intervene to protect Palestinian prisoners and ensure their safety. Participants in the vigils affirmed their continued support for the Palestinian prisoners and expressed their rejection of the measures Israeli forces, stressing the need for popular solidarity to confront Israeli policies against prisoners. These activities came within the “Friday of Prisoners and Captives” organized by the coordination of various Syrian cities, to emphasize the solidarity', 'https://alikhbariah.com/wp-content/uploads/2026/04/Popular-demonstrations-in-several-Syrian-cities-denouncing-the-law-to-execute-Palestinian-prisoners.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T14:44:18+03:00'::timestamptz, false, true, false, 170),
  ('الهلالي: الفريق الرئاسي يعمل على إعادة 200 عائلة من الحسكة إلى عفرين', 'Al-Hilali: The presidential team is working to return 200 families from Hasakah to Afrin', 'أوضح المتحدّث باسم الفريق الرئاسي المكلّف بمتابعة تنفيذ اتفاق 29 كانون الثاني مع قسد أحمد الهلالي، أن الفريق يعمل على إعادة النازحين إلى مناطقهم في عفرين بالتنسيق مع قيادتي الأمن الداخلي في الحسكة وحلب والدفاع المدني. وأشار الهلالي إلى أن غداً السبت المصادف 4 نيسان، سيشهد عودة 200 عائلة إلى منازلها، ضمن برنامج منظّم يهدف […]', 'The spokesman for the presidential team charged with following up on the implementation of the January 29 agreement with the SDF, Ahmed Al-Hilali, explained that the team is working to return the displaced to their areas in Afrin in coordination with the leadership of the Internal Security in Hasakah and Aleppo and the Civil Defense. Al-Hilali pointed out that tomorrow, Saturday, April 4, will witness the return of 200 families to their homes, as part of an organized program aimed […]', 'أوضح المتحدّث باسم الفريق الرئاسي المكلّف بمتابعة تنفيذ اتفاق 29 كانون الثاني مع قسد أحمد الهلالي، أن الفريق يعمل على إعادة النازحين إلى مناطقهم في عفرين بالتنسيق مع قيادتي الأمن الداخلي في الحسكة وحلب والدفاع المدني. وأشار الهلالي إلى أن غداً السبت المصادف 4 نيسان، سيشهد عودة 200 عائلة إلى منازلها، ضمن برنامج منظّم يهدف إلى تخفيف المعاناة الإنسانية وتسهيل إعادة الحياة الطبيعية للمدن والمناطق المحرّرة. وبيّن أن البرنامج يشمل إعادة تأهيل المدارس التي كانت مشغولة بالنازحين تمهيداً لافتتاحها في الموسم الدراسي القادم، ما يُعزّز استقرار المجتمع المحلي وعودة الخدمات الأساسية. وأكد الهلالي أن العمل يتوازى مع خطة لإجلاء المعتقلين بقضايا غير جزائية من سجون “قسد”، واستلام وإعادة هيكلة إدارة السجون في محافظة الحسكة بما يتوافق مع المعايير القانونية لضمان إدارة آمنة ومنظّمة للمنشآت. وتشمل الإجراءات إغلاق عدد من السجون القديمة التي كانت تحت إشراف “قسد”', 'The spokesman for the presidential team charged with following up on the implementation of the January 29 agreement with the SDF, Ahmed Al-Hilali, explained that the team is working to return the displaced to their areas in Afrin in coordination with the leadership of the Internal Security in Hasakah and Aleppo and the Civil Defense. Al-Hilali pointed out that tomorrow, Saturday, April 4, will witness the return of 200 families to their homes, as part of an organized program aimed at alleviating human suffering and facilitating the restoration of normal life to the liberated cities and regions. He stated that the program includes repetition Rehabilitating schools that were occupied by displaced people in preparation for their opening in the next academic season, which enhances the stability of the local community and the return of basic services. Al-Hilali confirmed that the work is parallel to a plan to evacuate detainees in non-criminal cases from “SDF” prisons, and taking over and restructuring the prison administration in Al-Hasakah Governorate in accordance with legal standards to ensure safe and organized management of the facilities. The measures include closing a number of old prisons that were under the supervision of the SDF.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Ahmed-al-Hilali-spokesperson-for-the-presidential-team-tasked-with-monitoring-the-implementation-of-the-January-29-agreement-with-the-SDF.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T14:30:22+03:00'::timestamptz, false, true, false, 169),
  ('أزمة الطحين والخبز في السويداء: معاناة يومية وصراع المصالح على قوت المواطنين', 'The flour and bread crisis in Suwayda: daily suffering and a conflict of interests over citizens’ livelihood', 'تتعمّق الأزمة الإنسانية في محافظة السويداء، حيث تتفاقم معاناة السكان جراء النفاد التام لمادة الطحين من الأفران، لتدخل المحافظة في أزمة خبز حادة تهدّد بتوقّف عدد من الأفران الرئيسة عن العمل، وسط تأكيدات من جانب المواطنين بحرمانهم من الحصول على أبسط مقوّمات الحياة الأساسية. وتُسلّط تصريحات المسؤولين وشهادات الأهالي، الضوء على أبعاد هذه المعاناة الإنسانية […]', 'The humanitarian crisis is deepening in As-Suwayda Governorate, where the population’s suffering is exacerbated as a result of the complete depletion of flour from bakeries, causing the governorate to enter into a severe bread crisis that threatens to cause a number of main bakeries to stop working, amid assurances from citizens. By depriving them of the most basic necessities of life. The statements of officials and the testimonies of families highlight the dimensions of this human suffering [...]', 'تتعمّق الأزمة الإنسانية في محافظة السويداء، حيث تتفاقم معاناة السكان جراء النفاد التام لمادة الطحين من الأفران، لتدخل المحافظة في أزمة خبز حادة تهدّد بتوقّف عدد من الأفران الرئيسة عن العمل، وسط تأكيدات من جانب المواطنين بحرمانهم من الحصول على أبسط مقوّمات الحياة الأساسية. وتُسلّط تصريحات المسؤولين وشهادات الأهالي، الضوء على أبعاد هذه المعاناة الإنسانية في محافظة تشهد تعقيدات إدارية وصراع مصالح على قوت الناس. انتهاء الإمدادات وعراقيل إدارية ترجع جذور هذه الأزمة إلى انتهاء العقد المبرم مع برنامج الأغذية العالمي (WFP) في 31 آذار الماضي، ما أسفر عن توقّف إمدادات الدقيق إلى المنطقة. ورغم تجديد العقد وحصول البرنامج على موافقات دولية ودعم من الدول المانحة للاستمرار بتزويد السويداء بالطحين، إلا أن استئناف التوريد يصطدم حالياً بعراقيل من الداخل. وبينما يُتوقّع أن يستغرق إتمام هذه المعاملات عدة أيام، فإن هذا يعني عدم وجود حلول إسعافية أو بديلة متاح', 'The humanitarian crisis is deepening in As-Suwayda Governorate, where the population’s suffering is exacerbated as a result of the complete depletion of flour from bakeries, causing the governorate to enter into a severe bread crisis that threatens to cause a number of main bakeries to stop working, amid assurances from citizens. By depriving them of the most basic necessities of life. The statements of officials and the testimonies of residents shed light on the dimensions of this human suffering in a governorate that is witnessing administrative complexities and a conflict of interests over people’s livelihood. Expiry of supplies and obstacles Administrative The roots of this crisis go back to the expiration of the contract concluded with the World Food Program (WFP) on March 31, which resulted in the cessation of flour supplies to the region. Despite the renewal of the contract and the program obtaining international approvals and support from donor countries To continue supplying Suwayda with flour, but resuming the supply is currently encountering obstacles from within. While these transactions are expected to take several days to complete, this means that there are no band-aid or alternative solutions available', 'https://alikhbariah.com/wp-content/uploads/2026/04/bread-crisis.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T14:15:05+03:00'::timestamptz, false, false, false, 168),
  ('إدارة الأحوال المدنية توضح آليات تنفيذ المرسوم 13 لعام 2026', 'The Civil Status Administration clarifies the mechanisms for implementing Decree No. 13 of 2026', 'أوضحت إدارة الأحوال المدنية، الجمعة 3 نيسان، آليات تنفيذ المرسوم رقم 13 لعام 2026 القاضي بمنح الجنسية في الجمهورية العربية السورية للمواطنين من أصول كردية المقيمين على الأراضي السورية، بمن فيهم مكتومو القيد. جاء ذلك في توضيحات صادرة عن مدير الأحوال المدنية وعضو اللجنة العليا لتنفيذ المرسوم عبد الله العبد الله، مع تحديد بدء تنفيذ […]', 'On Friday, April 3, the Civil Status Administration clarified the mechanisms for implementing Decree No. 13 of 2026 granting citizenship in the Syrian Arab Republic to citizens of Kurdish origin residing on Syrian territory, including those without registration. This came in Clarifications issued by the Director of Civil Status and member of the Supreme Committee for Implementing the Decree, Abdullah Al-Abdullah, specifying the start of implementation […]', 'أوضحت إدارة الأحوال المدنية، الجمعة 3 نيسان، آليات تنفيذ المرسوم رقم 13 لعام 2026 القاضي بمنح الجنسية في الجمهورية العربية السورية للمواطنين من أصول كردية المقيمين على الأراضي السورية، بمن فيهم مكتومو القيد. جاء ذلك في توضيحات صادرة عن مدير الأحوال المدنية وعضو اللجنة العليا لتنفيذ المرسوم عبد الله العبد الله، مع تحديد بدء تنفيذ الإجراءات اعتباراً من يوم الإثنين 6 نيسان 2026. وبيّن أن اللجان المختصة ستتوزّع في عدة محافظات، بواقع لجنة في حلب، ولجنة في دير الزور، ولجنة في الرقة، ولجنة في دمشق، إضافةً إلى خمس لجان في محافظة الحسكة، وذلك لاستقبال الطلبات وتدقيقها وتوجيه المتقدّمين في حال وجود نقص في الأوراق. وأوضح أن آلية عمل اللجان تنقسم إلى أربعة أقسام، يبدأ أولها باستقبال الطلبات وتدقيقها، ثم لجنة المقابلة التي تضم قاضياً ومسؤولاً من الأحوال المدنية وممثّلاً عن المحافظة، وتتولى مقابلة المتقدّمين وتوثيق الأوراق ودراسة الحالات. وأضاف: إن الل', 'On Friday, April 3, the Civil Status Administration clarified the mechanisms for implementing Decree No. 13 of 2026 granting citizenship in the Syrian Arab Republic to citizens of Kurdish origin residing on Syrian territory, including those without registration. This came in Clarifications issued by the Director of Civil Status and member of the Supreme Committee for Implementing the Decree, Abdullah Al-Abdullah, specifying that the implementation of the procedures will begin as of Monday, April 6, 2026. He stated that the relevant committees will be distributed in several governorates, with a committee In Aleppo, a committee in Deir ez-Zor, a committee in Raqqa, and a committee in Damascus, in addition to five committees in Al-Hasakah Governorate, to receive applications, review them, and direct applicants in the event of a shortage of papers. He explained that the committees'' work mechanism is divided into four Sections, the first of which begins with receiving applications and examining them, then the interview committee, which includes a judge, a civil status official, and a representative of the governorate, is responsible for interviewing applicants, documenting papers, and studying cases. He added: God', 'https://alikhbariah.com/wp-content/uploads/2026/04/Civil-Status-Department.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T13:56:46+03:00'::timestamptz, false, false, false, 167),
  ('وزارة العدل تعفي ذوي الإعاقة من الرسوم والتأمينات القضائية في جميع الدعاوى', 'The Ministry of Justice exempts people with disabilities from fees and judicial deposits in all cases', 'أعفت وزارة العدل جميع الأشخاص ذوي الإعاقة من الرسوم والتأمينات القضائية في جميع الدعاوى المقامة أمام المحاكم على اختلاف أنواعها ودرجاتها. جاء ذلك في تعميمٍ للوزارة، الجمعة 3 نيسان، استناداً إلى الكتاب الصادر عن وزارة الشؤون الاجتماعية والعمل بتاريخ 11 شباط 2026، وإلى أحكام المرسوم التشريعي رقم 19 لعام 2024، ولاسيما البند الخامس من الفقرة […]', 'The Ministry of Justice exempted all persons with disabilities from fees and judicial deposits in all cases filed before courts of all types and degrees. This came in a circular from the Ministry, Friday, April 3, based on the book issued by the Ministry Social Affairs and Labor dated February 11, 2026, and to the provisions of Legislative Decree No. 19 of 2024, especially item five of paragraph […]', 'أعفت وزارة العدل جميع الأشخاص ذوي الإعاقة من الرسوم والتأمينات القضائية في جميع الدعاوى المقامة أمام المحاكم على اختلاف أنواعها ودرجاتها. جاء ذلك في تعميمٍ للوزارة، الجمعة 3 نيسان، استناداً إلى الكتاب الصادر عن وزارة الشؤون الاجتماعية والعمل بتاريخ 11 شباط 2026، وإلى أحكام المرسوم التشريعي رقم 19 لعام 2024، ولاسيما البند الخامس من الفقرة (ب) من المادة 23 منه. ونص التعميم على إعفاء الأشخاص ذوي الإعاقة من الرسوم والتأمينات القضائية في الدعاوى المقامة أمام المحاكم بمختلف درجاتها، إضافةً إلى التعليمات التنفيذية الصادرة بقرار مجلس الوزراء رقم 55 لعام 2024 التي أوجبت اتخاذ الإجراءات اللازمة لتنفيذ هذا الإعفاء. وأوضح التعميم أن المقصود بالإعاقة هي الإعاقة المثبتة بموجب بطاقة إعاقة تمنحها وزارة الشؤون الاجتماعية والعمل للشخص ذي الإعاقة من مواطني الجمهورية العربية السورية ومن في حكمهم، باعتبارها الوثيقة الرسمية المعتمدة لتطبيق أحكام المرسوم التشري', 'The Ministry of Justice exempted all persons with disabilities from fees and judicial deposits in all cases filed before courts of all types and degrees. This came in a circular from the Ministry, Friday, April 3, based on the book issued by the Ministry Social Affairs and Labor dated February 11, 2026, and to the provisions of Legislative Decree No. 19 of 2024, especially Clause Five of Paragraph (B) of Article 23 thereof. The circular stipulates that persons with disabilities are exempted from judicial fees and insurance Cases filed before courts at various levels, in addition to the executive instructions issued by Cabinet Resolution No. 55 of 2024, which required taking the necessary measures to implement this exemption. The circular clarified that what is meant by disability is disability Proven according to a disability card granted by the Ministry of Social Affairs and Labor to a person with a disability who is a citizen of the Syrian Arab Republic and the like, as the official document approved for implementing the provisions of the legislative decree.', 'https://alikhbariah.com/wp-content/uploads/2026/02/Ministry-of-Justice-4-1.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T13:04:32+03:00'::timestamptz, false, false, false, 166),
  ('الداخلية تكشف حصيلة الربع الأول من 2026: عمليات نوعية تستهدف ميليشيات النظام البائد', 'The Ministry of Interior reveals the outcome of the first quarter of 2026: specific operations targeting the militias of the former regime', 'أعلنت وزارة الداخلية عن حصيلة العمليات الأمنية النوعية التي نُفّذت خلال الربع الأول من عام 2026، والتي أسفرت عن إلقاء القبض على عشرات المجرمين وقيادات بارزة في ميليشيات النظام البائد. وأوضح أنفوغراف الوزارة، الصادر عنها اليوم الجمعة 3 نيسان، أن العمليات الأمنية خلال النصف الأول من كانون الثاني 2026 استهدفت مجموعة من المجرمين، نتج عنها […]', 'The Ministry of Interior announced the outcome of the qualitative security operations carried out during the first quarter of 2026, which resulted in the arrest of dozens of criminals and prominent leaders of the former regime’s militias. He explained the ministry''s infographic issued by it Today, Friday, April 3, security operations during the first half of January 2026 targeted a group of criminals, resulting in […]', 'أعلنت وزارة الداخلية عن حصيلة العمليات الأمنية النوعية التي نُفّذت خلال الربع الأول من عام 2026، والتي أسفرت عن إلقاء القبض على عشرات المجرمين وقيادات بارزة في ميليشيات النظام البائد. وأوضح أنفوغراف الوزارة، الصادر عنها اليوم الجمعة 3 نيسان، أن العمليات الأمنية خلال النصف الأول من كانون الثاني 2026 استهدفت مجموعة من المجرمين، نتج عنها اعتقال كل من: خالد الحسين الذي كان يشغل رتبة مساعد أول في أمن الدولة بإدلب، وشجاع إبراهيم متزعّم مجموعة تابعة لميليشيا “الطراميح” المرتبطة بالفرقة 25، وأزد شير كامل إبراهيم لارتباطه السابق بميليشيا “الدفاع الوطني”. كما شملت العمليات في الفترة ذاتها كلّاً من علي رجوح الذي شغل سابقاً رتبة ملازم أول في الكلية البحرية، ووسيم حمدان وعادل مرعي اللذين شغلا مناصب قيادية في ريف درعا الشمالي، ومحمد خير فوزي العلي المنتسب سابقاً إلى الفرع 215. أما في النصف الثاني من كانون الثاني 2026، فقد استهدفت العمليات الأمنية مجموع', 'The Ministry of Interior announced the outcome of the qualitative security operations carried out during the first quarter of 2026, which resulted in the arrest of dozens of criminals and prominent leaders of the former regime’s militias. He explained the ministry''s infographic issued by it Today, Friday, April 3, security operations during the first half of January 2026 targeted a group of criminals, resulting in the arrest of: Khaled Al-Hussein, who held the rank of first assistant in State Security in Idlib, and Shujaa Ibrahim, a leader. A group affiliated with the “Taramih” militia linked to the 25th Division, and Azd Sher Kamel Ibrahim due to his previous association with the “National Defense” militia. The operations during the same period also included Ali Rajouh, who previously held the rank of first lieutenant at the Naval College. Wassim Hamdan and Adel Marei, who held leadership positions in the northern countryside of Daraa, and Muhammad Khair Fawzi Al-Ali, formerly affiliated with Branch 215. In the second half of January 2026, security operations targeted a total of', 'https://alikhbariah.com/wp-content/uploads/2026/01/Ministry-of-Interior-6.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T12:44:18+03:00'::timestamptz, false, false, false, 165),
  ('مقتل ثلاثة أطفال وإصابة آخرين جراء انفجار لغم في بلدة الهبيط', 'Three children were killed and others injured as a result of a mine explosion in the town of Al-Habit', 'قتل ثلاثة أطفال وأصيب آخرون، جراء انفجار لغم أرضي من مخلّفات النظام البائد في مدرسة اليرموك الواقعة في بلدة الهبيط بريف إدلب الجنوبي، بحسب ما أفادت إذاعة دمشق. من جانبه، قال المكتب الإعلامي لمديرية صحة حماة في بيان صحفي نشرته المديرية عبر معرفاتها الرسمية، إن قسم الإسعاف في مشفى السقيلبية الوطني تلقى بلاغاً يفيد بوصول […]', 'Three children were killed and others were injured, as a result of the explosion of a landmine left over from the former regime in the Yarmouk School located in the town of Al-Habit in the southern countryside of Idlib, according to what Damascus Radio reported. For its part, the media office of the Hama Health Directorate said in a press statement Published by the Directorate through its official accounts, the Ambulance Department at Suqaylabiya National Hospital received a report stating the arrival […]', 'قتل ثلاثة أطفال وأصيب آخرون، جراء انفجار لغم أرضي من مخلّفات النظام البائد في مدرسة اليرموك الواقعة في بلدة الهبيط بريف إدلب الجنوبي، بحسب ما أفادت إذاعة دمشق. من جانبه، قال المكتب الإعلامي لمديرية صحة حماة في بيان صحفي نشرته المديرية عبر معرفاتها الرسمية، إن قسم الإسعاف في مشفى السقيلبية الوطني تلقى بلاغاً يفيد بوصول طفلين مجهولي الهوية، تعرّضا لإصابات بالغة إثر انفجار لغم في قرية الهبيط. وتوفي أحد الطفلين في موقع الحادث متأثراً بالإصابات البليغة التي لحقت به، فيما أصيب الطفل الآخر بشظايا متفرقة استدعت تدخّلاً طبياً عاجلاً. وذكر المكتب أن الفريق الطبي في مشفى السقيلبية الوطني قدّم الإسعافات الأولية اللازمة للطفل المصاب، ويتم حالياً استكمال الإجراءات الطبية الضرورية تمهيداً لنقله إلى مشفى حماة الوطني لتلقي الرعاية الطبية المتخصصة واستكمال علاجه. وكرّرت مديرية صحة حماة مناشدتها لجميع الأهالي بضرورة الالتزام بأقصى درجات الحيطة والحذر، ونبّه', 'Three children were killed and others were injured, as a result of the explosion of a landmine left over from the former regime in the Yarmouk School located in the town of Al-Habit in the southern countryside of Idlib, according to what Damascus Radio reported. For its part, the media office of the Hama Health Directorate said in a press statement The directorate published it through its official accounts, saying that the ambulance department at Al-Suqaylabiyah National Hospital received a report stating the arrival of two unidentified children who were seriously injured as a result of a mine explosion in the village of Al-Habit. One of the two children died at the scene of the accident He sustained serious injuries, while the other child was injured by scattered shrapnel that required urgent medical intervention. The office stated that the medical team at Al-Suqaylabiyah National Hospital provided the necessary first aid to the injured child, and the treatment is currently being completed The necessary medical procedures in preparation for his transfer to Hama National Hospital to receive specialized medical care and complete his treatment. The Hama Health Directorate reiterated its appeal to all residents to adhere to the utmost caution and alertness.', 'https://alikhbariah.com/wp-content/uploads/2026/01/landmine.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T12:01:09+03:00'::timestamptz, false, false, false, 164),
  ('هطولات مطرية في مناطق متفرقة.. وانحسار تأثير المنخفض مساء', 'Rainfall in various areas... and the effect of the depression recedes in the evening', 'تستمر الهطولات المطرية خلال الساعات القادمة في مناطق متفرقة من البلاد، بسبب استمرار تأثرها بالمنخفض الجوي، على أن ينحسر تدريجياً مساء اليوم، الجمعة 3 نيسان، وفقاً للنشرة الصادرة عن المديرية العامة للأرصاد الجوية التابعة لوزارة الطوارئ وإدارة الكوارث. وكانت أجواء الليلة الماضية باردة نسبياً، وخاصة في المرتفعات الجبلية، مع تسجيل حالات لتشكل الضباب في أجزاء […]', 'Rainfall will continue during the coming hours in various areas of the country, due to its continued influence by the depression, and will gradually subside this evening, Friday, April 3, according to the bulletin issued by the General Directorate of Meteorology, which is responsible for... For the Ministry of Emergency and Disaster Management. The weather last night was relatively cold, especially in the mountain highlands, with cases of fog formation recorded in parts […]', 'تستمر الهطولات المطرية خلال الساعات القادمة في مناطق متفرقة من البلاد، بسبب استمرار تأثرها بالمنخفض الجوي، على أن ينحسر تدريجياً مساء اليوم، الجمعة 3 نيسان، وفقاً للنشرة الصادرة عن المديرية العامة للأرصاد الجوية التابعة لوزارة الطوارئ وإدارة الكوارث. وكانت أجواء الليلة الماضية باردة نسبياً، وخاصة في المرتفعات الجبلية، مع تسجيل حالات لتشكل الضباب في أجزاء من المنطقة الوسطى خلال ساعات الصباح الباكر. ويكون الطقس اليوم غائماً جزئياً بشكل عام، مع بقاء فرصة لهطولات مطرية متفرقة في المناطق الساحلية والجزيرة، وأجزاء من المنطقتين الشمالية والوسطى، كما تواصل درجات الحرارة انخفاضها لتصبح أدنى من معدلاتها بقليل. وتكون الرياح غربية إلى جنوبية غربية، بين الخفيفة والمعتدلة، مع هبات نشطة تصل سرعتها إلى 60 كيلومتراً في الساعة، وخاصة في المناطق الجنوبية والشمالية والساحلية، وأجزاء من المنطقة الوسطى والبادية، ويكون البحر خفيفاً إلى متوسط ارتفاع الموج. وحذرت', 'Rainfall will continue during the coming hours in various areas of the country, due to its continued influence by the depression, and will gradually subside this evening, Friday, April 3, according to the bulletin issued by the General Directorate of Meteorology, which is responsible for... For the Ministry of Emergency and Disaster Management. The weather last night was relatively cold, especially in the mountain highlands, with cases of fog formation recorded in parts of the central region during the early morning hours. The weather today will be partly cloudy General, with a chance of scattered rain showers remaining in the coastal areas, the island, and parts of the northern and central regions, and temperatures continue to drop to become slightly below average. The winds will be westerly to southwesterly, between light And moderate, with active gusts reaching speeds of up to 60 kilometers per hour, especially in the southern, northern and coastal regions, and parts of the central and desert regions, and the sea will be light to medium wave height. And I warned', 'https://alikhbariah.com/wp-content/uploads/2026/04/low-2.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T07:07:35+03:00'::timestamptz, false, false, false, 163),
  ('الخط الدائري الجنوبي في حلب.. من الفوضى إلى التنظيم', 'The Southern Ring Line in Aleppo... from chaos to organization', 'تشهد حركة النقل في مدينة حلب تغييرات جذرية ساهمت في تنظيم الحالة المرورية، في إطار توجهات مديرية النقل في محافظة حلب، والتي تهدف إلى إعادة تنظيم خط نقل “الدائري الجنوبي”، الذي يعد أحد أكثر الخطوط حيوية وازدحاماً في المدينة. عملت مديرية النقل في حلب على إدخال حافلات جديدة لتغذية الخط الدائري الجنوبي وإبعاد الحافلات المخالفة، […]', 'The transportation movement in the city of Aleppo is witnessing radical changes that have contributed to organizing the traffic situation, within the framework of the directions of the Transport Directorate in Aleppo Governorate, which aims to reorganize the “Southern Ring” transportation line, which is one of the most vital and crowded lines in the city. City. The Transport Directorate in Aleppo worked to introduce new buses to feed the Southern Ring Line and remove the violating buses, […]', 'تشهد حركة النقل في مدينة حلب تغييرات جذرية ساهمت في تنظيم الحالة المرورية، في إطار توجهات مديرية النقل في محافظة حلب، والتي تهدف إلى إعادة تنظيم خط نقل “الدائري الجنوبي”، الذي يعد أحد أكثر الخطوط حيوية وازدحاماً في المدينة. عملت مديرية النقل في حلب على إدخال حافلات جديدة لتغذية الخط الدائري الجنوبي وإبعاد الحافلات المخالفة، وقالت إن هذه الخطوة تهدف إلى ضبط الفوضى وتحسين خدمة النقل. في المقابل، أثار هذا القرار مخاوف لدى السائقين من خلق أزمة جديدة وعدم القدرة على استيعاب أعداد الركاب لجهة طول الخط واقتصار الخدمة على عدد قليل من الحافلات لتخدم المنطقة. خطة تشغيل خلال 100 يوم في هذا الصدد، أوضح مدير الإعلام في مديرية نقل حلب سعد غنيم لموقع الإخبارية أن خط نقل “الدائري الجنوبي” هو في الواقع من الخطوط الخالية ويفتقر إلى وجود حافلات نقل مرخصة ضمن الجداول الرسمية لدى المديرية، مؤكداً أن وسائل النقل العاملة حالياً تعمل خارج الإطار القانوني. وأضاف ', 'The transportation movement in the city of Aleppo is witnessing radical changes that have contributed to organizing the traffic situation, within the framework of the directions of the Transport Directorate in Aleppo Governorate, which aims to reorganize the “Southern Ring” transportation line, which is one of the most vital and crowded lines in the city. City. The Transport Directorate in Aleppo worked to introduce new buses to feed the Southern Ring Line and remove the violating buses, and said that this step aims to control chaos and improve transportation service. On the other hand, this decision raised concerns among drivers Creating a new crisis and the inability to accommodate the number of passengers in terms of the length of the line and limiting service to a small number of buses to serve the region. An operating plan within 100 days. In this regard, the Director of Information at the Aleppo Transport Directorate, Saad Ghoneim, explained to Al-Ekhbariya website: The “Southern Ring” transport line is in fact one of the empty lines and lacks the presence of licensed transport buses on the official schedules of the Directorate, confirming that the currently operating means of transport operate outside the legal framework. He added', 'https://alikhbariah.com/wp-content/uploads/2026/04/Internal-transport-in-Aleppo.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T20:30:44+03:00'::timestamptz, false, false, false, 162),
  ('وزارة الداخلية تقبض على متورطين بجريمة قتل بريف حمص', 'The Ministry of Interior arrests those involved in a murder in the Homs countryside', 'أعلنت وزارة الداخلية، الخميس 2 نيسان، أن مركز شرطة زيدل ألقى القبض على عدد من المتورطين في جريمة قتل المدعو إسماعيل مصطفى سفر من مدينة سلمية، والتي وقعت في شهر آذار الفائت على طريق زيدل – الجابرية بريف حمص. وأوضحت الوزارة، عبر منصاتها الرسمية، أنه بعد ورود بلاغ إلى مركز الشرطة في 14 آذار، كشفت […]', 'The Ministry of Interior announced, on Thursday, April 2, that the Zaidal Police Station arrested a number of those involved in the murder of Ismail Mustafa Safar from the city of Salamiya, which occurred last March on the Zaidal-Jabriya road in the Homs countryside. She explained The Ministry, through its official platforms, stated that after receiving a report to the police station on March 14, it revealed […]', 'أعلنت وزارة الداخلية، الخميس 2 نيسان، أن مركز شرطة زيدل ألقى القبض على عدد من المتورطين في جريمة قتل المدعو إسماعيل مصطفى سفر من مدينة سلمية، والتي وقعت في شهر آذار الفائت على طريق زيدل – الجابرية بريف حمص. وأوضحت الوزارة، عبر منصاتها الرسمية، أنه بعد ورود بلاغ إلى مركز الشرطة في 14 آذار، كشفت التحقيقات تورط المقبوض عليه “م.ع” بإقدامه على قتل المغدور بالاشتراك مع كل من “م.ط” و”م.ط”، إضافة إلى المتواري “ح.ط” الذي لا يزال البحث عنه جارياً لإلقاء القبض عليه. وأقر المقبوض عليه وشركاؤه بارتكاب عمليات سلب عدة في منطقة زيدل، كما اتخذت الإجراءات القانونية اللازمة بحقهم، فيما تستمر الجهات المختصة بملاحقة المتورط الفار تمهيداً لتقديمه إلى العدالة. وكانت قوى الأمن الداخلي في محافظة حلب ألقت القبض على مرتكب جريمة قتل رجل وطعن زوجته في حي بستان القصر في 19 آذار، عقب متابعة دقيقة وتحقيقات مكثفة أدت إلى تحديد هويته وموقعه. وبحسب المعلومات التي نشرتها مح', 'The Ministry of Interior announced, on Thursday, April 2, that the Zaidal Police Station arrested a number of those involved in the murder of Ismail Mustafa Safar from the city of Salamiya, which occurred last March on the Zaidal-Jabriya road in the Homs countryside. She explained The Ministry, through its official platforms, said that after a report was received at the police station on March 14, investigations revealed the involvement of the arrested person, “M.A.”, in his killing of the victim, in conjunction with “M.T.” and “M.T.”, in addition to the hidden person, “H.T.”, who is still being sought. is underway to arrest him. The arrested person and his accomplices admitted to committing several robberies in the Zaidel area, and the necessary legal measures were taken against them, while the competent authorities continue to pursue the fugitive involved in preparation for bringing him to justice. And it was The Internal Security Forces in Aleppo Governorate arrested the perpetrator of the crime of killing a man and stabbing his wife in the Bustan al-Qasr neighborhood on March 19, following careful follow-up and extensive investigations that led to determining his identity and location. According to the information published by M', 'https://alikhbariah.com/wp-content/uploads/2026/04/The-perpetrators-of-a-crime-in-Salamiyah-have-been-arrested.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T19:00:53+03:00'::timestamptz, false, false, false, 161),
  ('الدفاعات الإماراتية تتصدى لهجمات إيرانية.. وتعليق العمليات في منشآت حبشان للغاز', 'UAE defenses confront Iranian attacks... and suspend operations at Habshan gas facilities', 'أعلنت حكومة أبو ظبي، الجمعة 3 نيسان، تعليق العمليات في منشآت حبشان للغاز، إثر سقوط شظايا ناتج عن اعتراض دفاعاتها الجوية لصواريخ ومسيرات معادية، دون تسجيل أي إصابات. وقال مكتب أبو ظبي الإعلامي، في بيان نشره عبر منصة “إكس”، إن الجهات المختصة تتعامل مع حادثة سقوط شظايا في منشآت حبشان للغاز، بالتزامن مع اندلاع حريق […]', 'On Friday, April 3, the Abu Dhabi government announced the suspension of operations at the Habshan Gas facilities, following the fall of shrapnel resulting from its air defenses intercepting enemy missiles and drones, without recording any casualties. The Abu Dhabi Media Office said in a statement published on the platform “X”, the competent authorities are dealing with an incident of shrapnel falling at the Habshan Gas facilities, coinciding with the outbreak of a fire […]', 'أعلنت حكومة أبو ظبي، الجمعة 3 نيسان، تعليق العمليات في منشآت حبشان للغاز، إثر سقوط شظايا ناتج عن اعتراض دفاعاتها الجوية لصواريخ ومسيرات معادية، دون تسجيل أي إصابات. وقال مكتب أبو ظبي الإعلامي، في بيان نشره عبر منصة “إكس”، إن الجهات المختصة تتعامل مع حادثة سقوط شظايا في منشآت حبشان للغاز، بالتزامن مع اندلاع حريق تمت السيطرة عليه. وأضاف المكتب أن الجهات نفسها تعاملت أيضاً مع حادث مماثل في منطقة عجبان، مشدداً على عدم تداول الشائعات والالتزام بالمصادر الرسمية. وفي السياق، أعلنت وزارة الدفاع الإماراتية أن دفاعاتها الجوية تصدت لهجمات صاروخية وطائرات مسيرة قادمة من إيران ، مشيرة إلى أن الأصوات المسموعة في مناطق متفرقة ناتجة عن عمليات الاعتراض. وتشن إيران اعتداءات متواصلة بالصواريخ والمسيرات على عدة دول عربية بينها الإمارات، ما تسبب بسقوط ضحايا وأضرار مادية بالبنى التحتية، على خلفية التصعيد العسكري الناتج عن الحرب الأمريكية الإسرائيلية – الإيراني', 'On Friday, April 3, the Abu Dhabi government announced the suspension of operations at the Habshan Gas facilities, following the fall of shrapnel resulting from its air defenses intercepting enemy missiles and drones, without recording any casualties. The Abu Dhabi Media Office said in a statement published on the platform “X”, the competent authorities are dealing with an incident where fragments fell at the Habshan Gas facilities, coinciding with the outbreak of a fire that was controlled. The office added that the same authorities also dealt with a similar incident in the Ajban area, stressing that rumors were not circulating And adherence to official sources. In this context, the UAE Ministry of Defense announced that its air defenses responded to missile and drone attacks coming from Iran, noting that the sounds heard in separate areas resulted from interception operations. And Chen Iran continues attacks with missiles and marches on several Arab countries, including the UAE, causing casualties and material damage to infrastructure, against the backdrop of the military escalation resulting from the American-Israeli-Iranian war.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Habshan-facilities.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T11:40:03+03:00'::timestamptz, false, true, false, 160),
  ('الكويت.. استهداف مصفاة ميناء الأحمدي والدفاعات الجوية تتصدى لهجمات صاروخية', 'Kuwait: Mina Al-Ahmadi refinery was targeted, and air defenses responded to missile attacks', 'أعلنت وزارة الدفاع الكويتية، الجمعة 3 نيسان، أن دفاعاتها الجوية تصدت لهجمات صاروخية وطائرات مسيرة استهدفت منشآتها الحيوية، مؤكدةً جاهزيتها للتعامل مع أي تهديدات تمس أمن البلاد وسيادتها. وقالت رئاسة هيئة الأركان الكويتية في بيان نشرته عبر منصة “إكس”: “تتصدى الدفاعات الجوية الكويتية حالياً لهجمات صاروخية ومسيرات معادية”. وفي السياق، ذكرت مؤسسة البترول الكويتية أن […]', 'The Kuwaiti Ministry of Defense announced, on Friday, April 3, that its air defenses responded to missile and drone attacks that targeted its vital facilities, confirming its readiness to deal with any threats affecting the country’s security and sovereignty. The Kuwaiti Chief of Staff said In a statement published on the “X” platform: “Kuwait air defenses are currently responding to missile attacks and hostile marches.” In this context, the Kuwait Petroleum Corporation stated that […]', 'أعلنت وزارة الدفاع الكويتية، الجمعة 3 نيسان، أن دفاعاتها الجوية تصدت لهجمات صاروخية وطائرات مسيرة استهدفت منشآتها الحيوية، مؤكدةً جاهزيتها للتعامل مع أي تهديدات تمس أمن البلاد وسيادتها. وقالت رئاسة هيئة الأركان الكويتية في بيان نشرته عبر منصة “إكس”: “تتصدى الدفاعات الجوية الكويتية حالياً لهجمات صاروخية ومسيرات معادية”. وفي السياق، ذكرت مؤسسة البترول الكويتية أن مصفاة ميناء الأحمدي تعرّضت اليوم لاستهداف بطائرات مسيرة، ما أدى إلى اندلاع حرائق في عدد من الوحدات التشغيلية، موضحةً أن فرق الطوارئ والإطفاء باشرت تنفيذ خطط الاستجابة، واحتواء الحرائق ومنع امتدادها إلى المنشآت المجاورة. وأكدت المؤسسة أنه لم يتم تسجيل أي إصابات بشرية، وأنها اتخذت جميع الإجراءات الاحترازية لضمان سلامة العاملين وحماية المنشآت الحيوية. وكانت دولة الكويت أعلنت، السبت 28 آذار، تعرض مطارها الدولي لهجمات بطائرات مسيرة إيرانية، أسفرت عن أضرار ملموسة في نظام الرادار الخاص با', 'The Kuwaiti Ministry of Defense announced, on Friday, April 3, that its air defenses responded to missile and drone attacks that targeted its vital facilities, confirming its readiness to deal with any threats affecting the country’s security and sovereignty. The Kuwaiti Chief of Staff said In a statement published on the “X” platform: “Kuwait air defenses are currently responding to missile attacks and hostile marches.” In this context, the Kuwait Petroleum Corporation stated that Mina Al-Ahmadi refinery was targeted today by drones, which led to an outbreak of Fires broke out in a number of operational units, explaining that emergency and fire teams began implementing response plans, containing the fires and preventing them from spreading to neighboring facilities. The organization confirmed that no human injuries were recorded, and that it had taken all measures Precautionary measures to ensure the safety of workers and protect vital facilities. The State of Kuwait announced, on Saturday, March 28, that its international airport was subjected to attacks by Iranian drones, which resulted in significant damage to its radar system.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Kuwaiti-Ministry-of-Defense.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T08:40:04+03:00'::timestamptz, false, true, false, 159),
  ('الدفاع السعودية تعلن اعتراض وتدمير سبع طائرات مسيرة', 'Saudi Defense announces the interception and destruction of seven drones', 'أعلنت وزارة الدفاع السعودية، اليوم الجمعة 3 نيسان، اعتراض وتدمير سبع طائرات مسيرة خلال الساعات الماضية. وقال المتحدث باسم الوزارة اللواء الركن تركي المالكي في بيان نقلته وكالة الأنباء السعودية “واس”: إن قوات الدفاع الجوي تمكنت من اعتراض وتدمير سبع طائرات مسيرة. وكانت صحيفة “وول ستريت جورنال” الأمريكية أفادت، في 28 آذار الماضي، بأن قاعدة […]', 'Today, Friday, April 3, the Saudi Ministry of Defense announced the interception and destruction of seven drones during the past hours. Ministry spokesman, Major General Turki Al-Maliki, said in a statement carried by the Saudi News Agency “SPA”: The Defense Forces The air force was able to intercept and destroy seven drones. On March 28, the American newspaper “The Wall Street Journal” reported that the base […]', 'أعلنت وزارة الدفاع السعودية، اليوم الجمعة 3 نيسان، اعتراض وتدمير سبع طائرات مسيرة خلال الساعات الماضية. وقال المتحدث باسم الوزارة اللواء الركن تركي المالكي في بيان نقلته وكالة الأنباء السعودية “واس”: إن قوات الدفاع الجوي تمكنت من اعتراض وتدمير سبع طائرات مسيرة. وكانت صحيفة “وول ستريت جورنال” الأمريكية أفادت، في 28 آذار الماضي، بأن قاعدة الأمير سلطان الجوية في السعودية تعرضت لهجوم إيراني، أسفر عن إصابة 12 عسكرياً أمريكياً، بينهم اثنان بجروح بالغة و10 بارتجاج في الدماغ، مشيرة إلى أن صاروخاً واحداً على الأقل وعدة مسيرات أصابت القاعدة وألحقت أضراراً بعدة طائرات أمريكية للتزود بالوقود. وأوضحت الصحيفة أن هذه الضربة تعد الثانية على الأقل التي تستهدف القاعدة خلال الحرب ضد إيران، لافتة إلى أن الضربة السابقة التي جرت في 14 آذار الجاري أوقعت أضراراً بـ5 طائرات تزود بالوقود. وتأتي هذه الهجمات في ظل تصاعد الحرب الأمريكية الإسرائيلية – الإيرانية المستم', 'Today, Friday, April 3, the Saudi Ministry of Defense announced the interception and destruction of seven drones during the past hours. Ministry spokesman, Major General Turki Al-Maliki, said in a statement carried by the Saudi News Agency “SPA”: The Defense Forces The air force was able to intercept and destroy seven drones. On March 28, the American newspaper “The Wall Street Journal” reported that Prince Sultan Air Base in Saudi Arabia was subjected to an Iranian attack, which resulted in the injury of 12 American soldiers, including Two were seriously injured and 10 suffered concussions, noting that at least one missile and several drones hit the base and damaged several American refueling planes. The newspaper explained that this was at least the second strike targeting Al-Qaeda during the war against Iran, pointing out that the previous strike, which took place on March 14, damaged 5 aircraft refueling. These attacks come in light of the continuing escalation of the American-Israeli-Iranian war', 'https://alikhbariah.com/wp-content/uploads/2026/04/Saudi-Ministry-of-Defense-3.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T08:20:47+03:00'::timestamptz, false, false, false, 158),
  ('ترامب يحدد الأهداف القادمة.. الجسور ثم محطات الكهرباء', 'Trump sets the next goals: bridges, then power plants', 'قال الرئيس الأمريكي دونالد ترامب، الجمعة 3 نيسان، إن “الجيش الأمريكي هو الأقوى في العالم وبفارق كبير”، مضيفاً أن قيادة النظام الجديد في إيران تدرك ما يجب القيام به، وتدرك أنه يجب أن يُنجز بسرعة. وأوضح ترامب، في منشور على منصة “تروث سوشال”، أن الجيش الأمريكي لم يبدأ بعد بتدمير ما تبقى في إيران، مؤكداً […]', 'US President Donald Trump said on Friday, April 3, that “the American army is the strongest in the world by a large margin,” adding that the leadership of the new regime in Iran realizes what must be done, and realizes that it must be accomplished quickly. Trump explained, in a post On the “Truth Social” platform, the US army has not yet begun to destroy what remains in Iran, confirming […]', 'قال الرئيس الأمريكي دونالد ترامب، الجمعة 3 نيسان، إن “الجيش الأمريكي هو الأقوى في العالم وبفارق كبير”، مضيفاً أن قيادة النظام الجديد في إيران تدرك ما يجب القيام به، وتدرك أنه يجب أن يُنجز بسرعة. وأوضح ترامب، في منشور على منصة “تروث سوشال”، أن الجيش الأمريكي لم يبدأ بعد بتدمير ما تبقى في إيران، مؤكداً أن الأهداف القادمة ستكون الجسور أولاً، ثم محطات توليد الكهرباء. وسبق أن توعد الرئيس الأمريكي بضرب جميع محطات الطاقة في إيران إذا لم تصل إلى اتفاق مع طهران، مشيراً في خطاب متلفز الخميس 2 نيسان، إلى أن بلاده “ستعيد إيران إلى العصر الحجري”. ولفت إلى أن تغيير النظام الإيراني لم يكن هدفاً للحرب، ولكنه قد وقع بالفعل، موضحاً أن المواقع النووية الإيرانية أصبحت ركاماً، ولا يمكن لأحد الاقتراب من غبارها النووي لشهور.', 'US President Donald Trump said on Friday, April 3, that “the American army is the strongest in the world by a large margin,” adding that the leadership of the new regime in Iran realizes what must be done, and realizes that it must be accomplished quickly. Trump explained, in a post On the “Truth Social” platform, the US army has not yet begun to destroy what remains in Iran, stressing that the next targets will be bridges first, then power plants. The US President had previously vowed to strike all power plants in Iran if they did not He reached an agreement with Tehran, indicating in a televised speech on Thursday, April 2, that his country would “return Iran to the Stone Age.” He pointed out that changing the Iranian regime was not the goal of the war, but it had already occurred, explaining that the Iranian nuclear sites It has become rubble, and no one can approach its nuclear fallout for months.', 'https://alikhbariah.com/wp-content/uploads/2026/04/US-President-Donald-Trump.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-03T07:45:06+03:00'::timestamptz, false, false, false, 157),
  ('أبو الغيط يطالب مجلس الأمن باتخاذ إجراءات لوقف الاعتداءات الإيرانية على الدول العربية', 'Aboul Gheit calls on the Security Council to take measures to stop Iranian attacks on Arab countries', 'أكد الأمين العام لجامعة الدول العربية، أحمد أبو الغيط، أنه أدان في خطابه أمام مجلس الأمن الدولي بأشد العبارات الاعتداءات الإيرانية بالصواريخ والطائرات المسيّرة على الدول العربية، واصفاً إياها بأنها انتهاك صارخ للقانون الدولي وميثاق الأمم المتحدة. وقال أبو الغيط في سلسلة تدوينات نشرها على حسابه عبر منصة X الجمعة 3 نيسان، إن استهداف المنشآت […]', 'The Secretary-General of the League of Arab States, Ahmed Aboul Gheit, confirmed that in his speech before the UN Security Council, he condemned in the strongest terms the Iranian attacks with missiles and drones on Arab countries, describing them as a blatant violation of the law. International and the Charter of the United Nations. Aboul Gheit said in a series of blog posts published on his account on the X platform on Friday, April 3, that targeting the facilities […]', 'أكد الأمين العام لجامعة الدول العربية، أحمد أبو الغيط، أنه أدان في خطابه أمام مجلس الأمن الدولي بأشد العبارات الاعتداءات الإيرانية بالصواريخ والطائرات المسيّرة على الدول العربية، واصفاً إياها بأنها انتهاك صارخ للقانون الدولي وميثاق الأمم المتحدة. وقال أبو الغيط في سلسلة تدوينات نشرها على حسابه عبر منصة X الجمعة 3 نيسان، إن استهداف المنشآت المدنية والبنية التحتية في الدول العربية يُشكّل جريمة لا يمكن تبريرها تحت أي ذريعة، داعياً إلى توقّف هذه الاعتداءات فوراً. وطالب أبو الغيط مجلس الأمن باتخاذ إجراءات حازمة تلزم إيران بوقف اعتداءاتها وتحميلها المسؤولية الكاملة عن تبعاتها. وأشار إلى أن حرية الملاحة في مضيق هرمز وباب المندب تمثّل خطاً أحمر، مؤكداً أن أي تهديد لها يُعد مساساً بالأمن العالمي، وليس الإقليمي فقط. كما جدّد أبو الغيط التأكيد على أن القضية الفلسطينية ستظل في صدارة الأولويات العربية، مشدّداً على أن تحقيق الاستقرار في المنطقة مرهون ب', 'The Secretary-General of the League of Arab States, Ahmed Aboul Gheit, confirmed that in his speech before the UN Security Council, he condemned in the strongest terms the Iranian attacks with missiles and drones on Arab countries, describing them as a blatant violation of the law. International and the Charter of the United Nations. Aboul Gheit said in a series of blog posts published on his account on the X platform on Friday, April 3, that targeting civilian facilities and infrastructure in Arab countries constitutes a crime that cannot be justified under any pretext, calling for... Stop these attacks immediately. Aboul Gheit called on the Security Council to take firm measures to oblige Iran to stop its attacks and hold it fully responsible for their consequences. He pointed out that freedom of navigation in the Strait of Hormuz and Bab al-Mandab represents a red line, stressing that Any threat to it constitutes a violation of global security, not just regional security. Aboul Gheit also reiterated that the Palestinian issue will remain at the top of Arab priorities, stressing that achieving stability in the region depends on', 'https://alikhbariah.com/wp-content/uploads/2026/04/Aboul-Gheit-calls-on-the-Security-Council-to-take-measures-to-stop-Iranian-attacks-on-Arab-countries.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T23:34:07+03:00'::timestamptz, false, false, false, 156),
  ('أمين عام مجلس التعاون الخليجي: سلوك إيران تجاوز الخطوط الحمراء', 'Secretary-General of the Gulf Cooperation Council: Iran''s behavior has crossed red lines', 'قال أمين عام مجلس التعاون الخليجي جاسم البديوي، الخميس 2 نيسان، إن سلوك إيران تجاوز الخطوط الحمراء. وأكد البديوي في كلمته أمام مجلس الأمن، أن دول الخليج لا تدعو للحرب، مشدداً على حق دول المجلس الأصيل في الدفاع عن النفس. وفي 27 آذار الماضي، كشفت بيانات رسمية أن إيران وجهت نحو 83% من مجمل هجماتها […]', 'The Secretary-General of the Gulf Cooperation Council, Jassem Al-Budaiwi, said on Thursday, April 2, that Iran’s behavior crossed red lines. In his speech before the Security Council, Al-Budaiwi stressed that the Gulf states do not call for war, stressing the inherent right of the Council states to self-defense. On March 27, official data revealed that Iran directed about 83% of its total attacks […]', 'قال أمين عام مجلس التعاون الخليجي جاسم البديوي، الخميس 2 نيسان، إن سلوك إيران تجاوز الخطوط الحمراء. وأكد البديوي في كلمته أمام مجلس الأمن، أن دول الخليج لا تدعو للحرب، مشدداً على حق دول المجلس الأصيل في الدفاع عن النفس. وفي 27 آذار الماضي، كشفت بيانات رسمية أن إيران وجهت نحو 83% من مجمل هجماتها بالصواريخ والمسيرات منذ انطلاق الحرب في 28 شباط الماضي إلى دول الخليج العربية، مقابل 17% فقط استهدفت إسرائيل، في تصعيد خطير يهدد أمن المنطقة واستقرارها. وأظهر إحصاء استند إلى البيانات الرسمية التي أعلنتها الدول المستهدفة عن الاعتداءات الإيرانية، أنه حتى مساء الأربعاء 25 آذار، بلغ إجمالي ما أطلقته إيران من صواريخ ومسيرات 5321 هجوماً، بواقع 4391 منها على دول الخليج العربية، و930 هجوماً استهدفت إسرائيل، وفق ما أوردته صحيفة “الشرق الأوسط”. وكان للإمارات النصيب الأكبر من الاعتداءات التي طالتها بـ2156 هجمة، واستهدفت إيران السعودية بـ723 صاروخاً ومسيّرة م', 'The Secretary-General of the Gulf Cooperation Council, Jassem Al-Budaiwi, said on Thursday, April 2, that Iran’s behavior crossed red lines. In his speech before the Security Council, Al-Budaiwi stressed that the Gulf states do not call for war, stressing the inherent right of the Council states to self-defense. On March 27, official data revealed that Iran had directed about 83% of its total missile and drone attacks since the start of the war on February 28 to the Arab Gulf states, compared to only 17% that targeted Israel, in a dangerous escalation that threatens the security of the region. And its stability. A statistic based on official data announced by the targeted countries regarding the Iranian attacks showed that, as of the evening of Wednesday, March 25, the total number of missiles and drones launched by Iran reached 5,321 attacks, with 4,391 of them on countries. Gulf Arab News, and 930 attacks targeted Israel, according to what was reported by Asharq Al-Awsat newspaper. The UAE had the largest share of attacks, with 2,156 attacks, and Iran targeted Saudi Arabia with 723 missiles and drones.', 'https://alikhbariah.com/wp-content/uploads/2026/04/jasem-albediwe.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T18:30:48+03:00'::timestamptz, false, false, false, 155),
  ('رئيس الوزراء اللبناني: نجدد الرفض التام لأي عمل عسكري خارج مؤسسات الدولة', 'Lebanese Prime Minister: We renew our complete rejection of any military action outside state institutions', 'أكد رئيس الوزراء اللبناني نواف سلام، رفضه التام لأي عمل عسكري خارج مؤسسات الدولة الشرعية، مؤكداً أنّ قرار الحرب والسلم يجب أن يبقى حصراً بيد الدولة. وقال سلام في تصريحات نشرتها الوكالة اللبنانية للإعلام الخميس 2 نيسان: “حذرنا مرراً من حرب مدمرة فُرضت على بلادنا”، مجدداً حرصه على تجنيب لبنان مزيداً من المآسي والخسائر جراء […]', 'Lebanese Prime Minister Nawaf Salam affirmed his complete rejection of any military action outside the legitimate state institutions, stressing that the decision of war and peace must remain exclusively in the hands of the state. Salam said in statements published by the Lebanese Information Agency on Thursday, April 2: “We have repeatedly warned of a devastating war imposed on our country,” reiterating his keenness to spare Lebanon from further tragedies and losses as a result of […]', 'أكد رئيس الوزراء اللبناني نواف سلام، رفضه التام لأي عمل عسكري خارج مؤسسات الدولة الشرعية، مؤكداً أنّ قرار الحرب والسلم يجب أن يبقى حصراً بيد الدولة. وقال سلام في تصريحات نشرتها الوكالة اللبنانية للإعلام الخميس 2 نيسان: “حذرنا مرراً من حرب مدمرة فُرضت على بلادنا”، مجدداً حرصه على تجنيب لبنان مزيداً من المآسي والخسائر جراء الاعتداء على سيادته ومدنه وقراه. وأضاف: “لا مصلحة وطنية للبنان في حروب الآخرين، ونرفض ربط أرضنا بعمليات عسكرية مشتركة مع أي طرف”. وجدد رئيس الوزراء اللبناني رفض بلاده الحديث عن مناطق عازلة وأحزمة أمنية على أرض لبنان، وتهجير أكثر من مليون شخص، مشيراً إلى أن العمل مستمر على تعزيز القدرات، ودعم إيواء النازحين وضمان أمنهم وأمن المجتمعات المضيفة. وأشار إلى أن الحكومة اللبنانية تكثّف مساعيها الدبلوماسية لوقف التعديات على السيادة، وإدانة خروقات القانون الدولي، لافتاً إلى أن الهجوم الإسرائيلي لا يقتصر على العمليات العسكرية المعهو', 'Lebanese Prime Minister Nawaf Salam affirmed his complete rejection of any military action outside the legitimate state institutions, stressing that the decision of war and peace must remain exclusively in the hands of the state. Salam said in statements published by the Lebanese Information Agency on Thursday, April 2: “We repeatedly warned of a devastating war imposed on our country,” reiterating his keenness to spare Lebanon from further tragedies and losses as a result of the attacks on its sovereignty, cities, and villages. He added: “Lebanon has no national interest in other people’s wars, and we refuse to link our land with military operations.” Shared with any party.” The Lebanese Prime Minister reiterated his country’s refusal to talk about buffer zones and security belts on Lebanese soil, and the displacement of more than a million people, indicating that work continues to strengthen capabilities, support the shelter of the displaced, and ensure their security and that of host communities. He pointed out that the Lebanese government is intensifying its diplomatic efforts to stop infringements on sovereignty and condemn violations of international law, pointing out that the Israeli attack is not limited to conventional military operations.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Nawaf-Salam.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T12:00:12+03:00'::timestamptz, false, false, false, 154),
  ('الرئيس الفرنسي: مضيق هرمز استراتيجي للطاقة ويجب إعادة فتحه عبر مسار دبلوماسي', 'French President: The Strait of Hormuz is strategic for energy and must be reopened through a diplomatic path', 'أكد الرئيس الفرنسي إيمانويل ماكرون أن “مضيق هرمز استراتيجي للطاقة، ويجب إعادة فتحه عبر مسار دبلوماسي لا عسكري”، مشيراً إلى أن خيار فتحه بالقوة غير واقعي، وسيستغرق وقتاً طويلاً ويحمل مخاطر كبيرة. وقال في تصريحات نشرها قصر الإليزيه عبر منصة “إكس”، الخميس 2 نيسان، “نسعى إلى بناء مسارات دبلوماسية لوقف إطلاق النار وضمان حرية الملاحة […]', 'French President Emmanuel Macron stressed that “the Strait of Hormuz is strategic for energy, and must be reopened through a diplomatic, not military, path,” indicating that the option of opening it by force is unrealistic, will take a long time and carry great risks. He said in published statements Elysee Palace via the “X” platform, Thursday, April 2, “We seek to build diplomatic paths for a ceasefire and ensure freedom of navigation […]', 'أكد الرئيس الفرنسي إيمانويل ماكرون أن “مضيق هرمز استراتيجي للطاقة، ويجب إعادة فتحه عبر مسار دبلوماسي لا عسكري”، مشيراً إلى أن خيار فتحه بالقوة غير واقعي، وسيستغرق وقتاً طويلاً ويحمل مخاطر كبيرة. وقال في تصريحات نشرها قصر الإليزيه عبر منصة “إكس”، الخميس 2 نيسان، “نسعى إلى بناء مسارات دبلوماسية لوقف إطلاق النار وضمان حرية الملاحة في مضيق هرمز”، مؤكداً ضرورة خفض التصعيد، والتوصل إلى وقف لإطلاق النار في الشرق الأوسط. وأوضح ماكرون أن “المفاوضات وحدها يمكنها أن تحل الصراع في الشرق الأوسط”، مشيراً إلى ضرورة استئناف المفاوضات كسبيل وحيد لحل النزاع، ومؤكداً أن” أمن الملاحة وتدفق الطاقة والمنتجات رهن بإنهاء الحرب”. وأضاف أنه “يمكن التحقق من وقف تخصيب اليورانيوم في إيران تحت مظلة الوكالة الدولية للطاقة الذرية وليس بالعملية العسكرية”، مبيناً أنه من دون تفتيش دولي جدي لا يمكن الحديث عن معالجة حقيقية للملف النووي الإيراني. وأشار الرئيس الفرنسي إلى ضرور', 'French President Emmanuel Macron stressed that “the Strait of Hormuz is strategic for energy, and must be reopened through a diplomatic, not military, path,” indicating that the option of opening it by force is unrealistic, will take a long time and carry great risks. He said in published statements Elysee Palace, via the “X” platform, Thursday, April 2, said, “We seek to build diplomatic paths for a ceasefire and ensure freedom of navigation in the Strait of Hormuz,” stressing the necessity of reducing escalation and reaching a ceasefire in the Middle East. Macron explained that “Negotiations alone can resolve the conflict in the Middle East,” pointing to the necessity of resuming negotiations as the only way to resolve the conflict, stressing that “the security of navigation and the flow of energy and products depends on ending the war.” He added, “It is possible to verify the cessation of enrichment The uranium in Iran is under the umbrella of the International Atomic Energy Agency and not the military operation,” indicating that without serious international inspection it is not possible to talk about a real treatment of the Iranian nuclear file. The French President pointed out the necessity', 'https://alikhbariah.com/wp-content/uploads/2026/04/French-President.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T11:45:58+03:00'::timestamptz, false, false, false, 153),
  ('ترامب: إذا لم نتوصل إلى اتفاق سنضرب جميع محطات الطاقة في إيران', 'Trump: If we do not reach an agreement, we will strike all power plants in Iran', 'توعد الرئيس الأمريكي دونالد ترامب، بضرب جميع محطات الطاقة في إيران إذا لم تصل واشنطن وطهران إلى اتفاق. وقال ترامب في خطاب متلفز وجّهه للشعب الأمريكي بشأن الحرب، الخميس 2 نيسان: “سنعيد إيران إلى العصر الحجري”. وتوعد ترامب بضرب إيران “بقوة شديدة” خلال الأسبوعين إلى ثلاثة الأسابيع المقبلة، وأضاف: “الليلة هي بداية النهاية لشرور العدوان […]', 'US President Donald Trump has vowed to strike all power plants in Iran if Washington and Tehran do not reach an agreement. Trump said in a televised speech addressed to the American people regarding the war, Thursday, April 2: “We will return Iran to the Stone Age.” And he promised Trump will strike Iran “very forcefully” over the next two to three weeks, adding: “Tonight is the beginning of the end for the evils of aggression […]', 'توعد الرئيس الأمريكي دونالد ترامب، بضرب جميع محطات الطاقة في إيران إذا لم تصل واشنطن وطهران إلى اتفاق. وقال ترامب في خطاب متلفز وجّهه للشعب الأمريكي بشأن الحرب، الخميس 2 نيسان: “سنعيد إيران إلى العصر الحجري”. وتوعد ترامب بضرب إيران “بقوة شديدة” خلال الأسبوعين إلى ثلاثة الأسابيع المقبلة، وأضاف: “الليلة هي بداية النهاية لشرور العدوان الإيراني وشبح الابتزاز النووي الذي هدد العالم”. وأشار ترامب إلى أن الدفاعات الجوية الإيرانية أصبحت منعدمة تماماً، كما أن أنظمة الرادار مُحيت بنسبة 100%. ولفت الرئيس الأمريكي في خطابه إلى أن تغيير النظام الإيراني لم يكن هدفاً للحرب، ولكنه قد وقع بالفعل، موضحاً أن المواقع النووية الإيرانية أصبحت ركاماً، ولا يمكن لأحد الاقتراب من غبارها النووي لشهور. وكان ترامب قد أعلن أنه يفكر جدياً في الانسحاب من حلف شمال الأطلسي “ الناتو ”، بعد فشل الحلف في الانضمام إلى حربه على إيران، واصفاً الحلف بأنه أصبح “نمراً من ورق”، في ', 'US President Donald Trump has vowed to strike all power plants in Iran if Washington and Tehran do not reach an agreement. Trump said in a televised speech addressed to the American people regarding the war, Thursday, April 2: “We will return Iran to the Stone Age.” And he promised Trump will strike Iran “very hard” over the next two to three weeks, adding: “Tonight is the beginning of the end for the evils of Iranian aggression and the specter of nuclear blackmail that threatened the world.” Trump pointed out that Iranian air defenses have become... It is completely non-existent, and the radar systems have been wiped out 100%. In his speech, the American President pointed out that changing the Iranian regime was not a goal of war, but it had already occurred, explaining that the Iranian nuclear sites had become rubble, and no one could Getting close to its nuclear fallout for months. Trump had announced that he was seriously considering withdrawing from NATO, after the alliance failed to join its war on Iran, describing the alliance as having become a “paper tiger,” in', 'https://alikhbariah.com/wp-content/uploads/2026/03/US-President-2.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T10:58:05+03:00'::timestamptz, false, false, false, 152),
  ('المفوضية الأوروبية: تصرفات إيران تهدد الاستقرار الاقتصادي العالمي', 'European Commission: Iran''s actions threaten global economic stability', 'قالت رئيسة المفوضية الأوروبية أورسولا فون دير لاين: إن “تصرفات إيران تعرّض الاستقرار الاقتصادي العالمي للخطر”، مشددة على أهمية الحفاظ على أمن الملاحة الدولية. وأكدت في تدوينة على حسابها في منصة “إكس”، الخميس 2 نيسان، أن الاتحاد الأوروبي سيعمل بالتعاون مع شركائه الدوليين لضمان استئناف حرية الملاحة في مضيق هرمز في أقرب وقت ممكن. ودعا […]', 'European Commission President Ursula von der Leyen said: “Iran’s actions endanger global economic stability,” stressing the importance of maintaining the security of international navigation. She confirmed in a blog post on her account on the “X” platform, Thursday, April 2, that The European Union will work in cooperation with its international partners to ensure the resumption of freedom of navigation in the Strait of Hormuz as soon as possible. He called […]', 'قالت رئيسة المفوضية الأوروبية أورسولا فون دير لاين: إن “تصرفات إيران تعرّض الاستقرار الاقتصادي العالمي للخطر”، مشددة على أهمية الحفاظ على أمن الملاحة الدولية. وأكدت في تدوينة على حسابها في منصة “إكس”، الخميس 2 نيسان، أن الاتحاد الأوروبي سيعمل بالتعاون مع شركائه الدوليين لضمان استئناف حرية الملاحة في مضيق هرمز في أقرب وقت ممكن. ودعا الرئيس الأمريكي دونالد ترامب دول العالم التي تستورد النفط عبر مضيق هرمز إلى تحمل مسؤولية حماية هذا الممر الملاحي. وربط الرئيس الأمريكي، أمس الأربعاء، إمكانية النظر في وقف إطلاق النار على إيران بفتح مضيق هرمز وضمان حرية الملاحة فيه، مشدداً على أن العمليات العسكرية ستستمر إلى حين تحقيق ذلك. يذكر أن إيران أعلنت إغلاق المضيق بعد الضربات العسكرية الواسعة التي شنّتها الولايات المتحدة وإسرائيل على أراضيها والمتواصلة منذ 28 شباط الماضي، ما أدى إلى تعطيل شبه كامل للملاحة الدولية، وخلق أزمة طاقة عالمية واضطراب في سلاسل ا', 'European Commission President Ursula von der Leyen said: “Iran’s actions endanger global economic stability,” stressing the importance of maintaining the security of international navigation. She confirmed in a blog post on her account on the “X” platform, Thursday, April 2, that The European Union will work in cooperation with its international partners to ensure the resumption of freedom of navigation in the Strait of Hormuz as soon as possible. US President Donald Trump called on countries around the world that import oil through the Strait of Hormuz to bear responsibility for protecting this corridor Navigator. Yesterday, Wednesday, the American President linked the possibility of considering a ceasefire on Iran to opening the Strait of Hormuz and ensuring freedom of navigation in it, stressing that military operations will continue until this is achieved. It is noteworthy that Iran announced the closure of the strait After the massive military strikes launched by the United States and Israel on its territory, which have continued since February 28, which led to an almost complete disruption of international navigation, and the creation of a global energy crisis and disruption in energy chains.', 'https://alikhbariah.com/wp-content/uploads/2026/04/President-of-the-European-Commission.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T09:30:06+03:00'::timestamptz, false, false, false, 151),
  ('سوريا تكتسح أفغانستان بخماسية وتتأهل إلى نهائيات كأس آسيا متصدرة بالعلامة الكاملة', 'Syria sweeps Afghanistan by five and qualifies for the Asian Cup finals with a perfect score', 'اختتم منتخبنا الوطني لكرة القدم مشواره في التصفيات الآسيوية المؤهلة إلى النهائيات بنتيجة كبيرة، بعدما حقق فوزاً عريضاً على منتخب أفغانستان بنتيجة خمسة أهداف مقابل هدف واحد، في المباراة التي جمعتهما على ملعب الأمير عبد الله الفيصل في مدينة جدة السعودية. وسجل اللاعب محمد الصلخدي هدف المنتخب الأول في الدقيقة الخامسة، وواصل المنتخب سيطرته، لكنه […]', 'Our national football team concluded its campaign in the Asian qualifiers for the finals with a great result, after achieving a broad victory over the Afghanistan national team with a score of five goals to one, in the match that brought them together at Prince Abdul Stadium. God Almighty in Jeddah, Saudi Arabia. Player Mohamed Al-Salkhadi scored the first team’s goal in the fifth minute, and the team continued its control, but […]', 'اختتم منتخبنا الوطني لكرة القدم مشواره في التصفيات الآسيوية المؤهلة إلى النهائيات بنتيجة كبيرة، بعدما حقق فوزاً عريضاً على منتخب أفغانستان بنتيجة خمسة أهداف مقابل هدف واحد، في المباراة التي جمعتهما على ملعب الأمير عبد الله الفيصل في مدينة جدة السعودية. وسجل اللاعب محمد الصلخدي هدف المنتخب الأول في الدقيقة الخامسة، وواصل المنتخب سيطرته، لكنه أهدر فرصة تعزيز النتيجة عندما أضاع محمود الأسود ركلة جزاء. ورغم الاستحواذ، نجح منتخب أفغانستان في مفاجأة أصحاب الأرض بهجمة وحيدة انتهت بتسجيل كابتن الفريق علي رضا هدف التعادل في الدقيقة 21 لينتهي الشوط الأول بالتعادل هدف لهدف. وفي الشوط الثاني، ظهر المنتخب الوطني بشكل مغاير، وتمكن كابتن الفريق محمد الحلاق من كسر التعادل بهدف في الدقيقة 53. وبعد دقيقة واحدة فقط من نزوله بديلاً لأنس دهان، عزز البديل محمد مصطفى النتيجة بهدف ثالث في الدقيقة 58. ونجح اللاعب محمد مصطفى في تسجيل هدفه الشخصي الثاني والرابع للم', 'Our national football team concluded its campaign in the Asian qualifiers for the finals with a great result, after achieving a broad victory over the Afghanistan national team with a score of five goals to one, in the match that brought them together at Prince Abdul Stadium. God Almighty in Jeddah, Saudi Arabia. Player Mohamed Al-Salkhadi scored the first team''s goal in the fifth minute, and the team continued its control, but wasted the opportunity to increase the score when Mahmoud Al-Aswad missed a penalty kick. Despite the possession, the Afghanistan team succeeded The home team surprised the hosts with a single attack that ended with team captain Ali Reda scoring the equalizer in the 21st minute, ending the first half in a goal-to-goal draw. In the second half, the national team appeared in a different way, and the team captain, Mohamed Al-Hallaq, was able to break the score The equalizer was tied with a goal in the 53rd minute. Only one minute after coming on as a substitute for Anas Dahan, substitute Mohamed Mostafa increased the score with a third goal in the 58th minute. The player, Mohamed Mostafa, succeeded in scoring his second and fourth personal goal for the team.', 'https://alikhbariah.com/wp-content/uploads/2026/03/Syrian-national-team-3.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-31T19:28:48+03:00'::timestamptz, false, true, false, 150),
  ('فضية لسوريا في بطولة أنطاليا الدولية للمواي تاي', 'Silver for Syria in the Antalya International Muay Thai Championship', '​حقق لاعب منتخب سوريا لرياضة المواي تاي البطل سميان علي، الميدالية الفضية بوزن 71 كيلوغراماً، الأحد 29 آذار، في بطولة أنطاليا الدولية المفتوحة التي اختتمت منافساتها في تركيا بمشاركة واسعة من أبطال اللعبة على المستوى العربي والإقليمي والدولي. ​وأوضح رئيس اتحاد اللعبة حسان العلي، أن هذه الميدالية هي ثمرة أول مشاركة لرياضة المواي تاي السورية […]', '​Syrian Muay Thai national team player, champion Sumian Ali, won the silver medal with a weight of 71 kilograms, Sunday, March 29, in the Antalya International Open Championship, which concluded its competitions in Turkey with wide participation from the champions of the game at the level. Arab, regional and international. The head of the Federation, Hassan Al-Ali, explained that this medal is the result of the first participation in the sport of Syrian Muay Thai […]', '​حقق لاعب منتخب سوريا لرياضة المواي تاي البطل سميان علي، الميدالية الفضية بوزن 71 كيلوغراماً، الأحد 29 آذار، في بطولة أنطاليا الدولية المفتوحة التي اختتمت منافساتها في تركيا بمشاركة واسعة من أبطال اللعبة على المستوى العربي والإقليمي والدولي. ​وأوضح رئيس ا تحاد اللعبة حسان العلي، أن هذه الميدالية هي ثمرة أول مشاركة لرياضة المواي تاي السورية على الصعيد الخارجي لعام 2026، وجاء إنجاز البطل سميان ليؤكد التطور الواضح للمستوى الفني للاعبين بحسب ما نشرت جريدة الاتحاد الرياضي العام. ​وأشار العلي إلى أن هذه البطولة تعد من أهم البطولات التحضيرية قبل الاستحقاقات التي سيقيمها الاتحاد الدولي خلال هذا العام، حيث تندرج المشاركة ضمن خططه التحضيرية لتطوير أداء المنتخبات الوطنية. ​وأضاف أن خطة الاتحاد على الصعيد الخارجي تتضمن الكثير من المشاركات، متمنياً تحقيق ميداليات ومراكز أولى لأبطال وبطلات اللعبة في حال توفرت الظروف المناسبة للمشاركة للمنتخبات الوطنية ', '​Syrian Muay Thai national team player, champion Sumian Ali, won the silver medal with a weight of 71 kilograms, Sunday, March 29, in the Antalya International Open Championship, which concluded its competitions in Turkey with wide participation from the champions of the game at the level. Arab, regional and international. ​The President of the Federation, Hassan Al-Ali, explained that this medal is the result of the first participation of the Syrian Muay Thai sport on the foreign level in the year 2026, and the achievement of the champion Samian came to confirm the clear development of the technical level. For players, according to what was published in the General Sports Federation newspaper. Al-Ali pointed out that this tournament is one of the most important preparatory tournaments before the competitions that the International Federation will hold during this year, as participation falls within its preparatory plans to develop Performance of national teams. He added that the Federation’s plan at the external level includes many participations, hoping to achieve medals and first places for the champions and heroines of the game if the appropriate conditions are available for the national teams to participate.', 'https://alikhbariah.com/wp-content/uploads/2026/03/Antalya-International-Open-Championship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-30T02:44:01+03:00'::timestamptz, false, true, false, 149),
  ('حمص.. خطة خمسية لتأهيل المدينة الرياضية وإنشاء منشآت جديدة', 'Homs.. A five-year plan to rehabilitate the sports city and establish new facilities', 'أكد وزير الرياضة والشباب محمد سامح الحامض أن الوزارة تعمل على تأهيل المدينة الرياضية في حمص ضمن خطة تمتد لخمس سنوات. وتشمل الخطة إنشاء صالات متعددة الاستخدامات وملعباً رئيسياً ومرافق رياضية متكاملة، بالتوازي مع إطلاق أعمال صيانة في عدد من الملاعب، حسب وكالة سانا. وأوضح الحامض خلال جولة ميدانية في المحافظة برفقة محافظ حمص عبد […]', 'Minister of Sports and Youth, Muhammad Sameh Al-Hamid, confirmed that the ministry is working to rehabilitate the sports city in Homs within a five-year plan. The plan includes constructing multi-use halls, a main stadium, and integrated sports facilities, in parallel with the launch Maintenance work in a number of stadiums, according to SANA. Al-Hamid explained during a field tour in the governorate, accompanied by the Governor of Homs, Abdel […]', 'أكد وزير الرياضة والشباب محمد سامح الحامض أن الوزارة تعمل على تأهيل المدينة الرياضية في حمص ضمن خطة تمتد لخمس سنوات. وتشمل الخطة إنشاء صالات متعددة الاستخدامات وملعباً رئيسياً ومرافق رياضية متكاملة، بالتوازي مع إطلاق أعمال صيانة في عدد من الملاعب، حسب وكالة سانا . وأوضح الحامض خلال جولة ميدانية في المحافظة برفقة محافظ حمص عبد الرحمن الأعمى، أن المشروع يتضمن إنشاء ثلاث صالات لألعاب كرة اليد والطائرة والسلة، إضافة إلى ملاعب تدريبية ومسبح دولي وملاعب تنس. وأشار إلى أن التنفيذ سيبدأ وفق أولويات مدروسة عبر إنشاء صالتين وملعب تدريبي لكرة القدم، مع إعداد الدراسات اللازمة بالتنسيق مع المحافظة. وأضاف أن أعمال صيانة وترميم ملعب الساروت انطلقت بشكل كامل على نفقة الوزارة، إلى جانب تنفيذ أعمال صيانة لمرافق ومدرجات ملعب خالد بن الوليد. ولفت الحامض إلى أن سياسة الوزارة تركز على دعم الأندية وتخفيف الأعباء المالية عنها، من خلال إلغاء تكاليف التحكيم، وتخصي', 'Minister of Sports and Youth, Muhammad Sameh Al-Hamid, confirmed that the ministry is working to rehabilitate the sports city in Homs within a five-year plan. The plan includes constructing multi-use halls, a main stadium, and integrated sports facilities, in parallel with the launch Maintenance work in a number of stadiums, according to SANA. Al-Hamid explained during a field tour in the governorate, accompanied by the Governor of Homs, Abdul Rahman Al-Ama, that the project includes the establishment of three halls for handball, volleyball, and basketball, in addition to training fields. An international swimming pool and tennis courts. He pointed out that implementation will begin according to well-studied priorities by establishing two halls and a football training field, while preparing the necessary studies in coordination with the governorate. He added that the maintenance and restoration work on Al-Sarout Stadium has fully begun At the Ministry’s expense, in addition to carrying out maintenance work for the facilities and stands of Khaled Bin Al Waleed Stadium. Al-Hamed pointed out that the ministry’s policy focuses on supporting clubs and reducing their financial burdens, by eliminating arbitration costs and allocating', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Sports-visit-to-Homs.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-29T22:00:38+03:00'::timestamptz, false, false, false, 148),
  ('اختتام بطولة دمشق الدولية الأولى لفروسية قفز الحواجز بتأهل ثلاثة فرسان إلى قطر', 'The first Damascus International Show Jumping Equestrian Championship concluded with three riders qualifying for Qatar', 'اختتمت بطولة دمشق الدولية التأهيلية الأولى لفروسية قفز الحواجز، وذلك بعد منافسات استمرت يومين في نادي الفروسية المركزي بالديماس بريف دمشق. وبحسب ما نشرت وكالة “سانا“، الأحد 1 آذار، أسفرت النتائج النهائية عن تأهل ثلاثة فرسان إلى بطولة قطر الدولية المقررة في نيسان القادم بعد تحقيقهم النقاط التأهيلية المطلوبة. وذكرت الوكالة أن الفرسان المتأهلين هم […]', 'The first Damascus International Equestrian Qualifying Championship for show jumping was concluded after two days of competitions at the Central Equestrian Club in Dimas in the Damascus countryside. According to what was published by “SANA” agency, on Sunday, March 1, the final results resulted in three qualifications Knights will advance to the Qatar International Championship scheduled for next April after achieving the required qualifying points. The agency stated that the qualified riders are […]', 'اختتمت بطولة دمشق الدولية التأهيلية الأولى لفروسية قفز الحواجز، وذلك بعد منافسات استمرت يومين في نادي الفروسية المركزي بالديماس بريف دمشق. وبحسب ما نشرت وكالة “ سانا “، الأحد 1 آذار، أسفرت النتائج النهائية عن تأهل ثلاثة فرسان إلى بطولة قطر الدولية المقررة في نيسان القادم بعد تحقيقهم النقاط التأهيلية المطلوبة. وذكرت الوكالة أن الفرسان المتأهلين هم زيد أكريم بفئة الأطفال وجوري بحبوح بفئة جونيور ومحمد أبو زيد بفئة يونغ، حيث حصل كل منهم على 11 نقطة في ختام منافسات هذه البطولة. وأقيمت منافسات اليوم الثاني والختامي لبطولة دمشق الدولية التأهيلية الأولى على شوطين، الأول أصلي والثاني جولة للتمايز لكل فئة من الفئات الثلاث على حدة، علماً أن ارتفاع الحواجز في الجولة النهائية بلغ 115 سم لفئة الأطفال و125 سم لفئة جونيور و135 سم لفئة يونغ. وتنظم منافسات بطولة دمشق الدولية التأهيلية الثانية يومي الجمعة والسبت القادمين، على أرض نادي الفروسية المركزي بالدي', 'The first Damascus International Equestrian Qualifying Championship for show jumping was concluded after two days of competitions at the Central Equestrian Club in Dimas in the Damascus countryside. According to what was published by “SANA” agency, on Sunday, March 1, the final results resulted in three qualifications Knights will advance to the Qatar International Championship scheduled for next April after achieving the required qualifying points. The agency stated that the qualified riders were Zaid Akram in the children’s category, Juri Bahbouh in the junior category, and Muhammad Abu Zaid in the young category, where each of them won 11 points at the end of this tournament. The competitions of the second and final day of the first Damascus International Qualifying Championship were held in two rounds, the first an original round and the second a differentiation round for each of the three categories separately, noting that the height of the barriers in The final round reached 115 cm for the children''s category, 125 cm for the junior category, and 135 cm for the young category. The second Damascus International Qualifying Championship competitions will be held next Friday and Saturday, on the grounds of the Central Equestrian Club in Diy', 'https://alikhbariah.com/wp-content/uploads/2026/03/Damascus-Equestrian-Championship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-01T10:35:34+03:00'::timestamptz, false, false, false, 147),
  ('تأجيل مباراة منتخبنا الوطني وإيران في تصفيات كأس العالم لكرة السلة', 'The match between our national team and Iran in the Basketball World Cup qualifiers was postponed', 'أعلن الاتحاد العربي السوري لكرة السلة تأجيل مباراة منتخبنا الوطني أمام نظيره الإيراني والتي كانت مقررة في 2 آذار المقبل في العاصمة اللبنانية بيروت، ضمن منافسات التصفيات الآسيوية المؤهلة لكأس العالم 2027. وأوضح الاتحاد في بيان نشره عبر معرفاته الرسمية السبت 28 شباط، أن تأجيل المباراة يأتي بناءً على قرار الاتحاد الدولي لكرة السلة لأسباب […]', 'The Syrian Arab Basketball Federation announced the postponement of our national team’s match against its Iranian counterpart, which was scheduled for next March 2 in the Lebanese capital, Beirut, as part of the Asian qualifiers for the 2027 World Cup. The Federation explained In a statement published through its official handles on Saturday, February 28, the postponement of the match comes based on the decision of the International Basketball Federation for reasons […]', 'أعلن الاتحاد العربي السوري لكرة السلة تأجيل مباراة منتخبنا الوطني أمام نظيره الإيراني والتي كانت مقررة في 2 آذار المقبل في العاصمة اللبنانية بيروت، ضمن منافسات التصفيات الآسيوية المؤهلة لكأس العالم 2027. وأوضح الاتحاد في بيان نشره عبر معرفاته الرسمية السبت 28 شباط، أن تأجيل المباراة يأتي بناءً على قرار الاتحاد الدولي لكرة السلة لأسباب تتعلق بسلامة وأمن المنتخبات المشاركة وضمان سلامة المنافسات. وذكر أن المباراة ستقام في نافذة التصفيات القادمة (Window 3) على أن يتم الإعلان عن الموعد الجديد بشكل رسمي لاحقاً من قبل الاتحاد الدولي لكرة السلة. وأكد الاتحاد استمرار المنتخب الوطني في استعداداته بأفضل شكل مع الجاهزية لتمثيل سوريا بأفضل صورة في الاستحقاقات القادمة. وكان منتخبنا الوطني قد فاز أمس الجمعة على نظيره العراقي بنتيجة 78/70، ضمن منافسات النافذة الثانية.', 'The Syrian Arab Basketball Federation announced the postponement of our national team’s match against its Iranian counterpart, which was scheduled for next March 2 in the Lebanese capital, Beirut, as part of the Asian qualifiers for the 2027 World Cup. The Federation explained In a statement published on its official handles on Saturday, February 28, the postponement of the match comes based on the decision of the International Basketball Federation for reasons related to the safety and security of the participating teams and ensuring the integrity of the competitions. He stated that the match will be held during the qualifying window Next (Window 3) the new date will be officially announced later by the International Basketball Federation. The Federation confirmed that the national team will continue its preparations in the best possible way, with its readiness to represent Syria in the best way in the competitions Coming. Our national team won yesterday, Friday, over its Iraqi counterpart, with a score of 78/70, in the second window competitions.', 'https://alikhbariah.com/wp-content/uploads/2026/02/The-match-between-our-national-team-and-Iran-in-the-Basketball-World-Cup-qualifiers-has-been-postponed.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-28T19:53:47+03:00'::timestamptz, false, false, false, 146),
  ('الاتحاد السوري لكرة القدم يصدر حزمة عقوبات بحق عدد من أندية الدوري الممتاز', 'The Syrian Football Association issues a package of sanctions against a number of Premier League clubs', 'أصدرت لجنة الانضباط والأخلاق في الاتحاد السوري لكرة القدم، الإثنين 23 شباط، حزمة من العقوبات والغرامات المالية بحق عدد من الأندية والإداريين عقب انتهاء الأسبوع التاسع من الدوري الممتاز. وشملت القرارات تغريم نادي حطين مبلغ 3 ملايين ليرة سورية لقيام جمهوره بشتم فريق تشرين ومدرب وحارس نادي الفتوة، إضافة إلى تغريمه مليوني ليرة لإشعال الشماريخ […]', 'On Monday, February 23, the Disciplinary and Ethics Committee of the Syrian Football Association issued a package of penalties and financial fines against a number of clubs and administrators following the end of the ninth week of the Premier League. The decisions included fining Hattin Club An amount of 3 million Syrian pounds for his fans insulting the Tishreen team and the coach and goalkeeper of Al-Fatwa Club, in addition to a fine of two million Syrian pounds for lighting the candles […]', 'أصدرت لجنة الانضباط والأخلاق في الاتحاد السوري لكرة القدم، الإثنين 23 شباط، حزمة من العقوبات والغرامات المالية بحق عدد من الأندية والإداريين عقب انتهاء الأسبوع التاسع من الدوري الممتاز. وشملت القرارات تغريم نادي حطين مبلغ 3 ملايين ليرة سورية لقيام جمهوره بشتم فريق تشرين ومدرب وحارس نادي الفتوة، إضافة إلى تغريمه مليوني ليرة لإشعال الشماريخ ورميها داخل أرض الملعب. وغرمت اللجنة نادي الفتوة مليوني ليرة لاستنكافه عن إكمال مباراته مع حطين لمدة 14 دقيقة، وقررت إيقاف مساعد مدرب الرجال مرهف دحبور ثلاث مباريات رسمية مع غرامة مليون ليرة، بعد ثبوت تحريضه فريقه على الاستنكاف. وغرمت اللجنة نادي جبلة 6 ملايين ليرة لشتم جمهوره الحكام، مع مضاعفة العقوبة لتكرار المخالفة، إضافة إلى غرامة قدرها مليون وخمسمائة ألف ليرة لرمي العبوات الفارغة على الحكام. وفي السياق، أقرت اللجنة توقيف رئيس نادي أمية الرياضي سامر عادل طرشة كردي عن مرافقة فريقه ثلاث مباريات متتالية', 'On Monday, February 23, the Disciplinary and Ethics Committee of the Syrian Football Association issued a package of penalties and financial fines against a number of clubs and administrators following the end of the ninth week of the Premier League. The decisions included fining Hattin Club An amount of 3 million Syrian pounds for his fans insulting the Tishreen team and the coach and goalkeeper of Al-Fatwa Club, in addition to a fine of 2 million Syrian pounds for lighting candles and throwing them on the field. The committee fined Al-Fatwa Club two million liras for refusing to complete its match with Hattin For 14 minutes, it was decided to suspend the men’s assistant coach, Murhaf Dahbour, for three official matches and fine him one million liras, after it was proven that he incited his team to protest. The committee fined the Jableh Club 6 million liras for insulting its fans and the referees, with the penalty doubled for repetition The violation is in addition to a fine of one million five hundred thousand liras for throwing empty containers at the referees. In this context, the committee approved the arrest of the president of the Umayyad Sports Club, Samer Adel Tarsha Kurdi, for accompanying his team to three consecutive matches.', 'https://alikhbariah.com/wp-content/uploads/2026/02/Syrian-Football-Federation.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-23T15:05:39+03:00'::timestamptz, false, false, false, 145),
  ('وزير الرياضة يخصص مكافأة 6 ملايين ليرة للجمهور الأكثر التزاماً بالروح الرياضية', 'The Minister of Sports allocates a reward of 6 million liras to the audience most committed to sportsmanship', 'أعلن وزير الرياضة والشباب محمد سامح حامض، الأحد 22 شباط، عن تخصيص مكافأة أسبوعية بقيمة 6 ملايين ليرة سورية تحت عنوان “أفضل جمهور”، تمنح للجماهير الأكثر التزاماً بالروح الرياضية والتشجيع الحضاري في مباريات الدوري المحلي لكرة القدم وكرة السلة. ويأتي هذا القرار في إطار سعي الوزارة لتعزيز ثقافة التشجيع الإيجابي، والحد من المظاهر السلبية في […]', 'On Sunday, February 22, the Minister of Sports and Youth, Muhammad Sameh Hamid, announced the allocation of a weekly reward worth 6 million Syrian pounds under the title “Best Fans,” given to the fans most committed to the spirit of sportsmanship and civilized encouragement in local league matches. For football and basketball. This decision comes within the framework of the Ministry’s endeavor to promote a culture of positive encouragement and reduce negative aspects in [...]', 'أعلن وزير الرياضة والشباب محمد سامح حامض، الأحد 22 شباط، عن تخصيص مكافأة أسبوعية بقيمة 6 ملايين ليرة سورية تحت عنوان “أفضل جمهور”، تمنح للجماهير الأكثر التزاماً بالروح الرياضية والتشجيع الحضاري في مباريات الدوري المحلي لكرة القدم وكرة السلة. ويأتي هذا القرار في إطار سعي الوزارة لتعزيز ثقافة التشجيع الإيجابي، والحد من المظاهر السلبية في المدرّجات، وتحفيز الجماهير على خلق أجواء رياضية داعمة للعبة واللاعبين، والمساهمة في إنجاح مسابقات الدوري. وأوضحت الوزارة، في بيان لها، أن عملية اختيار الجمهور الفائز ستتم بشكل أسبوعي من قبل الاتحادين السوري لكرة القدم وكرة السلة، وفق معايير محددة ترتكز على الالتزام بالسلوك الحضاري، والانضباط العام، وعدم ارتكاب المخالفات داخل الملاعب والصالات الرياضية. وأكدت الوزارة أن هذه الخطوة تهدف إلى ترسيخ قيم المسؤولية المجتمعية لدى الجماهير، والارتقاء بالمشهد الرياضي بما يعكس الصورة الحضارية للرياضة في سوريا. وجاء قرا', 'On Sunday, February 22, the Minister of Sports and Youth, Muhammad Sameh Hamid, announced the allocation of a weekly reward worth 6 million Syrian pounds under the title “Best Fans,” given to the fans most committed to the spirit of sportsmanship and civilized encouragement in local league matches. For football and basketball. This decision comes within the framework of the Ministry’s endeavor to promote a culture of positive encouragement, reduce negative aspects in the stands, motivate fans to create a sports atmosphere supportive of the game and the players, and contribute to the success of competitions. League. The Ministry explained, in a statement, that the process of selecting the winning audience will take place on a weekly basis by the Syrian Football and Basketball Federations, according to specific criteria based on commitment to civilized behavior, public discipline, and not committing crimes. Violations inside stadiums and gyms. The Ministry confirmed that this step aims to consolidate the values ​​of social responsibility among the masses and improve the sports scene in a way that reflects the civilized image of sports in Syria. Read came', 'https://alikhbariah.com/wp-content/uploads/2026/02/The-Minister-of-Sports-allocates-a-reward-of-6-million-lira-for-the-fans-most-committed-to-sportsmanship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-22T17:35:59+03:00'::timestamptz, false, false, false, 144),
  ('نادي محافظة دمشق يحقق إنجازاً رياضياً جديداً في بطولة الجمهورية للكاراتيه', 'Damascus Governorate Club achieves a new sporting achievement in the Republic Karate Championship', 'تمكن لاعبو نادي محافظة دمشق من حصد 18 ميدالية ملونة، خلال مشاركتهم في بطولة الجمهورية للأندية والبيوتات الرياضية للكاراتيه، التي أقيمت منافساتها في العاصمة دمشق بمشاركة واسعة ضمت 600 لاعب ولاعبة يمثلون 35 نادياً من مختلف المحافظات. وتشير النتائج التي أعلنتها مديرية الأنشطة الرياضية، إلى تتويج أبطال النادي بـ7 ميداليات ذهبية، وميدالية فضية واحدة، و10 […]', 'Damascus Governorate Club players were able to win 18 colored medals, during their participation in the Republic Championship for Karate Clubs and Houses, whose competitions were held in the capital, Damascus, with wide participation that included 600 male and female players representing 35 clubs from Various governorates. The results announced by the Sports Activities Directorate indicate that the club’s champions were crowned with 7 gold medals, one silver medal, and 10 […]', 'تمكن لاعبو نادي محافظة دمشق من حصد 18 ميدالية ملونة، خلال مشاركتهم في بطولة الجمهورية للأندية والبيوتات الرياضية للكاراتيه، التي أقيمت منافساتها في العاصمة دمشق بمشاركة واسعة ضمت 600 لاعب ولاعبة يمثلون 35 نادياً من مختلف المحافظات. وتشير النتائج التي أعلنتها مديرية الأنشطة الرياضية، إلى تتويج أبطال النادي بـ7 ميداليات ذهبية، وميدالية فضية واحدة، و10 ميداليات برونزية، ضمن الفئات العمرية (-14 / -16 / -18 / -21 / +18)، ليحقق بذلك المركز الثاني في الترتيب العام للبطولة. وفي أجواء احتفالية تعبيراً عن تقدير هذا الإنجاز، جرى تتويج اللاعبين بجوائز عينية ومادية برعاية محافظ دمشق ماهر مروان أدلبي، دعماً للمواهب الرياضية وتحفيزاً لمزيد من التألق والنجاح.', 'Damascus Governorate Club players were able to win 18 colored medals, during their participation in the Republic Championship for Karate Clubs and Houses, whose competitions were held in the capital, Damascus, with wide participation that included 600 male and female players representing 35 clubs from Various governorates. The results announced by the Sports Activities Directorate indicate that the club’s champions were crowned with 7 gold medals, one silver medal, and 10 bronze medals, within the age groups (-14 / -16 / -18 / -21 / +18), thus achieving Second place in the overall championship standings. In a festive atmosphere to express appreciation for this achievement, the players were crowned with in-kind and material prizes under the patronage of the Governor of Damascus, Maher Marwan Adlabi, to support sports talent and encourage more brilliance and success.', 'https://alikhbariah.com/wp-content/uploads/2026/02/Damascus-Governorate-Karate-Club.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-21T12:30:34+03:00'::timestamptz, false, false, false, 143),
  ('منتخب حلب بطلاً لبطولة سوريا الأولى لكرة القدم المصغرة', 'The Aleppo national team is champion of the first Syrian mini-football championship', 'توج منتخب حلب بطلاً لبطولة سوريا الأولى لكرة القدم المصغرة بعد فوزه على منتخب درعا بركلات الترجيح بنتيجة 3–2، في المباراة النهائية التي أقيمت الإثنين 16 شباط، عقب انتهاء الوقت الأصلي بالتعادل 3–3. وشهدت المباراة تنافساً قوياً وتبادلاً في تسجيل الأهداف بين المنتخبين خلال الوقت الأصلي، قبل أن تتجه إلى ركلات الترجيح لحسم النتيجة، حسب […]', 'The Aleppo national team was crowned champion of the first Syrian mini-football championship after defeating the Daraa national team on penalties, 3-2, in the final match that was held on Monday, February 16, after regular time ended in a 3-3 draw. The match witnessed competition There was a strong exchange of goals between the two teams during regular time, before heading to penalty kicks to settle the result, according to […]', 'توج منتخب حلب بطلاً لبطولة سوريا الأولى لكرة القدم المصغرة بعد فوزه على منتخب درعا بركلات الترجيح بنتيجة 3–2، في المباراة النهائية التي أقيمت الإثنين 16 شباط، عقب انتهاء الوقت الأصلي بالتعادل 3–3. وشهدت المباراة تنافساً قوياً وتبادلاً في تسجيل الأهداف بين المنتخبين خلال الوقت الأصلي، قبل أن تتجه إلى ركلات الترجيح لحسم النتيجة، حسب ما نشرته وزارة الرياضة والشباب عبر معرفاتها الرسمية. وبدأ منتخب حلب اللقاء بالتقدم بثلاثة أهداف مقابل هدف، قبل أن تتعدل الموازين إثر طرد حارس مرماه في الدقيقة 70 من مجريات المباراة. واستغل منتخب درعا النقص العددي وقلص الفارق، قبل أن يدرك التعادل في الثواني الأخيرة من الوقت بدل الضائع، ليلجأ الفريقان إلى ركلات الترجيح التي حسمها منتخب حلب لصالحه بنتيجة (3-2). وأضاف منتخب حلب إلى الإنجاز الجماعي جوائز فردية، حيث حصل مهاجمه محمد درويش على لقب هداف البطولة بعدما سجل 8 أهداف، فيما نال حارس المرمى محمد معياري جائزة أف', 'The Aleppo national team was crowned champion of the first Syrian mini-football championship after defeating the Daraa national team on penalties, 3-2, in the final match that was held on Monday, February 16, after regular time ended in a 3-3 draw. The match witnessed competition There was a strong exchange of goals between the two teams during regular time, before heading to penalty kicks to decide the result, according to what the Ministry of Sports and Youth published through its official accounts. The Aleppo national team started the match by leading by three goals to one. Before the balance changed after his goalkeeper was sent off in the 70th minute of the match. The Daraa team took advantage of the numerical deficiency and reduced the gap, before achieving an equalizer in the last seconds of stoppage time, so the two teams resorted to penalty kicks, which The Aleppo national team won it in its favor with a score of (3-2). The Aleppo national team added individual awards to the collective achievement, as its striker Mohamed Darwish won the tournament’s top scorer title after scoring 8 goals, while goalkeeper Mohamed Ma’ari won the F.', 'https://alikhbariah.com/wp-content/uploads/2026/02/Aleppo-team-wins-the-first-Syrian-Mini-Football-Championship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-16T22:30:30+03:00'::timestamptz, false, false, false, 142),
  ('انطلاق البطولة الرمضانية الأولى لكرة القدم داخل الصالات في دمشق', 'The first Ramadan futsal tournament begins in Damascus', 'انطلقت فعاليات البطولة الرمضانية الأولى لكرة القدم داخل الصالات، التي تُنظَّمها وزارة الرياضة والشباب بالتعاون مع سفارة مملكة البحرين في دمشق. ويشرف على البطولة الاتحاد السوري لكرة القدم، برعاية المؤسسة الملكية للأعمال الإنسانية في مملكة البحرين وشركة طموح البحرينية للإدارة الرياضية، إضافة إلى مجموعة ديونز، حسب ما نشرت وزارة الرياضة والشباب على معرفاتها الرسمية الخميس […]', 'The first Ramadan futsal tournament, organized by the Ministry of Sports and Youth in cooperation with the Embassy of the Kingdom of Bahrain in Damascus, was launched. The tournament is supervised by the Syrian Football Federation, sponsored by the Royal Business Corporation Humanitarian Affairs in the Kingdom of Bahrain and the Bahraini Tamouh Sports Management Company, in addition to the Dunes Group, according to what the Ministry of Sports and Youth published on its official websites on Thursday […]', 'انطلقت فعاليات البطولة الرمضانية الأولى لكرة القدم داخل الصالات، التي تُنظَّمها وزارة الرياضة والشباب بالتعاون مع سفارة مملكة البحرين في دمشق. ويشرف على البطولة الاتحاد السوري لكرة القدم، برعاية المؤسسة الملكية للأعمال الإنسانية في مملكة البحرين وشركة طموح البحرينية للإدارة الرياضية، إضافة إلى مجموعة ديونز، حسب ما نشرت وزارة الرياضة والشباب على معرفاتها الرسمية الخميس 12 شباط. وتضمن حفل الافتتاح فقرات فنية مستوحاة من التراث السوري، إلى جانب عروض رياضية أضفت أجواء حماسية عكست أهداف البطولة في تعزيز التواصل والتلاقي بين الشعوب. وأكد سفير مملكة البحرين في دمشق وحيد مبارك سيار، أن تنظيم البطولة يهدف إلى تنمية العلاقات الاجتماعية والإنسانية بين أعضاء السلك الدبلوماسي والشباب السوري. كما أشار إلى أن تنظيم البطولة يمهّد لإقامة فعاليات رياضية مشتركة مستقبلاً بمشاركة البعثات الدبلوماسية المعتمدة في سوريا. ولفت السفير البحريني إلى أن الرياضة لغة عا', 'The first Ramadan futsal tournament, organized by the Ministry of Sports and Youth in cooperation with the Embassy of the Kingdom of Bahrain in Damascus, was launched. The tournament is supervised by the Syrian Football Federation, sponsored by the Royal Business Corporation Humanitarian Affairs in the Kingdom of Bahrain and the Bahraini Tamouh Sports Management Company, in addition to the Dunes Group, according to what the Ministry of Sports and Youth published on its official websites on Thursday, February 12. The opening ceremony included artistic performances inspired by Syrian heritage. In addition to sports performances, they added an enthusiastic atmosphere that reflected the goals of the tournament in enhancing communication and rapprochement between peoples. The Ambassador of the Kingdom of Bahrain to Damascus, Wahid Mubarak Sayyar, confirmed that organizing the tournament aims to develop social and humanitarian relations between the members of the tournament. The diplomatic corps and Syrian youth. He also pointed out that organizing the tournament paves the way for holding joint sporting events in the future with the participation of diplomatic missions accredited in Syria. The Bahraini ambassador pointed out that sports is a common language', 'https://alikhbariah.com/wp-content/uploads/2026/02/The-first-Ramadan-indoor-football-tournament-kicks-off-in-Damascus.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-12T21:23:01+03:00'::timestamptz, false, false, false, 141),
  ('برعاية وزارة الثقافة.. انطلاق ملتقى رواق للتراث السوري في المكتبة الوطنية بدمشق', 'Under the sponsorship of the Ministry of Culture, the launch of the Rwaq Forum for Syrian Heritage at the National Library in Damascus', 'انطلقت أعمال ملتقى رواق للتراث السوري، اليوم الجمعة 27 آذار، تحت رعاية وزارة الثقافة في المكتبة الوطنية بدمشق، بهدف توثيق التراث السوري المادي واللامادي وإتاحته عبر منصات رقمية متخصصة. وأكد وزير الثقافة محمد ياسين الصالح، أن إطلاق الملتقى يعكس توجهاً استراتيجياً يعتمد على الشراكة مع المبادرات الثقافية وتمكينها لتكون رافداً أساسياً في صون الهوية الوطنية، […]', 'The work of the Rwaq Forum for Syrian Heritage was launched today, Friday, March 27, under the auspices of the Ministry of Culture at the National Library in Damascus, with the aim of documenting the tangible and intangible Syrian heritage and making it available through specialized digital platforms. The Minister of Culture, Muhammad Yassin, confirmed Al-Saleh said that launching the forum reflects a strategic direction that relies on partnership with cultural initiatives and enabling them to be an essential contributor to the preservation of national identity, […]', 'انطلقت أعمال ملتقى رواق للتراث السوري، اليوم الجمعة 27 آذار، تحت رعاية وزارة الثقافة في المكتبة الوطنية بدمشق، بهدف توثيق التراث السوري المادي واللامادي وإتاحته عبر منصات رقمية متخصصة. وأكد وزير الثقافة محمد ياسين الصالح، أن إطلاق الملتقى يعكس توجهاً استراتيجياً يعتمد على الشراكة مع المبادرات الثقافية وتمكينها لتكون رافداً أساسياً في صون الهوية الوطنية، مشدداً على أن التراث السوري أمانة مشتركة تتطلب تكامل جهود المؤسسات والباحثين والمجتمعات المحلية، بحسب ما نشرته وزارة الثقافة عبر معرفاتها الرسمية. وبين الوزير أن الملتقى يسهم في تعزيز الشراكات، وتطوير آليات التوثيق، وحماية الإرث السوري من التزييف والاستهلاك، مؤكداً دعم الوزارة لاستعادة السردية الوطنية وعرضها للعالم بصوت أهلها. ومن جانبها، استعرضت الدكتورة هلا قصقص، المشرفة على ملتقى رواق مع فريق العمل، أهمية التوثيق وآلياته وسبل البحث والتدقيق ومنصات التفاعل في مختلف الأروقة التي يتبناها ا', 'The work of the Rwaq Forum for Syrian Heritage was launched today, Friday, March 27, under the auspices of the Ministry of Culture at the National Library in Damascus, with the aim of documenting the tangible and intangible Syrian heritage and making it available through specialized digital platforms. The Minister of Culture, Muhammad Yassin, confirmed Al-Saleh said that launching the forum reflects a strategic direction that relies on partnership with cultural initiatives and enabling them to be an essential contributor to the preservation of national identity, stressing that Syrian heritage is a joint trust that requires the integrated efforts of institutions and researchers. And local communities, according to what the Ministry of Culture published through its official accounts. The Minister stated that the forum contributes to strengthening partnerships, developing documentation mechanisms, and protecting Syrian heritage from counterfeiting and consumption, stressing the Ministry’s support for restoring the narrative. Patriotism and presenting it to the world with the voice of its people. For her part, Dr. Hala Qasqas, supervisor of the Riwaq Forum, reviewed with the work team the importance of documentation, its mechanisms, methods of research and auditing, and interaction platforms in the various corridors adopted by the organization.', 'https://alikhbariah.com/wp-content/uploads/2026/03/Ministry-of-Culture.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-27T12:00:10+03:00'::timestamptz, false, true, false, 140),
  ('وزير الثقافة يثني على جهود وزارة الداخلية خلال معرض دمشق الدولي للكتاب', 'The Minister of Culture praises the efforts of the Ministry of Interior during the Damascus International Book Fair', 'أثنى وزير الثقافة محمد ياسين صالح، الثلاثاء 17 شباط، على جهود وزارة الداخلية وقيادة الأمن الداخلي ورجال الأمن عقب انتهاء معرض دمشق الدولي للكتاب. وأعرب صالح في تدوينة عبر منصة “إكس“، عن تقديره لجهودهم خلال أيام المعرض، مشيراً إلى سهرهم لضمان سلامة الزوار والناشرين. وأوضح أنهم قدموا صورة تليق بالمعرض الذي أعاد الاعتبار للثقافة السورية […]', 'On Tuesday, February 17, Minister of Culture Muhammad Yassin Saleh praised the efforts of the Ministry of Interior, the Internal Security Command, and security personnel following the end of the Damascus International Book Fair. In a blog post on the “X” platform, Saleh expressed his appreciation for their efforts during the exhibition days, Noting that they are staying up late to ensure the safety of visitors and publishers. He explained that they presented an image worthy of the exhibition, which restored respect for Syrian culture […]', 'أثنى وزير الثقافة محمد ياسين صالح، الثلاثاء 17 شباط، على جهود وزارة الداخلية وقيادة الأمن الداخلي ورجال الأمن عقب انتهاء معرض دمشق الدولي للكتاب. وأعرب صالح في تدوينة عبر منصة “إكس “، عن تقديره لجهودهم خلال أيام المعرض، مشيراً إلى سهرهم لضمان سلامة الزوار والناشرين. وأوضح أنهم قدموا صورة تليق بالمعرض الذي أعاد الاعتبار للثقافة السورية بعد أن صودرت أعواماً طوالاً. واختتمت فعاليات معرض دمشق الدولي للكتاب، أمس الإثنين، وسط حضور عربي ودولي واسع وتكريم عدد من دور النشر والكتاب بعد 11 يوماً من انطلاقته. وأكد وزير الثقافة، في كلمة خلال حفل الاختتام، أهمية المعرض في تعزيز الدبلوماسية الثقافية والسياسية وتقديم صورة مشرقة عن سوريا الجديدة وأن المعرض تجاوز توقعات الناشرين وعكس تفاؤلاً كبيراً بمستقبل البلاد الحضاري. وأشار إلى أن المشروع الثقافي الجديد يعيد سوريا إلى مكانتها الحضارية الأصيلة مع التركيز على فئتي الأطفال والشباب، موضحاً أن الفئات العمري', 'On Tuesday, February 17, Minister of Culture Muhammad Yassin Saleh praised the efforts of the Ministry of Interior, the Internal Security Command, and security personnel following the end of the Damascus International Book Fair. In a blog post on the “X” platform, Saleh expressed his appreciation for their efforts during the exhibition days, Noting that they are staying up late to ensure the safety of visitors and publishers. He explained that they presented an image worthy of the exhibition, which restored respect for Syrian culture after it had been confiscated for many years. The activities of the Damascus International Book Fair concluded yesterday, Monday, amid an Arab and international presence It was widely distributed and a number of publishing houses and writers were honored 11 days after its launch. In a speech during the closing ceremony, the Minister of Culture stressed the importance of the exhibition in strengthening cultural and political diplomacy and presenting a bright image of the new Syria, and that the exhibition went beyond Publishers'' expectations reflected great optimism about the country''s cultural future. He pointed out that the new cultural project restores Syria to its original cultural status, with a focus on the categories of children and youth, explaining that the age groups', 'https://alikhbariah.com/wp-content/uploads/2026/02/Minister-of-Culture-Mohammed-Al-Saleh.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-17T23:42:13+03:00'::timestamptz, false, true, false, 139),
  ('بتوجيه من الرئيس الشرع.. وزارة الثقافة تعفي الناشرين من رسوم معرض دمشق للكتاب', 'Under the direction of President Al-Sharaa, the Ministry of Culture exempts publishers from Damascus Book Fair fees', 'أعلنت وزارة الثقافة إعفاء جميع الناشرين من رسوم الاشتراك واستئجار الأجنحة في معرض دمشق الدولي للكتاب، لتكون هذه الخطوة هدية بمناسبة النسخة التاريخية للمعرض. وقال وزير الثقافة محمد ياسين الصالح في تصريح لوكالة سانا، السبت 14 شباط، إن الإعفاء جاء بتوجيهات من السيد الرئيس أحمد الشرع. وأضاف أنّ “البعد التجاري للمعرض يظل ثانوياً، فيما يتقدّم […]', 'The Ministry of Culture announced that all publishers will be exempted from subscription fees and renting pavilions at the Damascus International Book Fair, so that this step will be a gift on the occasion of the historic edition of the fair. Minister of Culture Muhammad Yassin Al-Saleh said in a statement to SANA: Saturday, February 14, the exemption came under the directives of President Ahmed Al-Sharaa. He added that “the commercial dimension of the exhibition remains secondary, while […]', 'أعلنت وزارة الثقافة إعفاء جميع الناشرين من رسوم الاشتراك واستئجار الأجنحة في معرض دمشق الدولي للكتاب، لتكون هذه الخطوة هدية بمناسبة النسخة التاريخية للمعرض. وقال وزير الثقافة محمد ياسين الصالح في تصريح لوكالة سانا ، السبت 14 شباط، إن الإعفاء جاء بتوجيهات من السيد الرئيس أحمد الشرع. وأضاف أنّ “البعد التجاري للمعرض يظل ثانوياً، فيما يتقدّم البعد الفكري في هذا المحفل الثقافي بامتياز، مؤكداً أن المعرض يعكس عودة سوريا بقوة واستعادة كلمتها وهويتها ووجهها المشرق”. وأشار الصالح إلى أن المعرض يمثل شمس الحرف والحضارة، ويبرز أهمية الثقافة والفكر في تعزيز حضور الجمهورية العربية السورية داخلياً وخارجياً. وأكد وزير الثقافة في الرابع من الشهر الجاري، أن معرض دمشق الدولي للكتاب يشكل هذا العام حدثاً استثنائياً يعكس مرحلة ما بعد التحرير، ويعبر عن هوية ثقافية سورية جديدة تقوم على حرية الفكر واتساع فضاء التعبير، بعد عقود كان فيها سقف الحرية منخفضاً وهيمنة ال', 'The Ministry of Culture announced that all publishers will be exempted from subscription fees and renting pavilions at the Damascus International Book Fair, so that this step will be a gift on the occasion of the historic edition of the fair. Minister of Culture Muhammad Yassin Al-Saleh said in a statement to SANA: Saturday, February 14, the exemption came under the directives of President Ahmed Al-Sharaa. He added, “The commercial dimension of the exhibition remains secondary, while the intellectual dimension in this cultural forum is par excellence, stressing that the exhibition reflects Syria’s strong return and restoration.” Its word, its identity, and its bright face.” Al-Saleh pointed out that the exhibition represents the sun of crafts and civilization, and highlights the importance of culture and thought in enhancing the presence of the Syrian Arab Republic internally and externally. The Minister of Culture confirmed on the fourth of this month that The Damascus International Book Fair this year constitutes an exceptional event that reflects the post-liberation era, and expresses a new Syrian cultural identity based on freedom of thought and a wide space for expression, after decades in which the ceiling for freedom was low and the dominance of...', 'https://alikhbariah.com/wp-content/uploads/2026/02/Book-Fair-1.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-14T15:48:33+03:00'::timestamptz, false, false, false, 138),
  ('معرض دمشق الدولي للكتاب يستقطب 250 ألف زائر في يومه الأول', 'The Damascus International Book Fair attracts 250,000 visitors on its first day', 'استقبل معرض دمشق الدولي للكتاب في يومه الأول 250 ألف زائر، وفقاً لوزير الثقافة محمد ياسين صالح الذي اعتبر الإقبال على المعرض كمؤشر إيجابي في مسار التعافي واسترداد الهوية الوطنية. وأوضح الوزير في تصريح للإخبارية، السبت 7 شباط، أن الهدف الأساسي هو توثيق سوريا الحضاري ووضعه في الإطار الذي يليق بها وتستحقه، مشيراً إلى رفع […]', 'On its first day, the Damascus International Book Fair received 250,000 visitors, according to the Minister of Culture, Muhammad Yassin Saleh, who considered the turnout for the exhibition as a positive indicator in the path of recovery and recovery of national identity. The minister explained in a statement to Al-Ikhbariya, Saturday 7th February, said that the primary goal is to document Syria’s civilization and place it in the framework that befits and deserves it, pointing out […]', 'استقبل معرض دمشق الدولي للكتاب في يومه الأول 250 ألف زائر، وفقاً لوزير الثقافة محمد ياسين صالح الذي اعتبر الإقبال على المعرض كمؤشر إيجابي في مسار التعافي واسترداد الهوية الوطنية. وأوضح الوزير في تصريح ل لإخبارية ، السبت 7 شباط، أن الهدف الأساسي هو توثيق سوريا الحضاري ووضعه في الإطار الذي يليق بها وتستحقه، مشيراً إلى رفع سقف التحدي والجمال والإبداع بتنظيم معرض دولي بهذا الحجم في دمشق. وأضاف صالح أن الوزارة تجري تقييماً يومياً لفعاليات معرض دمشق الدولي للكتاب لتجنب أي أخطاء محتملة خلال سير المعرض، لافتاً إلى أنه في كل مكان بالمعرض هناك ما يلفت الانتباه ويجذب الزوار. وأشار الوزير إلى أن النظام البائد استهلك دور الكتب عبر فرض رقابة على نوعيتها وطريقة المشاركة، مؤكداً أن المعرض الحالي يعكس حرية الإبداع والتنوع الثقافي. وافتتح وزير الثقافة، يوم الخميس الماضي، حفل معرض دمشق الدولي للكتاب بدورته الاستثنائية في قصر المؤتمرات بدمشق، مؤكداً أن السور', 'On its first day, the Damascus International Book Fair received 250,000 visitors, according to the Minister of Culture, Muhammad Yassin Saleh, who considered the turnout for the exhibition as a positive indicator in the path of recovery and recovery of national identity. The minister explained in a statement to Ikhbaria, on Saturday February 7, that the primary goal is to document Syria’s civilization and place it in the framework that befits and deserves it, pointing to raising the ceiling of challenge, beauty and creativity by organizing an international exhibition of this size in Damascus. Saleh added that the Ministry conducts a daily evaluation of activities Damascus International Book Fair to avoid any possible errors during the course of the exhibition, pointing out that everywhere in the exhibition there is something that attracts attention and attracts visitors. The minister pointed out that the former regime had exhausted the role of books by imposing censorship on their quality and method Participation, stressing that the current exhibition reflects freedom of creativity and cultural diversity. Last Thursday, the Minister of Culture opened the extraordinary session of the Damascus International Book Fair at the Conference Palace in Damascus, stressing that the wall', 'https://alikhbariah.com/wp-content/uploads/2026/02/Damascus-International-Book-Fair.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-07T15:21:26+03:00'::timestamptz, false, false, false, 137),
  ('الرئيس الشرع يصل إلى قصر المؤتمرات للمشاركة بافتتاح معرض دمشق الدولي للكتاب', 'President Al-Sharaa arrives at the Conference Palace to participate in the opening of the Damascus International Book Fair', 'وصل السيد الرئيس أحمد الشرع برفقة عقيلته، إلى قصر المؤتمرات في دمشق للمشاركة في حفل افتتاح معرض دمشق الدولي للكتاب. وبدأت الوفود المشاركة في معرض دمشق الدولي للكتاب بالوصول إلى قصر المؤتمرات في دمشق، الخميس 5 شباط، للمشاركة في حفل الافتتاح الرسمي للمعرض. وأفادت مراسلة “الإخبارية” بأن الفعالية انطلقت بحضور شخصيات رسمية محلية وعربية وأجنبية […]', 'Mr. President Ahmed Al-Sharaa, accompanied by his wife, arrived at the Conference Palace in Damascus to participate in the opening ceremony of the Damascus International Book Fair. Delegations participating in the Damascus International Book Fair began arriving at the Conference Palace in Damascus on Thursday, February 5. To participate in the official opening ceremony of the exhibition. Al-Ekhbariya correspondent reported that the event was launched in the presence of local, Arab and foreign official figures […]', 'وصل السيد الرئيس أحمد الشرع برفقة عقيلته، إلى قصر المؤتمرات في دمشق للمشاركة في حفل افتتاح معرض دمشق الدولي للكتاب. وبدأت الوفود المشاركة في معرض دمشق الدولي للكتاب بالوصول إلى قصر المؤتمرات في دمشق، الخميس 5 شباط، للمشاركة في حفل الافتتاح الرسمي للمعرض. وأفادت مراسلة “ الإخبارية ” بأن الفعالية انطلقت بحضور شخصيات رسمية محلية وعربية وأجنبية للمشاركة في هذا الحدث الثقافي. وأوضحت المراسلة أن المعرض يمثّل تظاهرة ثقافية وطنية كبرى، مؤكدة أن معرض دمشق الدولي للكتاب لا يقتصر على عرض الكتب فحسب، بل يؤسس لمرحلة جديدة يعاد فيها وصل المجتمع بالمعرفة. من جهتها، قالت وزارة الداخلية عبر معرّفاتها الرسمية إنه، وبتوجيهات من وزير الداخلية أنس خطاب، تفقد قائد الأمن الداخلي في محافظة ريف دمشق العميد أحمد الدالاتي مدينة المعارض في المحافظة قبيل افتتاح معرض دمشق الدولي للكتاب لعام 2026. وأضافت الوزارة أن العميد الدالاتي اطلع على سير عملية التأمين والحماية، و', 'Mr. President Ahmed Al-Sharaa, accompanied by his wife, arrived at the Conference Palace in Damascus to participate in the opening ceremony of the Damascus International Book Fair. Delegations participating in the Damascus International Book Fair began arriving at the Conference Palace in Damascus on Thursday, February 5. To participate in the official opening ceremony of the exhibition. The Al-Ekhbariya correspondent reported that the event was launched in the presence of local, Arab and foreign official figures to participate in this cultural event. The correspondent explained that the exhibition represents a major national cultural demonstration. Emphasizing that the Damascus International Book Fair is not limited to displaying books, but rather establishes a new phase in which society is reconnected with knowledge. For its part, the Ministry of Interior said through its official identifiers that, under the directives of Interior Minister Anas Khattab, the commander of the Internal Security in the Damascus Countryside Governorate, Brigadier General Ahmed Al-Dalati, exhibition city in the governorate, prior to the opening of the Damascus International Book Fair for the year 2026. The Ministry added that Brigadier General Al-Dalati was briefed on the progress of the insurance and protection process, and', 'https://alikhbariah.com/wp-content/uploads/2026/02/President-Sharia-3.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-05T16:53:46+03:00'::timestamptz, false, false, false, 136),
  ('وزير الثقافة: معرض دمشق الدولي للكتاب يرسخ هوية سوريا المتجددة', 'Minister of Culture: The Damascus International Book Fair consolidates Syria’s renewed identity', 'أكد وزير الثقافة محمد ياسين صالح، أن معرض دمشق الدولي للكتاب يشكل في دورته الحالية حدثاً استثنائياً يجسد مرحلة ما بعد التحرير ويعبر عن هوية ثقافية سورية جديدة ترتكز على حرية الفكر واتساع فضاء التعبير بعد عقود من هيمنة الفكر الواحد. وأوضح الصالح في لقاء خاص مع قناة “الإخبارية“، الأربعاء 4 شباط، أن المعرض يأتي […]', 'The Minister of Culture, Muhammad Yassin Saleh, confirmed that the Damascus International Book Fair, in its current session, constitutes an exceptional event that embodies the post-liberation era and expresses a new Syrian cultural identity based on freedom of thought and the expansion of the space of expression after decades of dominance. One thought. Al-Saleh explained in an exclusive interview with Al-Ekhbariya channel, on Wednesday, February 4, that the exhibition comes […]', 'أكد وزير الثقافة محمد ياسين صالح، أن معرض دمشق الدولي للكتاب يشكل في دورته الحالية حدثاً استثنائياً يجسد مرحلة ما بعد التحرير ويعبر عن هوية ثقافية سورية جديدة ترتكز على حرية الفكر واتساع فضاء التعبير بعد عقود من هيمنة الفكر الواحد. وأوضح الصالح في لقاء خاص مع قناة “ الإخبارية “، الأربعاء 4 شباط، أن المعرض يأتي ليجسد صورة سوريا المتجددة التي تستعيد دورها الحضاري وتعيد الاعتبار للكتاب بوصفه ركناً أساسياً في بناء الوعي. وأشار إلى أن هذه الدورة هي الأكبر من حيث حجم المشاركة بتجاوز عدد دور النشر المشاركة 500 دار من سوريا ودول عربية وأجنبية، مع حلول المملكة العربية السعودية ودولة قطر ضيفتي شرف عبر أجنحة وفعاليات واسعة. وبيّن صالح أن الوزارة قدمت تسهيلات كبيرة شملت الإعفاء من رسوم الإيجار وتحمل تكاليف الشحن لتشجيع العودة إلى سوريا. ولفت إلى أن المعرض يتضمن باقة واسعة من المسابقات والجوائز في الرواية والشعر وجائزة أجمل جناح، بالإضافة إلى الكشف عن', 'The Minister of Culture, Muhammad Yassin Saleh, confirmed that the Damascus International Book Fair, in its current session, constitutes an exceptional event that embodies the post-liberation era and expresses a new Syrian cultural identity based on freedom of thought and the expansion of the space of expression after decades of dominance. One thought. Al-Saleh explained in an exclusive interview with Al-Ekhbariya channel, on Wednesday, February 4, that the exhibition comes to embody the renewed image of Syria, which is regaining its civilizational role and restoring the book’s respectability as an essential pillar in building awareness. He pointed out that this The tournament is the largest in terms of the size of participation, with the number of participating publishing houses exceeding 500 from Syria and Arab and foreign countries, with the Kingdom of Saudi Arabia and the State of Qatar being guests of honor through wide pavilions and events. Saleh stated that the ministry provided facilities It included exemption from rental fees and bearing shipping costs to encourage return to Syria. He pointed out that the exhibition includes a wide range of competitions and prizes in novels and poetry, as well as an award for the most beautiful pavilion, in addition to revealing...', 'https://alikhbariah.com/wp-content/uploads/2025/11/Minister-of-Culture-The-battle-to-deter-aggression-restored-the-dignity-of-a-nation-and-the-indomitable-spirit-of-a-people.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-04T22:04:41+03:00'::timestamptz, false, false, false, 135),
  ('خلال زيارتهم حاضنة دمر.. دبلوماسيون يحثون على صون الحرف التقليدية', 'During their visit to the Dummar Incubator, diplomats urge the preservation of traditional crafts', 'أكد سفراء أبخازيا والأردن والقائم بأعمال سفارة ليبيا في دمشق، الثلاثاء 3 شباط، خلال زيارتهم إلى حاضنة دمر للفنون الحرفية بدمشق، على ضرورة الحفاظ على الحرف التراثية والإبداع الحرفي السوري. وأعرب السفراء عن أهمية نقل فكرة هذا التجمع الذي يضم أهم الحرف التراثية إلى بلدانهم، مع الإشارة إلى دور الحرف اليدوية في إبراز الثقافة السورية […]', 'On Tuesday, February 3, during their visit to the Dummar Incubator for Craft Arts in Damascus, the Ambassadors of Abkhazia and Jordan and the Chargé d''Affairs of the Libyan Embassy in Damascus stressed the necessity of preserving Syrian heritage crafts and artisanal creativity. The ambassadors expressed the importance of conveying an idea This gathering, which includes the most important heritage crafts from their countries, with reference to the role of handicrafts in highlighting Syrian culture […]', 'أكد سفراء أبخازيا والأردن والقائم بأعمال سفارة ليبيا في دمشق، الثلاثاء 3 شباط، خلال زيارتهم إلى حاضنة دمر للفنون الحرفية بدمشق، على ضرورة الحفاظ على الحرف التراثية والإبداع الحرفي السوري. وأعرب السفراء عن أهمية نقل فكرة هذا التجمع الذي يضم أهم الحرف التراثية إلى بلدانهم، مع الإشارة إلى دور الحرف اليدوية في إبراز الثقافة السورية بحسب ما نشرت وكالة سانا . واطلع السفراء خلال زيارتهم على عدد من الحرف التقليدية الموجودة في الحاضنة مثل: الصدف، والموزاييك، والنقش على النحاس، والحفر على والخشب، وتركيب العطور وتصميم الأزياء والأغباني، إضافة إلى الحصر، واللباس العربي والبروكار والجلديات والخيط العربي والعجمي، والحلاقة والتزيين. بدوره أكد سفير أبخازيا محمد علي أن الحفاظ على الصناعات الحرفية التقليدية في سوريا أمر بالغ الأهمية، كونها تمثل جزءاً من الهوية الثقافية والحضارية العريقة للشعب السوري. وأوضح أن هذه الصناعات تساهم في نقل الثقافة السورية إلى د', 'On Tuesday, February 3, during their visit to the Dummar Incubator for Craft Arts in Damascus, the Ambassadors of Abkhazia and Jordan and the Chargé d''Affairs of the Libyan Embassy in Damascus stressed the necessity of preserving Syrian heritage crafts and artisanal creativity. The ambassadors expressed the importance of conveying an idea This gathering includes the most important traditional crafts from their countries, with reference to the role of handicrafts in highlighting Syrian culture, according to what was published by SANA. During their visit, the ambassadors were briefed on a number of traditional crafts present in the incubator, such as: Seashells, mosaics, engraving on copper, engraving on wood, installing perfumes, fashion design and garments, in addition to mats, Arabic dress, brocade, leather, Arab and Persian thread, shaving and decoration. In turn, the Ambassador of Abkhazia, Mohammed, confirmed Preserving traditional craft industries in Syria is extremely important, as they represent part of the ancient cultural and civilizational identity of the Syrian people. He explained that these industries contribute to transmitting Syrian culture to Dr', 'https://alikhbariah.com/wp-content/uploads/2026/02/Syrian-traditional-crafts.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-02-03T22:00:54+03:00'::timestamptz, false, false, false, 134),
  ('هيئة التميز والإبداع تطلق التصفيات النهائية للأولمبياد العلمي السوري 2026', 'The Excellence and Creativity Authority launches the final qualifiers for the Syrian Scientific Olympiad 2026', 'أعلنت هيئة التميز والإبداع، برعاية الأمانة العامة لرئاسة الجمهورية العربية السورية، عن انطلاق التصفيات النهائية للأولمبياد العلمي السوري لموسم 2026، بمشاركة نخبة من الطلاب المتفوقين من مختلف المحافظات السورية. وستجري التصفيات النهائية في فندق السبع بوابات بدمشق، بين 16-19 كانون الثاني الجاري في اختصاصات، الرياضيات والفيزياء والكيمياء وعلم الأحياء والمعلوماتية، قبل أن يجري اختيار الفرق […]', 'The Authority for Excellence and Creativity, under the auspices of the General Secretariat of the Presidency of the Syrian Arab Republic, announced the launch of the final qualifiers for the Syrian Scientific Olympiad for the 2026 season, with the participation of an elite group of outstanding students from various Syrian governorates. And you will run The final qualifiers will be held at the Seven Gates Hotel in Damascus, between January 16-19, in the specializations of mathematics, physics, chemistry, biology and informatics, before the teams are selected […]', 'أعلنت هيئة التميز والإبداع، برعاية الأمانة العامة لرئاسة الجمهورية العربية السورية، عن انطلاق التصفيات النهائية للأولمبياد العلمي السوري لموسم 2026، بمشاركة نخبة من الطلاب المتفوقين من مختلف المحافظات السورية. وستجري التصفيات النهائية في فندق السبع بوابات بدمشق، بين 16-19 كانون الثاني الجاري في اختصاصات، الرياضيات والفيزياء والكيمياء وعلم الأحياء والمعلوماتية، قبل أن يجري اختيار الفرق الوطنية التي ستمثل سورية في المحافل العلمية الإقليمية والدولية، بحسب ما نشرت الهيئة عبر صفحتها الرسمية على فيسبوك . وأضافت الهيئة أنه من المقرر أن تختتم الفعالية بحفل إعلان النتائج وتتويج الفرق الوطنية يوم 19 كانون الثاني 2026 في دار الأوبرا بدمشق، حيث سيتم الإعلان عن أسماء الطلاب الفائزين. ويعرف الأولمبياد العلمي السوري بأنه مسابقات في اختصاصات الرياضيات والفيزياء والكيمياء وعلم الأحياء والمعلوماتية والروبوتيك والمناظرات والنمذجة الرياضية. و تتنافس فيها الد', 'The Authority for Excellence and Creativity, under the auspices of the General Secretariat of the Presidency of the Syrian Arab Republic, announced the launch of the final qualifiers for the Syrian Scientific Olympiad for the 2026 season, with the participation of an elite group of outstanding students from various Syrian governorates. And you will run The final qualifiers will be held at the Seven Gates Hotel in Damascus, between January 16-19, in the specializations of mathematics, physics, chemistry, biology and informatics, before the national teams that will represent Syria in scientific forums are selected. Regional and international, according to what the authority published on its official Facebook page. The authority added that the event is scheduled to conclude with a ceremony announcing the results and crowning the national teams on January 19, 2026 at the Opera House in Damascus, where it will be held. Announcing the names of the winning students. The Syrian Scientific Olympiad is known as competitions in the disciplines of mathematics, physics, chemistry, biology, informatics, robotics, debates, and mathematical modeling. And D. competes in it', 'https://alikhbariah.com/wp-content/uploads/2026/01/Excellence-and-Creativity-Authority.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-01-14T01:11:43+03:00'::timestamptz, false, false, false, 133),
  ('وزارة الثقافة تنعى الباحث عماد الأرمشي أحد أبرز مؤرخين تاريخ دمشق العمراني', 'The Ministry of Culture mourns the researcher Imad Al-Armashi, one of the most prominent historians of Damascus’ urban history', 'نعت وزارة الثقافة، الثلاثاء 30 كانون الأول، المؤرخ والباحث عماد الأرمشي، أحد أبرز المتخصصين في توثيق التاريخ العمراني لمدينة دمشق، والذي شكل برحيله خسارة كبيرة للمشهد الثقافي والبحثي المعني بذاكرة العاصمة. وعن حياته، ولد الأرمشي في مدينة دمشق عام 1951، ونشأ في حي سوق ساروجة، ما عزز ارتباطه المبكر بالمدينة وأحيائها ومعالمها التاريخية. ونال شهادة […]', 'On Tuesday, December 30, the Ministry of Culture mourned the historian and researcher Imad Al-Armashi, one of the most prominent specialists in documenting the urban history of the city of Damascus, whose passing represented a great loss to the cultural and research scene concerned with the memory of the capital. And about his life, Al-Armashi was born in Damascus in 1951, and grew up in the Souq Sarouja neighborhood, which strengthened his early connection with the city, its neighborhoods, and its historical landmarks. He received a certificate [...]', 'نعت وزارة الثقافة، الثلاثاء 30 كانون الأول، المؤرخ والباحث عماد الأرمشي، أحد أبرز المتخصصين في توثيق التاريخ العمراني لمدينة دمشق، والذي شكل برحيله خسارة كبيرة للمشهد الثقافي والبحثي المعني بذاكرة العاصمة. وعن حياته، ولد الأرمشي في مدينة دمشق عام 1951، ونشأ في حي سوق ساروجة، ما عزز ارتباطه المبكر بالمدينة وأحيائها ومعالمها التاريخية. ونال شهادة الإجازة في التاريخ من جامعة دمشق عام 1977، ليبدأ بعدها مسيرته البحثية التي اتسمت بالدقة والمنهجية في التوثيق. وكرس المؤرخ منذ عام 2003 جهوده لجمع وأرشفة كم واسع من الوثائق والصور والمراجع المتعلقة بأحياء دمشق وأسواقها وجوامعها ومدارسها وتكاياها وخاناتها، إلى جانب توثيق تاريخ أسرها العريقة. ورصد التحولات العمرانية التي شهدتها المدينة على مدى عقود، وسعى إلى حفظ معالمها من الاندثار عبر أرشيف بصري ومعرفي غني. وخلّف عماد الأرمشي إرثاً توثيقياً ثميناً سيبقى مرجعاً للأجيال القادمة، وشاهداً على إسهامه العم', 'On Tuesday, December 30, the Ministry of Culture mourned the historian and researcher Imad Al-Armashi, one of the most prominent specialists in documenting the urban history of the city of Damascus, whose passing represented a great loss to the cultural and research scene concerned with the memory of the capital. And about his life, Al-Armashi was born in Damascus in 1951, and grew up in the Souq Sarouja neighborhood, which strengthened his early connection with the city, its neighborhoods, and its historical landmarks. He obtained a bachelor''s degree in history from the University of Damascus in 1977, after which he began his research career, which was characterized by precision. And methodology in documentation. Since 2003, the historian has devoted his efforts to collecting and archiving a wide range of documents, photos, and references related to Damascus’ neighborhoods, markets, mosques, schools, hospices, and inns, in addition to documenting the history of its ancient families. And monitor transformations The urban development that the city witnessed over the decades, and sought to preserve its landmarks from extinction through a rich visual and cognitive archive. Imad Al-Armashi left behind a valuable documentary legacy that will remain a reference for future generations, and a testimony to his general contribution.', 'https://alikhbariah.com/wp-content/uploads/2025/12/Emad-Al-Armashi-1.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2025-12-30T16:58:08+03:00'::timestamptz, false, false, false, 132),
  ('وزارة الثقافة تحتفي باليوم العالمي للغة العربية في كلية الآداب بدمشق', 'The Ministry of Culture celebrates International Arabic Language Day at the College of Arts in Damascus', 'نظمت وزارة الثقافة بالتعاون مع كلية الآداب والعلوم الإنسانية في جامعة دمشق، يوم أمس الخميس، فعالية ثقافية احتفاءً باليوم العالمي للغة العربية، وذلك في مدرج الكلية. وشدد مدير مديرية المراكز الثقافية أنس الدغيم في كلمة له، على حرص الوزارة على الاهتمام بلغة القرآن الكريم، مؤكداً أنها “مداد وفكر للجميع لا ينضب”. وتضمنت الفعالية ندوة علمية […]', 'Yesterday, Thursday, the Ministry of Culture, in cooperation with the Faculty of Arts and Human Sciences at Damascus University, organized a cultural event to celebrate International Arabic Language Day, in the college’s auditorium. Director of the Cultural Centers Directorate, Anas Al-Daghim, stressed in a speech He praised the Ministry’s keenness to pay attention to the language of the Holy Qur’an, stressing that it is “an inexhaustible resource and thought for all.” The event included a scientific symposium [...]', 'نظمت وزارة الثقافة بالتعاون مع كلية الآداب والعلوم الإنسانية في جامعة دمشق، يوم أمس الخميس، فعالية ثقافية احتفاءً باليوم العالمي للغة العربية، وذلك في مدرج الكلية. وشدد مدير مديرية المراكز الثقافية أنس الدغيم في كلمة له، على حرص الوزارة على الاهتمام بلغة القرآن الكريم، مؤكداً أنها “مداد وفكر للجميع لا ينضب”. وتضمنت الفعالية ندوة علمية قدم خلالها عضو الهيئة التدريسية في جامعة دمشق أيمن الشوّا مداخلة بعنوان “الغيرة على اللغة العربية”، سلط فيها الضوء على جهود علماء اللغة الأوائل كالفراهيدي وسيبويه والنسائي والفرّاء، وأثرهم الباقي حتى اليوم، مشيراً إلى أن المستشرقين والمؤرخين المنصفين حثوا العرب على الغيرة على لغتهم. ومن جانبها، قدمت رئيسة قسم اللغة العربية وآدابها في الجامعة الدكتورة منى طعمة، خلال مداخلتها بعنوان “اللغة العربية بين الواقع والمأمول”، تحليلاً واقعياً لواقع القسم والتحديات التي يواجهها كتضخم أعداد الطلاب، مؤكدة ضرورة تعاون كاف', 'Yesterday, Thursday, the Ministry of Culture, in cooperation with the Faculty of Arts and Human Sciences at Damascus University, organized a cultural event to celebrate International Arabic Language Day, in the college’s auditorium. Director of the Cultural Centers Directorate, Anas Al-Daghim, stressed in a speech He praised the Ministry’s keenness to pay attention to the language of the Holy Qur’an, stressing that it is “an inexhaustible resource and thought for all.” The event included a scientific symposium during which Damascus University faculty member Ayman Al-Shawa presented an intervention entitled “Jealousy for the Arabic Language.” In it, he shed light on the efforts of early linguists such as Al-Farahidi, Sibawayh, Al-Nasa’i, and Al-Farra’, and their impact that remains until today, pointing out that orientalists and fair-minded historians urged the Arabs to be jealous of their language. For her part, the Head of the Language Department presented Arabic and its literature at the university, Dr. Mona Tohme, during her intervention entitled “The Arabic Language between Reality and Aspirations,” provided a realistic analysis of the reality of the department and the challenges it faces, such as the swelling numbers of students, stressing the necessity of sufficient cooperation.', 'https://alikhbariah.com/wp-content/uploads/2025/12/Ministry-of-Culture.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2025-12-19T13:40:41+03:00'::timestamptz, false, false, false, 131),
  ('انطلاق المؤتمر العلمي الأول لنقابة أطباء سوريا', 'The launch of the first scientific conference of the Syrian Doctors Syndicate', 'انطلقت اليوم، الخميس 2 نيسان، أعمال المؤتمر العلمي الأول لنقابة أطباء سوريا تحت عنوان “المستجدات في الاختصاصات الطبية البشرية”، بحضور وزير الصحة مصعب العلي، ووزير التعليم العالي والبحث العلمي مروان الحلبي، وذلك في فندق البوابات السبع بدمشق. وسيستمر المؤتمر ثلاثة أيام ليسلط الضوء على أبرز المستجدات الطبية، ويهدف إلى تعزيز دور البحث العلمي والتعاون المهني […]', 'Today, Thursday, April 2, the work of the first scientific conference of the Syrian Doctors Syndicate began under the title “Developments in Human Medical Specialties,” in the presence of the Minister of Health, Musab Al-Ali, and the Minister of Higher Education and Scientific Research, Marwan Al-Halabi, at the Hotel The Seven Gates of Damascus. The conference will last for three days to highlight the most prominent medical developments, and aims to enhance the role of scientific research and professional cooperation [...]', 'انطلقت اليوم، الخميس 2 نيسان، أعمال المؤتمر العلمي الأول لنقابة أطباء سوريا تحت عنوان “المستجدات في الاختصاصات الطبية البشرية”، بحضور وزير الصحة مصعب العلي، ووزير التعليم العالي والبحث العلمي مروان الحلبي، وذلك في فندق البوابات السبع بدمشق. وسيستمر المؤتمر ثلاثة أيام ليسلط الضوء على أبرز المستجدات الطبية، ويهدف إلى تعزيز دور البحث العلمي والتعاون المهني في تطوير القطاع الصحي. بحسب مراسل الإخبارية . وكان وزير التعليم العالي والبحث العلمي الدكتور مروان الحلبي قد بحث، يوم الأربعاء 1 نيسان، مع وفد من مجموعة منظمات طبية أمريكية، برئاسة الدكتور محمد أغيد جمعة، سبل تعزيز التعاون في دعم المستشفيات الجامعية. بحسب ما نشرت الوزارة عبر معرفاتها الرسمية. وتناول الجانبان تنفيذ مشروع لتزويد المستشفى الوطني الجامعي بجهاز قثطرة وعائية دماغية، إضافة إلى تقديم جهاز قثطرة قلبية لمستشفى المواساة الجامعي في دمشق.', 'Today, Thursday, April 2, the work of the first scientific conference of the Syrian Doctors Syndicate began under the title “Developments in Human Medical Specialties,” in the presence of the Minister of Health, Musab Al-Ali, and the Minister of Higher Education and Scientific Research, Marwan Al-Halabi, at the Hotel The Seven Gates of Damascus. The conference will last for three days to highlight the most prominent medical developments, and aims to enhance the role of scientific research and professional cooperation in developing the health sector. According to the news correspondent. He was Minister of Higher Education and Research Scientific Dr. Marwan Al-Halabi discussed, on Wednesday, April 1, with a delegation from a group of American medical organizations, headed by Dr. Muhammad Aghid Juma, ways to enhance cooperation in supporting university hospitals. According to what the Ministry published through its official accounts. The two sides discussed the implementation of a project to provide the National University Hospital with a cerebral vascular catheterization device, in addition to providing a cardiac catheterization device to Al-Mouwasat University Hospital in Damascus.', 'https://alikhbariah.com/wp-content/uploads/2026/04/The-first-scientific-conference-of-the-Syrian-Doctors-Syndicate-has-begun.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-02T09:45:28+03:00'::timestamptz, false, true, false, 130),
  ('الحسكة.. مديرية الصحة تزود المنطقة الصحية في القامشلي بشحنة أدوية جديدة', 'Al-Hasakah.. The Health Directorate provides the health region in Qamishli with a shipment of new medicines', 'أعلنت مديرية صحة الحسكة تزويد المنطقة الصحية في القامشلي بشحنة دوائية جديدة، في إطار دعم جاهزية المؤسسات الصحية وتلبية احتياجاتها، وفقًا لما نقلت مديرية إعلام الحسكة، الأربعاء ١ نيسان. وبحسب مديرية الصحة، تضمنت الشحنة 32 صنفاً دوائياً متنوعاً شملت أدوية أساسية لمرضى الأمراض المزمنة، أبرزها الإنسولين وأدوية السكري الفموية، فضلاً عن بخاخات الربو والمضادات الحيوية […]', 'The Al-Hasakah Health Directorate announced that it would supply the health region in Qamishli with a new shipment of medicine, within the framework of supporting the readiness of health institutions and meeting their needs, according to what the Al-Hasakah Media Directorate reported on Wednesday, April 1. According to the Health Directorate, the shipment included 32 diverse pharmaceutical classes included essential medications for patients with chronic diseases, most notably insulin and oral diabetes medications, as well as asthma sprays and antibiotics […]', 'أعلنت مديرية صحة الحسكة تزويد المنطقة الصحية في القامشلي بشحنة دوائية جديدة، في إطار دعم جاهزية المؤسسات الصحية وتلبية احتياجاتها، وفقًا لما نقلت مديرية إعلام الحسكة، الأربعاء ١ نيسان. وبحسب مديرية الصحة، تضمنت الشحنة 32 صنفاً دوائياً متنوعاً شملت أدوية أساسية لمرضى الأمراض المزمنة، أبرزها الإنسولين وأدوية السكري الفموية، فضلاً عن بخاخات الربو والمضادات الحيوية ومسكنات الألم وأدوية خفض ضغط الدم، إلى جانب أصناف أخرى ضرورية. وباشرت مديرية صحة الحسكة إجراءات التنسيق مع إدارة الخدمات الطبية العسكرية لاستلام مجموعة من الأجهزة والتجهيزات الطبية من المشفى العسكري في مدينة الشدادي، تمهيداً لنقلها إلى مشفى الشدادي العام، بحسب ما نشرت مديرية إعلام الحسكة في 11 آذار الماضي. وأوضح مدير الصحة خالد الخالد أن التجهيزات المزمع نقلها تشمل أجهزة “أشعة بسيطة، إيكو، طبقي محوري”، وعدداً من أجهزة المختبر، إضافة إلى مواد ومستلزمات طبية وأثاث وتجهيزات خدمية.', 'The Al-Hasakah Health Directorate announced that it would supply the health region in Qamishli with a new shipment of medicine, within the framework of supporting the readiness of health institutions and meeting their needs, according to what the Al-Hasakah Media Directorate reported on Wednesday, April 1. According to the Health Directorate, the shipment included 32 various types of medications included essential medications for patients with chronic diseases, most notably insulin and oral diabetes medications, as well as asthma sprays, antibiotics, pain relievers, and blood pressure-lowering medications, in addition to other essential items. And I started Al-Hasakah Health Directorate coordinated procedures with the Military Medical Services Administration to receive a group of medical devices and equipment from the military hospital in the city of Al-Shaddadi, in preparation for transferring them to Al-Shaddadi General Hospital, according to what was published by the Al-Hasakah Media Directorate. On March 11 last. Health Director Khaled Al-Khaled explained that the equipment to be transferred includes “simple x-ray, echo, and CT” machines, and a number of laboratory equipment, in addition to medical materials and supplies, furniture, and service equipment.', 'https://alikhbariah.com/wp-content/uploads/2026/04/Health-district-in-Qamishli-1.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T12:30:41+03:00'::timestamptz, false, true, false, 129),
  ('معاون محافظ حماة يبحث مع مديري المشافي الخاصة تطوير الخدمات الطبية', 'Assistant Governor of Hama discusses with private hospital directors the development of medical services', 'بحث معاون محافظ حماة لقطاع الصحة محمد الشريف، مع مديري المشافي الخاصة سبل تحسين الخدمات الطبية ورفع كفاءة العمل في القطاع الصحي. وتطرق الاجتماع إلى التركيز على تقديم خدمات طبية عالية الجودة وضمان سلامة المرضى والكادر الطبي، إلى جانب تناول أبرز التحديات والاستماع إلى مقترحات المعنيين. بحسب ما نشرت المحافظة عبر معرفاتها الرسمية الثلاثاء 31 […]', 'The Assistant Governor of Hama for the health sector, Muhammad Al-Sharif, discussed with the directors of private hospitals ways to improve medical services and raise the efficiency of work in the health sector. The meeting focused on providing high-quality medical services and ensuring the safety of patients and staff Medical, in addition to addressing the most prominent challenges and listening to the suggestions of those concerned. According to what the governorate published through its official accounts on Tuesday, 31 […]', 'بحث معاون محافظ حماة لقطاع الصحة محمد الشريف، مع مديري المشافي الخاصة سبل تحسين الخدمات الطبية ورفع كفاءة العمل في القطاع الصحي. وتطرق الاجتماع إلى التركيز على تقديم خدمات طبية عالية الجودة وضمان سلامة المرضى والكادر الطبي، إلى جانب تناول أبرز التحديات والاستماع إلى مقترحات المعنيين. بحسب ما نشرت المحافظة عبر معرفاتها الرسمية الثلاثاء 31 آذار. وأكد المشاركون على ضرورة الالتزام المهني والتقيد بمعايير النظافة والتعقيم لضمان جودة الخدمات وحماية صحة المواطنين. وأواخر تشرين الأول الفائت، افتتح وزير الصحة مصعب العلي، قسم غسيل الكلى في مشفى حماة الوطني، وذلك بعد تأهيله وتجهيزه، بهدف تطوير مراكز الغسيل الكلوي وتحسين جودة الخدمات الطبية في مختلف المحافظات. وقال وزير الصحة حينها، إنه “تم تزويد القسم بـ30 جهازاً حديثاً مقدمة من وزارة الصحة بالتعاون مع منظمة “ميدغلوبل” و”منظمة الإغاثة الإسلامية” ، وفقاً لما نقلت معرفات الوزارة الرسمية. وأكد الوزير أن', 'The Assistant Governor of Hama for the health sector, Muhammad Al-Sharif, discussed with the directors of private hospitals ways to improve medical services and raise the efficiency of work in the health sector. The meeting focused on providing high-quality medical services and ensuring the safety of patients and staff Medical, in addition to addressing the most prominent challenges and listening to the suggestions of those concerned. According to what the governorate published through its official accounts on Tuesday, March 31. Participants stressed the need for professional commitment and adherence to hygiene and sterilization standards to ensure quality Services and protecting citizens'' health. In late October, the Minister of Health, Musab Al-Ali, opened the dialysis department at the Hama National Hospital, after rehabilitating and equipping it, with the aim of developing dialysis centers and improving the quality of medical services in various areas. Governorates. The Minister of Health said at the time, “The department was provided with 30 modern devices provided by the Ministry of Health in cooperation with the “MedGlobal” organization and the “Islamic Relief Organization,” according to what was reported by the official Ministry sources. The Minister confirmed that', 'https://alikhbariah.com/wp-content/uploads/2026/04/Medical-services-in-Hama.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-04-01T01:00:43+03:00'::timestamptz, false, false, false, 128),
  ('توقيع اتفاقية تأمين صحي لأكثر من 11 ألف عامل في الشركة السورية للاتصالات', 'Signing a health insurance agreement for more than 11,000 workers at the Syrian Telecommunications Company', 'وقعت المؤسسة العامة السورية للتأمين، الإثنين 30 آذار، عقد تأمين صحي شامل مع الشركة السورية للاتصالات، لتغطية نحو 11,500 عامل وموظف، وذلك بحضور وزير المالية محمد يسر برنية ووزير الاتصالات وتقانة المعلومات عبد السلام هيكل. ويهدف العقد إلى تعزيز مظلة الرعاية الصحية والاجتماعية للعاملين، بما يسهم في تعزيز الاستقرار الوظيفي وتحسين بيئة العمل، إضافة إلى […]', 'On Monday, March 30, the Syrian General Insurance Corporation signed a comprehensive health insurance contract with the Syrian Telecommunications Company, to cover about 11,500 workers and employees, in the presence of the Minister of Finance, Muhammad Yusser Barneyah, and the Minister of Communications and Information Technology, Abdul Salam. structure. The contract aims to strengthen the health and social care umbrella for workers, which contributes to enhancing job stability and improving the work environment, in addition to [...]', 'وقعت المؤسسة العامة السورية للتأمين، الإثنين 30 آذار، عقد تأمين صحي شامل مع الشركة السورية للاتصالات، لتغطية نحو 11,500 عامل وموظف، وذلك بحضور وزير المالية محمد يسر برنية ووزير الاتصالات وتقانة المعلومات عبد السلام هيكل. ويهدف العقد إلى تعزيز مظلة الرعاية الصحية والاجتماعية للعاملين، بما يسهم في تعزيز الاستقرار الوظيفي وتحسين بيئة العمل، إضافة إلى رفع مستوى الخدمات المقدمة ضمن المؤسسات العامة، بحسب ما نشرت وزارة المالية عبر منصاتها ا لرسمية. من جانبه، أكد وزير المالية أن توقيع العقد جاء بعد عملية تنافسية شفافة، مشيراً إلى الحرص على تقوية حوكمة الشركات والمؤسسات الاقتصادية المملوكة للدولة، وتعزيز تنافسيتها. ولفت إلى أن المرحلة المقبلة ستشهد اهتماماً أكبر بتطوير الضمان الصحي للعاملين، والذي ينعكس بدوره إيجاباً على الأداء وجودة الخدمات المقدمة. وكان الوزير برنية ووزير الصحة مصعب العلي، قد عقدا في 30 كانون الأول، مؤتمراً صحفياً مشتركاً حول خط', 'On Monday, March 30, the Syrian General Insurance Corporation signed a comprehensive health insurance contract with the Syrian Telecommunications Company, to cover about 11,500 workers and employees, in the presence of the Minister of Finance, Muhammad Yusser Barneyah, and the Minister of Communications and Information Technology, Abdul Salam. structure. The contract aims to strengthen the umbrella of health and social care for workers, which contributes to enhancing job stability and improving the work environment, in addition to raising the level of services provided within public institutions, according to what the Ministry of Finance published via Its official platforms. For his part, the Minister of Finance confirmed that the signing of the contract came after a transparent competitive process, indicating the keenness to strengthen the governance of state-owned companies and economic institutions, and enhance their competitiveness. He pointed out that the next stage will witness Greater interest in developing health insurance for workers, which in turn reflects positively on the performance and quality of services provided. On December 30, Minister Bernieh and Minister of Health Musab Al-Ali held a joint press conference about the line.', 'https://alikhbariah.com/wp-content/uploads/2026/03/agreement.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-30T19:07:18+03:00'::timestamptz, false, false, false, 127),
  ('وزير الصحة: المرسوم 68 رسالة تقدير للكوادر الطبية', 'Minister of Health: Decree 68 is a letter of appreciation to medical personnel', 'أكد وزير الصحة الدكتور مصعب العلي، أن صدور المرسوم رقم 68 لعام 2026 القاضي بزيادة الرواتب والأجور، يشكل رسالة تقدير ووفاء حقيقية للعاملين، ولا سيما الكوادر الطبية، ويعكس التوجه نحو تحسين واقع القطاع الصحي. وأوضح العلي أن هذه الخطوة تؤكد أن الاستثمار في الإنسان هو المدخل الحقيقي لتطوير الخدمات الصحية ورفع جودتها، حسب ما نشرته […]', 'The Minister of Health, Dr. Musab Al-Ali, confirmed that the issuance of Decree No. 68 of 2026 stipulating increasing salaries and wages constitutes a true message of appreciation and loyalty to workers, especially medical personnel, and reflects the trend towards improving the reality of the health sector. Al-Ali explained This step confirms that investing in people is the real gateway to developing health services and raising their quality, according to what was published […]', 'أكد وزير الصحة الدكتور مصعب العلي، أن صدور المرسوم رقم 68 لعام 2026 القاضي بزيادة الرواتب والأجور، يشكل رسالة تقدير ووفاء حقيقية للعاملين، ولا سيما الكوادر الطبية، ويعكس التوجه نحو تحسين واقع القطاع الصحي. وأوضح العلي أن هذه الخطوة تؤكد أن الاستثمار في الإنسان هو المدخل الحقيقي لتطوير الخدمات الصحية ورفع جودتها، حسب ما نشرته وزارة الصحة عبر معرفاتها الرسمية السبت 21 آذار. وأشار إلى أن وزارة الصحة تؤمن بأن استقرار الكوادر مهنياً ومعيشياً يمثل الضامن الأهم لجودة الرعاية الصحية، وحجر الأساس في تعزيز الأمان الصحي للمجتمع. وأضاف العلي أن الوزارة تبارك لكوادرها هذا التقدير، معربة عن تطلعها إلى انتظام أكبر في تقديم الخدمات الصحية لكل من يحتاجها. وأصدر السيد الرئيس أحمد الشرع المرسوم رقم (68) لعام 2026 القاضي بتطبيق لائحة زيادة نوعية على رواتب وأجور العاملين في سبع جهات عامة، متضمنة علاوة الترفيع المستحقة بموجب القانون رقم /50/ لعام 2004. وجاء ال', 'The Minister of Health, Dr. Musab Al-Ali, confirmed that the issuance of Decree No. 68 of 2026 stipulating increasing salaries and wages constitutes a true message of appreciation and loyalty to workers, especially medical personnel, and reflects the trend towards improving the reality of the health sector. Al-Ali explained This step confirms that investing in people is the real gateway to developing health services and raising their quality, according to what the Ministry of Health published through its official websites on Saturday, March 21. He pointed out that the Ministry of Health believes in the professional stability of cadres Living is the most important guarantee of quality health care, and the cornerstone of enhancing community health security. Al-Ali added that the Ministry congratulates its staff on this appreciation, expressing its aspiration for greater regularity in providing health services to everyone who needs them. President Ahmed Al-Sharaa issued Decree No. (68) of 2026 implementing regulations for a qualitative increase in the salaries and wages of workers in seven public agencies, including the promotion bonus due under Law No. /50/ of 2004. The decision came', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Health-Decree-68-is-a-message-of-appreciation-to-medical-staff.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-21T20:41:31+03:00'::timestamptz, false, false, false, 126),
  ('الرقابة والتفتيش تكشف مخالفات إدارية وفنية في أحد مشافي ريف دمشق', 'Oversight and inspection reveal administrative and technical violations in a hospital in the Damascus countryside', 'كشفت الهيئة المركزية للرقابة والتفتيش، الإثنين 16 آذار، عن مخالفات إدارية وفنية في أحد مشافي محافظة ريف دمشق، وذلك في إطار متابعة أداء المؤسسات الصحية والتحقق من الالتزام بالأنظمة والقوانين الناظمة للعمل الطبي. ورصدت الفرق الرقابية التابعة للهيئة خلال جولة رقابية غياب آليات واضحة لتوثيق المواد الطبية المستخدمة داخل المشفى، وعدم حفظ الأضابير الخاصة بملفات […]', 'On Monday, March 16, the Central Authority for Control and Inspection revealed administrative and technical violations in a hospital in the Damascus countryside governorate, within the framework of monitoring the performance of health institutions and verifying compliance with the regulations and laws regulating medical work. And spotted The Authority’s oversight teams during an oversight tour. The absence of clear mechanisms for documenting medical materials used inside the hospital, and the failure to save files related to […]', 'كشفت الهيئة المركزية للرقابة والتفتيش، الإثنين 16 آذار، عن مخالفات إدارية وفنية في أحد مشافي محافظة ريف دمشق، وذلك في إطار متابعة أداء المؤسسات الصحية والتحقق من الالتزام بالأنظمة والقوانين الناظمة للعمل الطبي. ورصدت الفرق الرقابية التابعة للهيئة خلال جولة رقابية غياب آليات واضحة لتوثيق المواد الطبية المستخدمة داخل المشفى، وعدم حفظ الأضابير الخاصة بملفات المرضى وفق الأصول القانونية، إضافة إلى إهمال متابعة الإجراءات الفنية اللازمة لصيانة الأجهزة الطبية المتوقفة عن العمل، وغياب عدد من العاملين أثناء تنفيذ الجولة. وأوضحت الهيئة أنه وبناءً على نتائج التفتيش فقد تم اتخاذ إجراءات تصحيحية وعقابية شملت توجيه عقوبة التنبيه لعدد من العاملين المقصرين، واحتساب غياب الموظفين غير المتواجدين كإجازة بلا أجر، إلى جانب الإيعاز بإصلاح الأجهزة الطبية المعطلة ورفد المشفى بالكوادر اللازمة، مع اعتماد سجلات لتوثيق الإجراءات والخدمات المقدمة. وأشارت إلى أن هذه ال', 'On Monday, March 16, the Central Authority for Control and Inspection revealed administrative and technical violations in a hospital in the Damascus countryside governorate, within the framework of monitoring the performance of health institutions and verifying compliance with the regulations and laws regulating medical work. And spotted The Authority’s oversight teams during a monitoring tour. The absence of clear mechanisms for documenting the medical materials used inside the hospital, and the failure to keep files related to patient files in accordance with legal procedures, in addition to neglecting to follow up on the necessary technical procedures. To maintain medical equipment that has stopped working, and the absence of a number of workers during the tour. The authority explained that, based on the results of the inspection, corrective and punitive measures were taken, including directing warning penalties to a number of negligent employees. The absence of employees who are not present is counted as unpaid leave, in addition to instructions to repair broken medical equipment and provide the hospital with the necessary personnel, while adopting records to document the procedures and services provided. She indicated that this...', 'https://alikhbariah.com/wp-content/uploads/2026/03/Oversight-and-inspection-uncovers-administrative-and-technical-violations-in-a-hospital-in-rural-Damascus.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-16T17:50:26+03:00'::timestamptz, false, false, false, 125),
  ('وزير الدفاع يتفقد مستشفى دمشق العسكري استعداداً لافتتاحه', 'The Minister of Defense inspects Damascus Military Hospital in preparation for its opening', 'أجرى وزير الدفاع مرهف أبو قصرة جولة تفقدية في مستشفى دمشق العسكري، رفقة مدير المستشفى سالم عبدان، للاطلاع على التحضيرات النهائية قبيل افتتاح المستشفى من قبل إدارة الخدمات الطبية العسكرية. وأشارت الوزارة عبر معرفاتها الرسمية الخميس 12 آذار، إلى أن المستشفى سيبدأ قريباً بتقديم خدماته الطبية للعسكريين، إضافة إلى الأهالي وفق الخطة الموضوعة. وفي 23 […]', 'Defense Minister Murhaf Abu Qasra conducted an inspection tour of Damascus Military Hospital, accompanied by the hospital director, Salem Abdan, to see the final preparations ahead of the opening of the hospital by the Military Medical Services Administration. The Ministry indicated through its identifiers Official announcement Thursday, March 12, that the hospital will soon begin providing medical services to soldiers, in addition to families, according to the established plan. On the 23rd […]', 'أجرى وزير الدفاع مرهف أبو قصرة جولة تفقدية في مستشفى دمشق العسكري، رفقة مدير المستشفى سالم عبدان، للاطلاع على التحضيرات النهائية قبيل افتتاح المستشفى من قبل إدارة الخدمات الطبية العسكرية. وأشارت الوزارة عبر معرفاتها الرسمية الخميس 12 آذار، إلى أن المستشفى سيبدأ قريباً بتقديم خدماته الطبية للعسكريين، إضافة إلى الأهالي وفق الخطة الموضوعة. وفي 23 تشرين الأول، أعلنت إدارة الخدمات الطبية العسكرية في وزارة الدفاع عن رغبتها ب التعاقد مع عدد من خريجي الكليات والمعاهد في مختلف الاختصاصات، ضمن مشفى دمشق العسكري، وذلك لرفده بالكادر الطبي المناسب.', 'Defense Minister Murhaf Abu Qasra conducted an inspection tour of Damascus Military Hospital, accompanied by the hospital director, Salem Abdan, to see the final preparations ahead of the opening of the hospital by the Military Medical Services Administration. The Ministry indicated through its identifiers Official announcement Thursday, March 12, that the hospital will soon begin providing medical services to soldiers, in addition to families, according to the established plan. On October 23, the Department of Military Medical Services at the Ministry of Defense announced its desire to contract with A number of graduates of colleges and institutes in various specialties, within the Damascus Military Hospital, in order to provide it with the appropriate medical staff.', 'https://alikhbariah.com/wp-content/uploads/2026/03/Defense-Minister-Marhaf-Abu-Qasra-5.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-12T10:13:50+03:00'::timestamptz, false, false, false, 124),
  ('افتتاح أول مركز تخصصي لغسيل الكلى جنوب إدلب', 'Opening of the first specialized dialysis center in southern Idlib', 'افتتح وزير الصحة مصعب العلي، الأربعاء 11 آذار، مركز الرعاية الثالثة المتخصص بغسيل الكلى، والذي يعد المركز الوحيد من نوعه في ريف إدلب الجنوبي. ويهدف المركز الذي جهز بـ27 سريراً، إلى تعزيز الرعاية الصحية في المنطقة وتخفيف معاناة المرضى عبر توفير العلاج اللازم بالقرب من مناطق سكنهم، وفق ما أوردت وزارة الصحة عبر معرفاتها الرسمية. […]', 'On Wednesday, March 11, Minister of Health Musab Al-Ali opened the tertiary care center specializing in dialysis, which is the only center of its kind in the southern countryside of Idlib. The center, which is equipped with 27 beds, aims to enhance health care in the region and reduce... The suffering of patients through the provision of necessary treatment near their areas of residence, according to what the Ministry of Health reported through its official accounts. […]', 'افتتح وزير الصحة مصعب العلي، الأربعاء 11 آذار، مركز الرعاية الثالثة المتخصص بغسيل الكلى، والذي يعد المركز الوحيد من نوعه في ريف إدلب الجنوبي. ويهدف المركز الذي جهز بـ27 سريراً، إلى تعزيز الرعاية الصحية في المنطقة وتخفيف معاناة المرضى عبر توفير العلاج اللازم بالقرب من مناطق سكنهم، وفق ما أوردت وزارة الصحة عبر معرفاتها الرسمية. وأواخر تشرين الأول الفائت، افتتح العلي، قسم غسيل الكلى في مشفى حماة الوطني، وذلك بعد تأهيله وتجهيزه، بهدف تطوير مراكز الغسيل الكلوي وتحسين جودة الخدمات الطبية في مختلف المحافظات. وقال وزير الصحة حينها، إنه “تم تزويد القسم بـ30 جهازاً حديثاً مقدمة من وزارة الصحة بالتعاون مع منظمة “ميدغلوبل” و”منظمة الإغاثة الإسلامية” ، وفق ما نقلت معرفات الوزارة الرسمية. وأكد الوزير أن افتتاح قسم غسيل الكلى يشكل خطوة نوعية لتحسين الخدمات لمرضى الكلى، ويخدم القسم نحو 300 مريض من محافظة حماة.', 'On Wednesday, March 11, Minister of Health Musab Al-Ali opened the tertiary care center specializing in dialysis, which is the only center of its kind in the southern countryside of Idlib. The center, which is equipped with 27 beds, aims to enhance health care in the region and reduce... The suffering of patients through the provision of necessary treatment near their areas of residence, according to what the Ministry of Health reported through its official accounts. In late October, Al-Ali opened the dialysis department at Hama National Hospital, after rehabilitating and equipping it, with the aim of developing Dialysis centers and improving the quality of medical services in various governorates. The Minister of Health said at the time, “The department was provided with 30 modern devices provided by the Ministry of Health in cooperation with the MedGlobal Organization and the Islamic Relief Organization,” according to what was reported. Official Ministry IDs. The Minister stressed that the opening of the dialysis department constitutes a qualitative step to improve services for kidney patients, and the department serves about 300 patients from Hama Governorate.', 'https://alikhbariah.com/wp-content/uploads/2026/03/Kidney-Dialysis-Center.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-11T21:10:43+03:00'::timestamptz, false, false, false, 123),
  ('وزارة الصحة تزود مستشفى الرقة للأطفال بمعدات طبية حديثة', 'The Ministry of Health provides Al-Raqqa Children''s Hospital with modern medical equipment', 'زوّدت وزارة الصحة مديرية صحة الرقة بعدد من الأجهزة والمعدّات الطبية الحديثة، بهدف تعزيز قدراتها على تلبية الاحتياجات المتزايدة للسكان. وقالت وزارة الصحة عبر معرفاتها الرسمية، الأربعاء 11 آذار، إنه تم تزويد مشفى الأطفال التخصصي في الرقة بتجهيزات نوعية شملت ثلاث حواضن للعناية بالوليد وثلاث حواضن عادية، إضافة إلى ثلاث حواضن أوتوماتيكية، مما يسهم في […]', 'The Ministry of Health provided the Raqqa Health Directorate with a number of modern medical devices and equipment, with the aim of enhancing its capabilities to meet the growing needs of the population. The Ministry of Health said through its official accounts, on Wednesday, March 11, that the Children’s Hospital had been provided The Specialist Specialist Hospital in Raqqa provided quality equipment that included three incubators for newborn care and three regular incubators, in addition to three automatic incubators, which contributes to [...]', 'زوّدت وزارة الصحة مديرية صحة الرقة بعدد من الأجهزة والمعدّات الطبية الحديثة، بهدف تعزيز قدراتها على تلبية الاحتياجات المتزايدة للسكان. وقالت وزارة الصحة عبر معرفاتها الرسمية، الأربعاء 11 آذار، إنه تم تزويد مشفى الأطفال التخصصي في الرقة بتجهيزات نوعية شملت ثلاث حواضن للعناية بالوليد وثلاث حواضن عادية، إضافة إلى ثلاث حواضن أوتوماتيكية، مما يسهم في رفع مستوى الرعاية الصحية المقدّمة للأطفال حديثي الولادة. وأكد مدير صحة الرقة عبدالله الحمود أن هذه التجهيزات ستسهم بشكل فاعل في تحسين جودة الخدمات الطبية وتخفيف الأعباء المادية عن الأهالي، مشيراً إلى استمرار جهود التحديث والتطوير لضمان كفاءة جميع المرافق الصحية في عموم المحافظة. وفي 24 كانون الثاني، سلّمت وزارة الصحة 20 جهازاً حديثاً لغسيل الكلى إلى مستشفى الرقة الوطني، ضمن جهود تطوير القطاع الصحي في المحافظة لخدمة ما يقارب 380 مريضاً بالقصور الكلوي. وتأتي هذه الخطوات استجابة مباشرة لاحتياجات المح', 'The Ministry of Health provided the Raqqa Health Directorate with a number of modern medical devices and equipment, with the aim of enhancing its capabilities to meet the growing needs of the population. The Ministry of Health said through its official accounts, on Wednesday, March 11, that the Children’s Hospital had been provided The specialist hospital in Raqqa has quality equipment that includes three neonatal care incubators and three regular incubators, in addition to three automatic incubators, which contributes to raising the level of health care provided to newborns. Raqqa Health Director Abdullah confirmed Al-Hamoud said that these equipment will contribute effectively to improving the quality of medical services and reducing the financial burdens on the people, indicating the continuation of modernization and development efforts to ensure the efficiency of all health facilities throughout the governorate. On January 24, The Ministry of Health delivered 20 modern dialysis machines to Raqqa National Hospital, as part of efforts to develop the health sector in the governorate to serve approximately 380 patients with renal failure. These steps come in direct response to the needs of the community', 'https://alikhbariah.com/wp-content/uploads/2026/03/Medical-equipment.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-11T12:00:03+03:00'::timestamptz, false, false, false, 122),
  ('مديرية صحة دير الزور تطالب المشافي والمراكز الطبية باستكمال الترخيص', 'Deir ez-Zor Health Directorate requires hospitals and medical centers to complete licensing', 'أصدرت مديرية صحة دير الزور، الثلاثاء 10 آذار، تعميماً موجهاً إلى جميع المشافي والمراكز الطبية الخاصة والخيرية، دعت فيه أصحاب المنشآت إلى مراجعة المديرية خلال أسبوع عمل لاستكمال إجراءات الترخيص وتحديث بياناتهم. وذكرت المديرية عبر معرفاتها الرسمية أن التعميم يشمل جميع المنشآت الصحية — المرخصة والعاملة، أو المرخصة غير العاملة، أو غير المرخصة — بهدف […]', 'On Tuesday, March 10, the Deir ez-Zor Health Directorate issued a circular addressed to all hospitals and private and charitable medical centers, calling on facility owners to visit the directorate within a working week to complete licensing procedures and update their data. And I mentioned The Directorate, through its official information, stated that the circular includes all health facilities - licensed and operating, licensed but not operating, or unlicensed - with the aim of […]', 'أصدرت مديرية صحة دير الزور، الثلاثاء 10 آذار، تعميماً موجهاً إلى جميع المشافي والمراكز الطبية الخاصة والخيرية، دعت فيه أصحاب المنشآت إلى مراجعة المديرية خلال أسبوع عمل لاستكمال إجراءات الترخيص وتحديث بياناتهم. وذكرت المديرية عبر معرفاتها الرسمية أن التعميم يشمل جميع المنشآت الصحية — المرخصة والعاملة، أو المرخصة غير العاملة، أو غير المرخصة — بهدف تحديث البيانات لدى دائرة المنشآت الصحية، بما يحقق المصلحة العامة. ونوهت المديرية بأن عملية المراجعة ستعتمد لإعادة تقييم المنشآت ومنح التراخيص، مؤكدة أن عدم المراجعة يجعل الإجراءات غير قانونية، ويعرّض أصحاب المنشآت لعقوبات قد تصل إلى إغلاق المراكز غير المسجلة بعد انتهاء المهلة المحددة. وفي سياق آخر، عقدت مديرية صحة دير الزور اجتماعاً مع وفد من اللجنة الدولية للصليب الأحمر (ICRC) وبرنامج الأمم المتحدة الإنمائي (UNDP)، لبحث دعم مراكز العلاج الفيزيائي وتركيب الأطراف الصناعية، وتطوير آليات العمل في الم', 'On Tuesday, March 10, the Deir ez-Zor Health Directorate issued a circular addressed to all hospitals and private and charitable medical centers, calling on facility owners to visit the directorate within a working week to complete licensing procedures and update their data. And I mentioned The Directorate, through its official identifiers, stated that the circular includes all health facilities - licensed and operating, licensed but not operating, or unlicensed - with the aim of updating data with the Health Facilities Department, in a way that achieves the public interest. The Directorate noted that The review process will be adopted to re-evaluate the facilities and grant licenses, stressing that failure to review makes the procedures illegal, and exposes the owners of the facilities to penalties that may amount to the closure of unregistered centers after the specified deadline has expired. In another context, it was held Deir ez-Zor Health Directorate held a meeting with a delegation from the International Committee of the Red Cross (ICRC) and the United Nations Development Program (UNDP), to discuss support for physical therapy centers and the installation of prosthetic limbs, and developing work mechanisms in the areas.', 'https://alikhbariah.com/wp-content/uploads/2026/03/Deir-ez-Zor-Health-Directorate.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations where slug = 'syria' limit 1), '2026-03-10T16:30:40+03:00'::timestamptz, false, false, false, 121)
;

-- =============================
-- 5) Breaking news (10 days x 5/day, each 24h)
-- =============================
with breaking_seed as (
  select * from (values
    (1, 'مظاهرات شعبية في عدة مدن سورية تنديداً بقانون إعدام الأسرى الفلسطينيين', 'Popular demonstrations in several Syrian cities denouncing the law on executing Palestinian prisoners', 'خرجت مظاهرات شعبية في عدة مدن ومناطق سورية، الجمعة 3 نيسان، تنديداً بقانون إعدام الأسرى الفلسطينيين الذي أقرّه الكنيست الإسرائيلي قبل أيام. وبحسب مراسلي الإخبارية، شهد حي الرمل الجنوبي في اللاذقية مظاهرة كبيرة، كما نظّم الأهالي في مدينة جرابلس شرق حلب وقفة تضامنية مع الشعب الفلسطيني، مؤكدين دعمهم للأسرى ورفضهم لممارسات الاحتلال الإسرائيلي. وشملت التظاهرات […]', 'Popular demonstrations took place in several Syrian cities and regions, Friday, April 3, denouncing the law on executing Palestinian prisoners that was approved by the Israeli Knesset a few days ago. According to my news correspondent, the southern Raml neighborhood in Latakia witnessed and organized a large demonstration The people of the city of Jarabulus, east of Aleppo, stand in solidarity with the Palestinian people, affirming their support for the prisoners and their rejection of the practices of the Israeli occupation. The demonstrations included […]'),
    (2, 'الهلالي: الفريق الرئاسي يعمل على إعادة 200 عائلة من الحسكة إلى عفرين', 'Al-Hilali: The presidential team is working to return 200 families from Hasakah to Afrin', 'أوضح المتحدّث باسم الفريق الرئاسي المكلّف بمتابعة تنفيذ اتفاق 29 كانون الثاني مع قسد أحمد الهلالي، أن الفريق يعمل على إعادة النازحين إلى مناطقهم في عفرين بالتنسيق مع قيادتي الأمن الداخلي في الحسكة وحلب والدفاع المدني. وأشار الهلالي إلى أن غداً السبت المصادف 4 نيسان، سيشهد عودة 200 عائلة إلى منازلها، ضمن برنامج منظّم يهدف […]', 'The spokesman for the presidential team charged with following up on the implementation of the January 29 agreement with the SDF, Ahmed Al-Hilali, explained that the team is working to return the displaced to their areas in Afrin in coordination with the leadership of the Internal Security in Hasakah and Aleppo and the Civil Defense. Al-Hilali pointed out that tomorrow, Saturday, April 4, will witness the return of 200 families to their homes, as part of an organized program aimed […]'),
    (3, 'أزمة الطحين والخبز في السويداء: معاناة يومية وصراع المصالح على قوت المواطنين', 'The flour and bread crisis in Suwayda: daily suffering and a conflict of interests over citizens’ livelihood', 'تتعمّق الأزمة الإنسانية في محافظة السويداء، حيث تتفاقم معاناة السكان جراء النفاد التام لمادة الطحين من الأفران، لتدخل المحافظة في أزمة خبز حادة تهدّد بتوقّف عدد من الأفران الرئيسة عن العمل، وسط تأكيدات من جانب المواطنين بحرمانهم من الحصول على أبسط مقوّمات الحياة الأساسية. وتُسلّط تصريحات المسؤولين وشهادات الأهالي، الضوء على أبعاد هذه المعاناة الإنسانية […]', 'The humanitarian crisis is deepening in As-Suwayda Governorate, where the population’s suffering is exacerbated as a result of the complete depletion of flour from bakeries, causing the governorate to enter into a severe bread crisis that threatens to cause a number of main bakeries to stop working, amid assurances from citizens. By depriving them of the most basic necessities of life. The statements of officials and the testimonies of families highlight the dimensions of this human suffering [...]'),
    (4, 'إدارة الأحوال المدنية توضح آليات تنفيذ المرسوم 13 لعام 2026', 'The Civil Status Administration clarifies the mechanisms for implementing Decree No. 13 of 2026', 'أوضحت إدارة الأحوال المدنية، الجمعة 3 نيسان، آليات تنفيذ المرسوم رقم 13 لعام 2026 القاضي بمنح الجنسية في الجمهورية العربية السورية للمواطنين من أصول كردية المقيمين على الأراضي السورية، بمن فيهم مكتومو القيد. جاء ذلك في توضيحات صادرة عن مدير الأحوال المدنية وعضو اللجنة العليا لتنفيذ المرسوم عبد الله العبد الله، مع تحديد بدء تنفيذ […]', 'On Friday, April 3, the Civil Status Administration clarified the mechanisms for implementing Decree No. 13 of 2026 granting citizenship in the Syrian Arab Republic to citizens of Kurdish origin residing on Syrian territory, including those without registration. This came in Clarifications issued by the Director of Civil Status and member of the Supreme Committee for Implementing the Decree, Abdullah Al-Abdullah, specifying the start of implementation […]'),
    (5, 'وزارة العدل تعفي ذوي الإعاقة من الرسوم والتأمينات القضائية في جميع الدعاوى', 'The Ministry of Justice exempts people with disabilities from fees and judicial deposits in all cases', 'أعفت وزارة العدل جميع الأشخاص ذوي الإعاقة من الرسوم والتأمينات القضائية في جميع الدعاوى المقامة أمام المحاكم على اختلاف أنواعها ودرجاتها. جاء ذلك في تعميمٍ للوزارة، الجمعة 3 نيسان، استناداً إلى الكتاب الصادر عن وزارة الشؤون الاجتماعية والعمل بتاريخ 11 شباط 2026، وإلى أحكام المرسوم التشريعي رقم 19 لعام 2024، ولاسيما البند الخامس من الفقرة […]', 'The Ministry of Justice exempted all persons with disabilities from fees and judicial deposits in all cases filed before courts of all types and degrees. This came in a circular from the Ministry, Friday, April 3, based on the book issued by the Ministry Social Affairs and Labor dated February 11, 2026, and to the provisions of Legislative Decree No. 19 of 2024, especially item five of paragraph […]'),
    (6, 'الداخلية تكشف حصيلة الربع الأول من 2026: عمليات نوعية تستهدف ميليشيات النظام البائد', 'The Ministry of Interior reveals the outcome of the first quarter of 2026: specific operations targeting the militias of the former regime', 'أعلنت وزارة الداخلية عن حصيلة العمليات الأمنية النوعية التي نُفّذت خلال الربع الأول من عام 2026، والتي أسفرت عن إلقاء القبض على عشرات المجرمين وقيادات بارزة في ميليشيات النظام البائد. وأوضح أنفوغراف الوزارة، الصادر عنها اليوم الجمعة 3 نيسان، أن العمليات الأمنية خلال النصف الأول من كانون الثاني 2026 استهدفت مجموعة من المجرمين، نتج عنها […]', 'The Ministry of Interior announced the outcome of the qualitative security operations carried out during the first quarter of 2026, which resulted in the arrest of dozens of criminals and prominent leaders of the former regime’s militias. He explained the ministry''s infographic issued by it Today, Friday, April 3, security operations during the first half of January 2026 targeted a group of criminals, resulting in […]'),
    (7, 'مقتل ثلاثة أطفال وإصابة آخرين جراء انفجار لغم في بلدة الهبيط', 'Three children were killed and others injured as a result of a mine explosion in the town of Al-Habit', 'قتل ثلاثة أطفال وأصيب آخرون، جراء انفجار لغم أرضي من مخلّفات النظام البائد في مدرسة اليرموك الواقعة في بلدة الهبيط بريف إدلب الجنوبي، بحسب ما أفادت إذاعة دمشق. من جانبه، قال المكتب الإعلامي لمديرية صحة حماة في بيان صحفي نشرته المديرية عبر معرفاتها الرسمية، إن قسم الإسعاف في مشفى السقيلبية الوطني تلقى بلاغاً يفيد بوصول […]', 'Three children were killed and others were injured, as a result of the explosion of a landmine left over from the former regime in the Yarmouk School located in the town of Al-Habit in the southern countryside of Idlib, according to what Damascus Radio reported. For its part, the media office of the Hama Health Directorate said in a press statement Published by the Directorate through its official accounts, the Ambulance Department at Suqaylabiya National Hospital received a report stating the arrival […]'),
    (8, 'الدفاعات الإماراتية تتصدى لهجمات إيرانية.. وتعليق العمليات في منشآت حبشان للغاز', 'UAE defenses confront Iranian attacks... and suspend operations at Habshan gas facilities', 'أعلنت حكومة أبو ظبي، الجمعة 3 نيسان، تعليق العمليات في منشآت حبشان للغاز، إثر سقوط شظايا ناتج عن اعتراض دفاعاتها الجوية لصواريخ ومسيرات معادية، دون تسجيل أي إصابات. وقال مكتب أبو ظبي الإعلامي، في بيان نشره عبر منصة “إكس”، إن الجهات المختصة تتعامل مع حادثة سقوط شظايا في منشآت حبشان للغاز، بالتزامن مع اندلاع حريق […]', 'On Friday, April 3, the Abu Dhabi government announced the suspension of operations at the Habshan Gas facilities, following the fall of shrapnel resulting from its air defenses intercepting enemy missiles and drones, without recording any casualties. The Abu Dhabi Media Office said in a statement published on the platform “X”, the competent authorities are dealing with an incident of shrapnel falling at the Habshan Gas facilities, coinciding with the outbreak of a fire […]'),
    (9, 'هيئة دعم وتنمية الإنتاج المحلي والصادرات تطلق السجل الوطني للتصدير', 'The Authority for Support and Development of Local Production and Exports launches the National Export Register', 'أعلنت هيئة دعم وتنمية الإنتاج المحلي والصادرات، الجمعة 3 نيسان، عن الإطلاق الرسمي للسجل الوطني للتصدير، وذلك لتنظيم قطاع التصدير وضبط بيانات المصدرين، مع تحديد مهلة تنتهي في 30 حزيران القادم لتسجيل البيانات. ودعت الهيئة كافة المصدرين للمبادرة بالتسجيل خلال المهلة المحددة، مؤكدة أنه لن يُسمح لأي شخص أو شركة بمزاولة التصدير بعد انتهاء المهلة […]', 'The Authority for Support and Development of Local Production and Exports announced, on Friday, April 3, the official launch of the National Export Register, in order to organize the export sector and control exporters’ data, setting a deadline of next June 30 to register data. The authority called All exporters of the initiative must register within the specified deadline, stressing that no person or company will be allowed to engage in exports after the expiration of the deadline […]'),
    (10, 'الاتحاد الأوروبي: أسعار الطاقة ستبقى مرتفعة لفترة طويلة بسبب صراع الشرق الأوسط', 'European Union: Energy prices will remain high for a long time due to the Middle East conflict', 'أعلن الاتحاد الأوروبي، الجمعة 3 نيسان، أن أسعار الطاقة ستبقى مرتفعة لفترة زمنية طويلة بسبب الصراع في الشرق الأوسط. وأكد مفوض الطاقة بالاتحاد الأوروبي دان يورغنسن، في تصريح نقلته صحيفة فايننشال تايمز، أن أسعار الطاقة ستبقى مرتفعة لفترة زمنية طويلة جداً، مشدداً على أن الاتحاد الأوروبي يستعد لأسوأ السيناريوهات المحتملة جراء الصراع في الشرق الأوسط. […]', 'The European Union announced, on Friday, April 3, that energy prices will remain high for a long period of time due to the conflict in the Middle East. European Union Energy Commissioner Dan Jorgensen confirmed, in a statement reported by the Financial Times, that energy prices... It will remain high for a very long period of time, stressing that the European Union is preparing for the worst possible scenarios resulting from the conflict in the Middle East. […]'),
    (11, 'الكويت.. استهداف مصفاة ميناء الأحمدي والدفاعات الجوية تتصدى لهجمات صاروخية', 'Kuwait: Mina Al-Ahmadi refinery was targeted, and air defenses responded to missile attacks', 'أعلنت وزارة الدفاع الكويتية، الجمعة 3 نيسان، أن دفاعاتها الجوية تصدت لهجمات صاروخية وطائرات مسيرة استهدفت منشآتها الحيوية، مؤكدةً جاهزيتها للتعامل مع أي تهديدات تمس أمن البلاد وسيادتها. وقالت رئاسة هيئة الأركان الكويتية في بيان نشرته عبر منصة “إكس”: “تتصدى الدفاعات الجوية الكويتية حالياً لهجمات صاروخية ومسيرات معادية”. وفي السياق، ذكرت مؤسسة البترول الكويتية أن […]', 'The Kuwaiti Ministry of Defense announced, on Friday, April 3, that its air defenses responded to missile and drone attacks that targeted its vital facilities, confirming its readiness to deal with any threats affecting the country’s security and sovereignty. The Kuwaiti Chief of Staff said In a statement published on the “X” platform: “Kuwait air defenses are currently responding to missile attacks and hostile marches.” In this context, the Kuwait Petroleum Corporation stated that […]'),
    (12, 'الدفاع السعودية تعلن اعتراض وتدمير سبع طائرات مسيرة', 'Saudi Defense announces the interception and destruction of seven drones', 'أعلنت وزارة الدفاع السعودية، اليوم الجمعة 3 نيسان، اعتراض وتدمير سبع طائرات مسيرة خلال الساعات الماضية. وقال المتحدث باسم الوزارة اللواء الركن تركي المالكي في بيان نقلته وكالة الأنباء السعودية “واس”: إن قوات الدفاع الجوي تمكنت من اعتراض وتدمير سبع طائرات مسيرة. وكانت صحيفة “وول ستريت جورنال” الأمريكية أفادت، في 28 آذار الماضي، بأن قاعدة […]', 'Today, Friday, April 3, the Saudi Ministry of Defense announced the interception and destruction of seven drones during the past hours. Ministry spokesman, Major General Turki Al-Maliki, said in a statement carried by the Saudi News Agency “SPA”: The Defense Forces The air force was able to intercept and destroy seven drones. On March 28, the American newspaper “The Wall Street Journal” reported that the base […]'),
    (13, 'ترامب يحدد الأهداف القادمة.. الجسور ثم محطات الكهرباء', 'Trump sets the next goals: bridges, then power plants', 'قال الرئيس الأمريكي دونالد ترامب، الجمعة 3 نيسان، إن “الجيش الأمريكي هو الأقوى في العالم وبفارق كبير”، مضيفاً أن قيادة النظام الجديد في إيران تدرك ما يجب القيام به، وتدرك أنه يجب أن يُنجز بسرعة. وأوضح ترامب، في منشور على منصة “تروث سوشال”، أن الجيش الأمريكي لم يبدأ بعد بتدمير ما تبقى في إيران، مؤكداً […]', 'US President Donald Trump said on Friday, April 3, that “the American army is the strongest in the world by a large margin,” adding that the leadership of the new regime in Iran realizes what must be done, and realizes that it must be accomplished quickly. Trump explained, in a post On the “Truth Social” platform, the US army has not yet begun to destroy what remains in Iran, confirming […]'),
    (14, 'هطولات مطرية في مناطق متفرقة.. وانحسار تأثير المنخفض مساء', 'Rainfall in various areas... and the effect of the depression recedes in the evening', 'تستمر الهطولات المطرية خلال الساعات القادمة في مناطق متفرقة من البلاد، بسبب استمرار تأثرها بالمنخفض الجوي، على أن ينحسر تدريجياً مساء اليوم، الجمعة 3 نيسان، وفقاً للنشرة الصادرة عن المديرية العامة للأرصاد الجوية التابعة لوزارة الطوارئ وإدارة الكوارث. وكانت أجواء الليلة الماضية باردة نسبياً، وخاصة في المرتفعات الجبلية، مع تسجيل حالات لتشكل الضباب في أجزاء […]', 'Rainfall will continue during the coming hours in various areas of the country, due to its continued influence by the depression, and will gradually subside this evening, Friday, April 3, according to the bulletin issued by the General Directorate of Meteorology, which is responsible for... For the Ministry of Emergency and Disaster Management. The weather last night was relatively cold, especially in the mountain highlands, with cases of fog formation recorded in parts […]'),
    (15, 'أبو الغيط يطالب مجلس الأمن باتخاذ إجراءات لوقف الاعتداءات الإيرانية على الدول العربية', 'Aboul Gheit calls on the Security Council to take measures to stop Iranian attacks on Arab countries', 'أكد الأمين العام لجامعة الدول العربية، أحمد أبو الغيط، أنه أدان في خطابه أمام مجلس الأمن الدولي بأشد العبارات الاعتداءات الإيرانية بالصواريخ والطائرات المسيّرة على الدول العربية، واصفاً إياها بأنها انتهاك صارخ للقانون الدولي وميثاق الأمم المتحدة. وقال أبو الغيط في سلسلة تدوينات نشرها على حسابه عبر منصة X الجمعة 3 نيسان، إن استهداف المنشآت […]', 'The Secretary-General of the League of Arab States, Ahmed Aboul Gheit, confirmed that in his speech before the UN Security Council, he condemned in the strongest terms the Iranian attacks with missiles and drones on Arab countries, describing them as a blatant violation of the law. International and the Charter of the United Nations. Aboul Gheit said in a series of blog posts published on his account on the X platform on Friday, April 3, that targeting the facilities […]'),
    (16, 'الخط الدائري الجنوبي في حلب.. من الفوضى إلى التنظيم', 'The Southern Ring Line in Aleppo... from chaos to organization', 'تشهد حركة النقل في مدينة حلب تغييرات جذرية ساهمت في تنظيم الحالة المرورية، في إطار توجهات مديرية النقل في محافظة حلب، والتي تهدف إلى إعادة تنظيم خط نقل “الدائري الجنوبي”، الذي يعد أحد أكثر الخطوط حيوية وازدحاماً في المدينة. عملت مديرية النقل في حلب على إدخال حافلات جديدة لتغذية الخط الدائري الجنوبي وإبعاد الحافلات المخالفة، […]', 'The transportation movement in the city of Aleppo is witnessing radical changes that have contributed to organizing the traffic situation, within the framework of the directions of the Transport Directorate in Aleppo Governorate, which aims to reorganize the “Southern Ring” transportation line, which is one of the most vital and crowded lines in the city. City. The Transport Directorate in Aleppo worked to introduce new buses to feed the Southern Ring Line and remove the violating buses, […]'),
    (17, 'المبعوثة البريطانية: زيارة الرئيس الشرع للندن محطة مفصلية في العلاقات مع سوريا', 'The British envoy: President Al-Shara''s visit to London is a turning point in relations with Syria', 'أكدت الممثّلة الخاصة للمملكة المتحدة آن سنو، الخميس 2 نيسان، أن الزيارة الأخيرة، التي أجراها السيد الرئيس أحمد الشرع، إلى لندن شكّلت محطة مفصلية في مسار العلاقات بين المملكة وسوريا. وقالت سنو في منشور عبر منصة “إكس” إن الزيارة تضمنت لقاءات عدة وجولة في البرلمان ومناقشات حول سيادة القانون والتعددية السياسية، إضافةً إلى لقاء مع […]', 'The Special Representative of the United Kingdom, Anne Snow, confirmed on Thursday, April 2, that the recent visit by President Ahmed Al-Sharaa to London constituted a turning point in the course of relations between the Kingdom and Syria. Snow said in a post on the “X” platform: The visit included several meetings, a tour of Parliament, and discussions on the rule of law and political pluralism, in addition to a meeting with […]'),
    (18, 'الرئيس الشرع يبحث مع عضو بالكونغرس الأوضاع الإقليمية والدولية', 'President Al-Sharaa discusses with a member of Congress the regional and international situation', 'بحث السيد الرئيس أحمد الشرع، مع عضو الكونغرس الأمريكي كوري لي ميلز، الأوضاع الإقليمية والدولية الراهنة، وعدداً من القضايا ذات الاهتمام المشترك. جاء ذلك خلال استقبال الرئيس الشرع، عضو الكونغرس في قصر الشعب بدمشق، الخميس 2 نيسان، وفق ما نشرت رئاسة الجمهورية على معرّفاتها الرسمية. وخلال الساعات الماضية، كان الرئيس الشرع قد ناقش مع وكيل […]', 'Mr. President Ahmed Al-Sharaa discussed, with US Congressman Corey Lee Mills, the current regional and international situations, and a number of issues of common interest. This came during President Al-Sharaa’s reception, a member of Congress, at the People’s Palace in Damascus, on Thursday April 2, according to what the Presidency of the Republic published on its official websites. During the past hours, President Al-Sharaa had discussed with the Undersecretary [...]'),
    (19, 'الأمم المتحدة: سوريا يمكن أن تتحول إلى قصة نجاح بدعم دولي', 'United Nations: Syria can turn into a success story with international support', 'قال مدير برنامج الأمم المتحدة الإنمائي ألكسندر دي كرو، الخميس 2 نيسان، إن سوريا قادرة على التحول إلى قصة نجاح في مرحلة ما بعد الحرب، إذا توفر الدعم الدولي بالوقوف إلى جانب الشعب السوري. وأشار دي كرو، في منشور له على منصة “إكس”، إلى أن المرحلة الحالية تتطلب زيادة الدعم التنموي، بما يتيح إعادة بناء […]', 'Director of the United Nations Development Programme, Alexander De Croo, said on Thursday, April 2, that Syria is capable of turning into a success story in the post-war phase, if international support is available to stand by the Syrian people. De Croo noted, in his post on: The “X” platform indicated that the current stage requires increased development support, allowing the rebuilding of […]'),
    (20, 'وزارة الداخلية تقبض على متورطين بجريمة قتل بريف حمص', 'The Ministry of Interior arrests those involved in a murder in the Homs countryside', 'أعلنت وزارة الداخلية، الخميس 2 نيسان، أن مركز شرطة زيدل ألقى القبض على عدد من المتورطين في جريمة قتل المدعو إسماعيل مصطفى سفر من مدينة سلمية، والتي وقعت في شهر آذار الفائت على طريق زيدل – الجابرية بريف حمص. وأوضحت الوزارة، عبر منصاتها الرسمية، أنه بعد ورود بلاغ إلى مركز الشرطة في 14 آذار، كشفت […]', 'The Ministry of Interior announced, on Thursday, April 2, that the Zaidal Police Station arrested a number of those involved in the murder of Ismail Mustafa Safar from the city of Salamiya, which occurred last March on the Zaidal-Jabriya road in the Homs countryside. She explained The Ministry, through its official platforms, stated that after receiving a report to the police station on March 14, it revealed […]'),
    (21, 'وزارة الخارجية والمغتربين ترحب بخطة الاحتياجات الإنسانية لعام 2026', 'The Ministry of Foreign Affairs and Expatriates welcomes the 2026 Humanitarian Needs Plan', 'رحّب مدير إدارة التعاون الدولي في وزارة الخارجية والمغتربين قتيبة قاديش، بخطة الاحتياجات الإنسانية والاستجابة لعام 2026 الخاصة بسوريا، التي أطلقها وكيل الأمين العام للأمم المتحدة للشؤون الإنسانية ومنسق الإغاثة في حالات الطوارئ توم فيلتشر. وأكد قاديش خلال لقاء صحفي، الخميس 2 نيسان، التزام الوزارة بالعمل والتشاور والتنسيق مع مؤسسات الدولة، بما يحافظ على سيادة […]', 'Director of the International Cooperation Department at the Ministry of Foreign Affairs and Expatriates, Qutaiba Qadish, welcomed the 2026 humanitarian needs and response plan for Syria, launched by the United Nations Under-Secretary-General for Humanitarian Affairs and Relief Coordinator in Emergency Situations. Emergency Tom Fletcher. During a press interview, Thursday, April 2, Kadish affirmed the ministry’s commitment to working, consulting, and coordinating with state institutions, in a way that preserves the sovereignty of […]'),
    (22, 'أمين عام مجلس التعاون الخليجي: سلوك إيران تجاوز الخطوط الحمراء', 'Secretary-General of the Gulf Cooperation Council: Iran''s behavior has crossed red lines', 'قال أمين عام مجلس التعاون الخليجي جاسم البديوي، الخميس 2 نيسان، إن سلوك إيران تجاوز الخطوط الحمراء. وأكد البديوي في كلمته أمام مجلس الأمن، أن دول الخليج لا تدعو للحرب، مشدداً على حق دول المجلس الأصيل في الدفاع عن النفس. وفي 27 آذار الماضي، كشفت بيانات رسمية أن إيران وجهت نحو 83% من مجمل هجماتها […]', 'The Secretary-General of the Gulf Cooperation Council, Jassem Al-Budaiwi, said on Thursday, April 2, that Iran’s behavior crossed red lines. In his speech before the Security Council, Al-Budaiwi stressed that the Gulf states do not call for war, stressing the inherent right of the Council states to self-defense. On March 27, official data revealed that Iran directed about 83% of its total attacks […]'),
    (23, 'محافظ السويداء يبحث مع القائم بأعمال سفارة فرنسا تعزيز الأمن والاستقرار', 'The Governor of Suwayda discusses with the Chargé d''Affaires of the French Embassy the strengthening of security and stability', 'التقى محافظ السويداء مصطفى البكور، الخميس 2 نيسان، مع القائم بأعمال سفارة فرنسا في سوريا جان باتيست فافر، لبحث سبل تعزيز الأمن والاستقرار في المحافظة، وآفاق تطوير التعاون المشترك في مختلف المجالات. وأكد الجانبان خلال اللقاء أهمية تكثيف الجهود بما يسهم في دعم الاستقرار، وترسيخ مقومات التعافي على المستويين المحلي والوطني، بحسب ما نشرت محافظة […]', 'On Thursday, April 2, the Governor of Suwayda, Mustafa Al-Bakour, met with the Chargé d''Affaires of the French Embassy in Syria, Jean-Baptiste Favre, to discuss ways to enhance security and stability in the governorate, and prospects for developing joint cooperation in various fields. Both sides confirmed during The meeting emphasized the importance of intensifying efforts to contribute to supporting stability and consolidating the elements of recovery at the local and national levels, according to what the Governorate […]'),
    (24, 'توغل وإطلاق نار.. اعتداءات جديدة لجيش الاحتلال الإسرائيلي في ريف القنيطرة الغربي', 'Incursion and shooting... new attacks by the Israeli occupation army in the western countryside of Quneitra', 'توغل جيش الاحتلال الإسرائيلي، الخميس 2 نيسان، برتل يضم أربع آليات وجرافة في شمال قرية الأصبح بريف القنيطرة الجنوبي. وفي التفاصيل، أفاد مراسل الإخبارية بأن جيش الاحتلال نصب حاجزاً وأغلق الطريق بساتر ترابي، إضافة إلى قيامه بإطلاق النار لترويع المدنيين. وفي السياق، أضاف المراسل أن جيش الاحتلال منع مرور المدنيين عبر الطريق الذي يصل إلى […]', 'On Thursday, April 2, the Israeli occupation army entered a convoy of four vehicles and a bulldozer north of the village of Al-Asbah in the southern countryside of Quneitra. In detail, Al-Ekhbariya correspondent reported that the occupation army set up a checkpoint and closed the road with a dirt berm, in addition to He opened fire to terrorize civilians. In this context, the correspondent added that the occupation army prevented civilians from passing through the road that reaches […]'),
    (25, 'رئيس الهيئة العامة للمنافذ والجمارك يفتتح منفذ التنف – الوليد الحدودي مع العراق', 'The head of the General Authority of Ports and Customs opens the Al-Tanf - Al-Walid border crossing with Iraq', 'افتتح رئيس الهيئة العامة للمنافذ والجمارك قتيبة بدوي، الخميس 2 نيسان، منفذ التنف – الوليد الحدودي، بمشاركة رئيس هيئة المنافذ الحدودية العراقي عمر عدنان الوائلي والوفد المرافق له. وقال بدوي في منشور عبر منصة “إكس“: “افتتاح منفذ التنف – الوليد اليوم مع الأشقاء في جمهورية العراق يشكل خطوة مهمة في مسار تعزيز التعاون المشترك وتفعيل […]', 'On Thursday, April 2, the head of the General Authority of Ports and Customs, Qutaiba Badawi, opened the Al-Tanf-Al-Walid border crossing, with the participation of the head of the Iraqi Border Ports Authority, Omar Adnan Al-Waeli, and his accompanying delegation. Badawi said in a post on the “X” platform: “The opening of the Al-Tanf-Al-Waleed crossing today with our brothers in the Republic of Iraq constitutes an important step in the path of strengthening joint cooperation and activating […]'),
    (26, 'تجارة دمشق تعترض على رسوم الحماية الأردنية: تحدّ من تنافسية الصادرات السورية', 'Damascus trade objects to Jordanian protection fees: they limit the competitiveness of Syrian exports', 'اعترضت غرفة تجارة دمشق على الرسوم التي فرضتها المملكة الأردنية الهاشمية على بعض المنتجات السورية، وخاصة في قطاعات الصناعات الغذائية والمنسوجات. وأكدت الغرفة في بيان لها، الخميس 2 نيسان، أن ارتفاع هذه الرسوم يحد بشكل واضح من القدرة التنافسية للصادرات السورية ويعيق دخولها إلى السوق الأردنية بالشكل المطلوب. وأوضحت أن الرسوم المفروضة تؤثر سلباً على […]', 'The Damascus Chamber of Commerce objected to the fees imposed by the Hashemite Kingdom of Jordan on some Syrian products, especially in the food and textile industries sectors. The Chamber confirmed in a statement, Thursday, April 2, that the increase in these fees is limited It is clear from the competitiveness of Syrian exports and hinders their entry into the Jordanian market as required. She explained that the imposed fees negatively affect [...]'),
    (27, 'وزارة الخارجية والمغتربين تحدد 4 أولويات للتعافي في سوريا وخطة الاستجابة لعام 2026', 'The Ministry of Foreign Affairs and Expatriates sets 4 priorities for recovery in Syria and the response plan for 2026', 'أعلن مدير إدارة التعاون الدولي في وزارة الخارجية والمغتربين قتيبة قاديش، الخميس 2 نيسان، عن تحديد أربعة مجالات ذات أولوية للتعافي في سوريا وخطة الاستجابة للاحتياجات الإنسانية لعام 2026. وشملت المجالات التي حددت: استعادة البنية التحتية، وإعادة بناء المؤسسات العامة، والصمود الاجتماعي، وإزالة الألغام. وأوضح قاديش أن بيان أولويات التعافي في سوريا وخطة الاستجابة للاحتياجات […]', 'On Thursday, April 2, Director of the International Cooperation Department at the Ministry of Foreign Affairs and Expatriates, Qutaiba Kadish, announced the identification of four priority areas for recovery in Syria and the humanitarian needs response plan for 2026. The areas identified included: Infrastructure, rebuilding public institutions, social resilience, and mine clearance. Kadish explained that the statement of recovery priorities in Syria and the plan to respond to the needs […]'),
    (28, 'سوريا والمجر تبحثان تعزيز التعاون في الطيران المدني', 'Syria and Hungary are discussing enhancing cooperation in civil aviation', 'التقى رئيس الهيئة العامة للطيران المدني والنقل الجوي عمر الحصري، الخميس 2 نيسان، مع القائم بأعمال سفارة المجر في دمشق أشتفان جيولاشوش، لبحث سبل تعزيز التعاون الثنائي في مجال الطيران المدني. وتناول اللقاء آفاق تطوير العلاقات المشتركة بين البلدين، بما يخدم مصالح الجانبين، ويسهم في دعم قطاع النقل الجوي وتطويره، بحسب ما نشرت الهيئة العامة […]', 'The head of the General Authority of Civil Aviation and Air Transport, Omar Al-Husri, met on Thursday, April 2, with the Chargé d''Affaires of the Embassy of Hungary in Damascus, István Gyulasz, to discuss ways to enhance bilateral cooperation in the field of civil aviation. The meeting discussed development prospects The joint relations between the two countries, in a way that serves the interests of both sides, and contributes to supporting and developing the air transport sector, according to what was published by the General Authority […]'),
    (29, 'وزير الطاقة يبحث مع وزير النفط العراقي آليات بدء تصدير النفط عبر الأراضي السورية', 'The Minister of Energy discusses with the Iraqi Oil Minister the mechanisms for starting oil exports through Syrian territory', 'أجرى وزير الطاقة محمد البشير، الخميس 2 نيسان، اتصالاً هاتفياً مع وزير النفط العراقي حيان عبد الغني، بحثا خلاله آليات بدء تصدير النفط العراقي عبر الأراضي السورية. وبحسب ما نشرت وزارة الطاقة عبر معرفاتها الرسمية، فقد ناقش الجانبان توريد الغاز المنزلي إلى سوريا، وتأهيل خط كركوك – بانياس، في خطوة تعكس عمق التعاون المشترك بين […]', 'On Thursday, April 2, Energy Minister Muhammad al-Bashir made a phone call with Iraqi Oil Minister Hayan Abdul-Ghani, during which they discussed mechanisms for starting the export of Iraqi oil through Syrian territory. According to what the Ministry of Energy published through its official accounts, he discussed The two sides supply domestic gas to Syria, and rehabilitate the Kirkuk-Baniyas line, in a step that reflects the depth of joint cooperation between […]'),
    (30, 'رئيس الوزراء اللبناني: نجدد الرفض التام لأي عمل عسكري خارج مؤسسات الدولة', 'Lebanese Prime Minister: We renew our complete rejection of any military action outside state institutions', 'أكد رئيس الوزراء اللبناني نواف سلام، رفضه التام لأي عمل عسكري خارج مؤسسات الدولة الشرعية، مؤكداً أنّ قرار الحرب والسلم يجب أن يبقى حصراً بيد الدولة. وقال سلام في تصريحات نشرتها الوكالة اللبنانية للإعلام الخميس 2 نيسان: “حذرنا مرراً من حرب مدمرة فُرضت على بلادنا”، مجدداً حرصه على تجنيب لبنان مزيداً من المآسي والخسائر جراء […]', 'Lebanese Prime Minister Nawaf Salam affirmed his complete rejection of any military action outside the legitimate state institutions, stressing that the decision of war and peace must remain exclusively in the hands of the state. Salam said in statements published by the Lebanese Information Agency on Thursday, April 2: “We have repeatedly warned of a devastating war imposed on our country,” reiterating his keenness to spare Lebanon from further tragedies and losses as a result of […]'),
    (31, 'الرئيس الفرنسي: مضيق هرمز استراتيجي للطاقة ويجب إعادة فتحه عبر مسار دبلوماسي', 'French President: The Strait of Hormuz is strategic for energy and must be reopened through a diplomatic path', 'أكد الرئيس الفرنسي إيمانويل ماكرون أن “مضيق هرمز استراتيجي للطاقة، ويجب إعادة فتحه عبر مسار دبلوماسي لا عسكري”، مشيراً إلى أن خيار فتحه بالقوة غير واقعي، وسيستغرق وقتاً طويلاً ويحمل مخاطر كبيرة. وقال في تصريحات نشرها قصر الإليزيه عبر منصة “إكس”، الخميس 2 نيسان، “نسعى إلى بناء مسارات دبلوماسية لوقف إطلاق النار وضمان حرية الملاحة […]', 'French President Emmanuel Macron stressed that “the Strait of Hormuz is strategic for energy, and must be reopened through a diplomatic, not military, path,” indicating that the option of opening it by force is unrealistic, will take a long time and carry great risks. He said in published statements Elysee Palace via the “X” platform, Thursday, April 2, “We seek to build diplomatic paths for a ceasefire and ensure freedom of navigation […]'),
    (32, 'ترامب: إذا لم نتوصل إلى اتفاق سنضرب جميع محطات الطاقة في إيران', 'Trump: If we do not reach an agreement, we will strike all power plants in Iran', 'توعد الرئيس الأمريكي دونالد ترامب، بضرب جميع محطات الطاقة في إيران إذا لم تصل واشنطن وطهران إلى اتفاق. وقال ترامب في خطاب متلفز وجّهه للشعب الأمريكي بشأن الحرب، الخميس 2 نيسان: “سنعيد إيران إلى العصر الحجري”. وتوعد ترامب بضرب إيران “بقوة شديدة” خلال الأسبوعين إلى ثلاثة الأسابيع المقبلة، وأضاف: “الليلة هي بداية النهاية لشرور العدوان […]', 'US President Donald Trump has vowed to strike all power plants in Iran if Washington and Tehran do not reach an agreement. Trump said in a televised speech addressed to the American people regarding the war, Thursday, April 2: “We will return Iran to the Stone Age.” And he promised Trump will strike Iran “very forcefully” over the next two to three weeks, adding: “Tonight is the beginning of the end for the evils of aggression […]'),
    (33, 'أسعار النفط ترتفع إلى 108 دولارات للبرميل بعد خطاب ترامب', 'Oil prices rise to $108 a barrel after Trump''s speech', 'ارتفعت أسعار النفط، الخميس 2 نيسان، إلى أكثر من 6 بالمئة لتصل إلى 108 دولارات للبرميل بعد خطاب الرئيس الأمريكي دونالد ترامب، وفقاً لوكالة أسوشيتد برس الأمريكية. وكان ترامب وجه، في وقت سابق من اليوم، خطاباً للشعب الأمريكي بشأن الحرب على إيران، مؤكداً أن الأهداف الاستراتيجية اقتربت من التحقق، لكنه لم يحدد موعداً لنهاية الحرب. […]', 'On Thursday, April 2, oil prices rose by more than 6 percent, reaching $108 a barrel, after US President Donald Trump’s speech, according to the American Associated Press. Earlier today, Trump addressed the people US Secretary of State regarding the war on Iran, stressing that the strategic goals are close to being achieved, but he did not set a date for the end of the war. […]'),
    (34, 'انطلاق المؤتمر العلمي الأول لنقابة أطباء سوريا', 'The launch of the first scientific conference of the Syrian Doctors Syndicate', 'انطلقت اليوم، الخميس 2 نيسان، أعمال المؤتمر العلمي الأول لنقابة أطباء سوريا تحت عنوان “المستجدات في الاختصاصات الطبية البشرية”، بحضور وزير الصحة مصعب العلي، ووزير التعليم العالي والبحث العلمي مروان الحلبي، وذلك في فندق البوابات السبع بدمشق. وسيستمر المؤتمر ثلاثة أيام ليسلط الضوء على أبرز المستجدات الطبية، ويهدف إلى تعزيز دور البحث العلمي والتعاون المهني […]', 'Today, Thursday, April 2, the work of the first scientific conference of the Syrian Doctors Syndicate began under the title “Developments in Human Medical Specialties,” in the presence of the Minister of Health, Musab Al-Ali, and the Minister of Higher Education and Scientific Research, Marwan Al-Halabi, at the Hotel The Seven Gates of Damascus. The conference will last for three days to highlight the most prominent medical developments, and aims to enhance the role of scientific research and professional cooperation [...]'),
    (35, 'المفوضية الأوروبية: تصرفات إيران تهدد الاستقرار الاقتصادي العالمي', 'European Commission: Iran''s actions threaten global economic stability', 'قالت رئيسة المفوضية الأوروبية أورسولا فون دير لاين: إن “تصرفات إيران تعرّض الاستقرار الاقتصادي العالمي للخطر”، مشددة على أهمية الحفاظ على أمن الملاحة الدولية. وأكدت في تدوينة على حسابها في منصة “إكس”، الخميس 2 نيسان، أن الاتحاد الأوروبي سيعمل بالتعاون مع شركائه الدوليين لضمان استئناف حرية الملاحة في مضيق هرمز في أقرب وقت ممكن. ودعا […]', 'European Commission President Ursula von der Leyen said: “Iran’s actions endanger global economic stability,” stressing the importance of maintaining the security of international navigation. She confirmed in a blog post on her account on the “X” platform, Thursday, April 2, that The European Union will work in cooperation with its international partners to ensure the resumption of freedom of navigation in the Strait of Hormuz as soon as possible. He called […]'),
    (36, 'مباحثات سورية – أردنية لتعزيز التعاون وتبادل الخبرات في مجال البريد', 'Syrian-Jordanian discussions to enhance cooperation and exchange of experiences in the field of mail', 'زار وفد من شركة البريد الأردني برئاسة رئيس مجلس الإدارة سامي الداوود، والمدير العام هنادي الطيب، المؤسسة السورية للبريد، لبحث تعزيز التعاون وتبادل الخبرات والاطلاع على واقع العمل البريدي في سوريا. وشهدت الزيارة لقاء مع وزير الاتصالات وتقانة المعلومات عبد السلام هيكل، بحضور سفير المملكة الأردنية الهاشمية في دمشق سفيان القضاة، ومدير عام المؤسسة السورية […]', 'A delegation from the Jordan Post Company, headed by Chairman of the Board of Directors, Sami Al-Daoud, and General Manager, Hanadi Al-Tayeb, visited the Syrian Postal Corporation, to discuss enhancing cooperation, exchanging experiences, and learning about the reality of postal work in Syria. The visit included a meeting with Minister of Communications and Information Technology, Abdul Salam Heikal, in the presence of the Ambassador of the Hashemite Kingdom of Jordan in Damascus, Sufyan Al-Qudah, and the Director General of the Syrian Foundation […]'),
    (37, 'مباحثات سورية – لبنانية لتعزيز التعاون الاقتصادي بين البلدين', 'Syrian-Lebanese discussions to enhance economic cooperation between the two countries', 'استقبل حاكم مصرف سوريا المركزي عبدالقادر الحصرية، الأربعاء 1 نيسان، سفير لبنان في سوريا هنري قسطون في إطار بحث سبل تعزيز التعاون المشترك بين الجانبين. وجرى خلال اللقاء بحث سبل تعزيز التعاون القطاع المصرفي والمالي، ضمن رؤية جديدة للتعاون الاقتصادي بين البلدين، بحسب ما نشر مصرف سوريا المركزي عبر معرفاته الرسمية. وكان حاكم مصرف سوريا […]', 'On Wednesday, April 1, the Governor of the Central Bank of Syria, Abdul Qader Al-Husria, received the Lebanese Ambassador to Syria, Henry Costoun, within the framework of discussing ways to enhance joint cooperation between the two sides. During the meeting, ways to enhance cooperation in the banking and financial sectors were discussed, including A new vision for economic cooperation between the two countries, according to what the Central Bank of Syria published through its official accounts. The Governor of the Bank of Syria was […]'),
    (38, 'خطوة إيجابية.. غرفة تجارة دمشق تثني على قرار فتح التبادل التجاري مع الأردن', 'A positive step.. The Damascus Chamber of Commerce praises the decision to open trade exchange with Jordan', 'أعلنت وزارة الصناعة والتجارة والتموين الأردنية، الأربعاء 1 نيسان، السماح بدخول منتجات سورية كانت خاضعة سابقاً لقيود الاستيراد، وذلك ضمن تنظيم التبادل التجاري بين البلدين. وينص القرار على إلغاء بعض قرارات الحظر ورخص الاستيراد السابقة، مقابل اعتماد رسوم حماية على قائمة من المستوردات ذات المنشأ السوري، مع التركيز على الصناعات الغذائية والمنسوجات باعتبارها من السلع […]', 'The Jordanian Ministry of Industry, Trade and Supply announced, on Wednesday, April 1, allowing the entry of Syrian products that were previously subject to import restrictions, as part of regulating trade exchange between the two countries. The decision stipulates the cancellation of some bans and licenses Previous imports, in exchange for the adoption of protection fees on a list of imports of Syrian origin, with a focus on food industries and textiles as commodities […]'),
    (39, 'الحسكة.. مديرية الصحة تزود المنطقة الصحية في القامشلي بشحنة أدوية جديدة', 'Al-Hasakah.. The Health Directorate provides the health region in Qamishli with a shipment of new medicines', 'أعلنت مديرية صحة الحسكة تزويد المنطقة الصحية في القامشلي بشحنة دوائية جديدة، في إطار دعم جاهزية المؤسسات الصحية وتلبية احتياجاتها، وفقًا لما نقلت مديرية إعلام الحسكة، الأربعاء ١ نيسان. وبحسب مديرية الصحة، تضمنت الشحنة 32 صنفاً دوائياً متنوعاً شملت أدوية أساسية لمرضى الأمراض المزمنة، أبرزها الإنسولين وأدوية السكري الفموية، فضلاً عن بخاخات الربو والمضادات الحيوية […]', 'The Al-Hasakah Health Directorate announced that it would supply the health region in Qamishli with a new shipment of medicine, within the framework of supporting the readiness of health institutions and meeting their needs, according to what the Al-Hasakah Media Directorate reported on Wednesday, April 1. According to the Health Directorate, the shipment included 32 diverse pharmaceutical classes included essential medications for patients with chronic diseases, most notably insulin and oral diabetes medications, as well as asthma sprays and antibiotics […]'),
    (40, 'سوريا تعيد تفعيل ممرات الطاقة الإقليمية مع بدء دخول “الفيول” العراقي', 'Syria reactivates regional energy corridors with the start of the entry of Iraqi “fuel”.', 'أكدت وزارة الطاقة أن سوريا بدأت بإعادة تفعيل ممرات الطاقة الإقليمية مع بدء دخول صهاريج “الفيول العراقي” أراضيها، متجهة إلى مصب بانياس. ولفتت الوزارة عبر معرفاتها الرسمية، الأربعاء 1 نيسان، إلى أن هذه الخطوة “تؤشر إلى انطلاق مرحلة جديدة من تفعيل حركة ترانزيت الطاقة خلال سوريا وتعزيز دورها الحيوي في الربط بين الأسواق الإقليمية”. وبينت […]', 'The Ministry of Energy confirmed that Syria has begun to reactivate regional energy corridors with the start of “Iraqi fuel” tanks entering its territory, heading to the mouth of Baniyas. The Ministry pointed out through its official accounts, on Wednesday, April 1, that this step “indicates... Launching a new phase of activating the energy transit movement through Syria and enhancing its vital role in linking regional markets.” She indicated […]'),
    (41, 'الحرب الأمريكية – الإيرانية تضغط على اقتصادات دول المنطقة والعالم', 'The American-Iranian war is putting pressure on the economies of countries in the region and the world', 'تسبّب تعطل الملاحة في مضيق هرمز، الذي يمر به نحو 20% من الإمدادات العالمية من النفط والغاز، في ارتفاع أسعار الطاقة، وبالتالي تضخم عام في الأسعار في كثير من دول العالم. وجاء إغلاق المضيق نتيجة الحرب المندلعة في الشرق الأوسط بين إسرائيل والولايات المتحدة من جهة، وإيران من جهة أخرى منذ 28 شباط الماضي. وبحسب […]', 'The disruption of navigation in the Strait of Hormuz, through which about 20% of global supplies of oil and gas passes, has caused energy prices to rise, and thus a general inflation in prices in many countries of the world. The closure of the strait came as a result of the war raging in the east The Middle East conflict between Israel and the United States on the one hand, and Iran on the other hand, has been ongoing since February 28. According to […]'),
    (42, 'المالية تعلن بدء التسجيل الإلكتروني لإعادة صرف المعاشات التقاعدية المتوقفة', 'Finance announces the start of electronic registration to repay suspended pensions', 'أعلنت وزارة المالية، الأربعاء 1 نيسان، بدء التسجيل الإلكتروني لاستكمال عملية صرف المعاشات التقاعدية المتوقفة، وذلك في إطار جهودها لمعالجة ملفات المتقاعدين وضمان وصول المستحقات المالية إلى أصحابها. وأوضحت الوزارة عبر معرفاتها الرسمية، أن عملية التسجيل متاحة من خلال الرسائل النصية المجانية (SMS) إلى الرقم 3346، على أن يتضمن محتوى الرسالة الاسم الثلاثي والرقم الوطني […]', 'On Wednesday, April 1, the Ministry of Finance announced the start of electronic registration to complete the process of disbursing suspended pensions, as part of its efforts to address retirees’ files and ensure that financial entitlements reach their owners. The Ministry explained via According to its official IDs, the registration process is available through free text messages (SMS) to the number 3346, provided that the content of the message includes the full name and the national number […]'),
    (43, 'معاون محافظ حماة يبحث مع مديري المشافي الخاصة تطوير الخدمات الطبية', 'Assistant Governor of Hama discusses with private hospital directors the development of medical services', 'بحث معاون محافظ حماة لقطاع الصحة محمد الشريف، مع مديري المشافي الخاصة سبل تحسين الخدمات الطبية ورفع كفاءة العمل في القطاع الصحي. وتطرق الاجتماع إلى التركيز على تقديم خدمات طبية عالية الجودة وضمان سلامة المرضى والكادر الطبي، إلى جانب تناول أبرز التحديات والاستماع إلى مقترحات المعنيين. بحسب ما نشرت المحافظة عبر معرفاتها الرسمية الثلاثاء 31 […]', 'The Assistant Governor of Hama for the health sector, Muhammad Al-Sharif, discussed with the directors of private hospitals ways to improve medical services and raise the efficiency of work in the health sector. The meeting focused on providing high-quality medical services and ensuring the safety of patients and staff Medical, in addition to addressing the most prominent challenges and listening to the suggestions of those concerned. According to what the governorate published through its official accounts on Tuesday, 31 […]'),
    (44, 'سوريا تكتسح أفغانستان بخماسية وتتأهل إلى نهائيات كأس آسيا متصدرة بالعلامة الكاملة', 'Syria sweeps Afghanistan by five and qualifies for the Asian Cup finals with a perfect score', 'اختتم منتخبنا الوطني لكرة القدم مشواره في التصفيات الآسيوية المؤهلة إلى النهائيات بنتيجة كبيرة، بعدما حقق فوزاً عريضاً على منتخب أفغانستان بنتيجة خمسة أهداف مقابل هدف واحد، في المباراة التي جمعتهما على ملعب الأمير عبد الله الفيصل في مدينة جدة السعودية. وسجل اللاعب محمد الصلخدي هدف المنتخب الأول في الدقيقة الخامسة، وواصل المنتخب سيطرته، لكنه […]', 'Our national football team concluded its campaign in the Asian qualifiers for the finals with a great result, after achieving a broad victory over the Afghanistan national team with a score of five goals to one, in the match that brought them together at Prince Abdul Stadium. God Almighty in Jeddah, Saudi Arabia. Player Mohamed Al-Salkhadi scored the first team’s goal in the fifth minute, and the team continued its control, but […]'),
    (45, 'توقيع اتفاقية تأمين صحي لأكثر من 11 ألف عامل في الشركة السورية للاتصالات', 'Signing a health insurance agreement for more than 11,000 workers at the Syrian Telecommunications Company', 'وقعت المؤسسة العامة السورية للتأمين، الإثنين 30 آذار، عقد تأمين صحي شامل مع الشركة السورية للاتصالات، لتغطية نحو 11,500 عامل وموظف، وذلك بحضور وزير المالية محمد يسر برنية ووزير الاتصالات وتقانة المعلومات عبد السلام هيكل. ويهدف العقد إلى تعزيز مظلة الرعاية الصحية والاجتماعية للعاملين، بما يسهم في تعزيز الاستقرار الوظيفي وتحسين بيئة العمل، إضافة إلى […]', 'On Monday, March 30, the Syrian General Insurance Corporation signed a comprehensive health insurance contract with the Syrian Telecommunications Company, to cover about 11,500 workers and employees, in the presence of the Minister of Finance, Muhammad Yusser Barneyah, and the Minister of Communications and Information Technology, Abdul Salam. structure. The contract aims to strengthen the health and social care umbrella for workers, which contributes to enhancing job stability and improving the work environment, in addition to [...]'),
    (46, 'فضية لسوريا في بطولة أنطاليا الدولية للمواي تاي', 'Silver for Syria in the Antalya International Muay Thai Championship', '​حقق لاعب منتخب سوريا لرياضة المواي تاي البطل سميان علي، الميدالية الفضية بوزن 71 كيلوغراماً، الأحد 29 آذار، في بطولة أنطاليا الدولية المفتوحة التي اختتمت منافساتها في تركيا بمشاركة واسعة من أبطال اللعبة على المستوى العربي والإقليمي والدولي. ​وأوضح رئيس اتحاد اللعبة حسان العلي، أن هذه الميدالية هي ثمرة أول مشاركة لرياضة المواي تاي السورية […]', '​Syrian Muay Thai national team player, champion Sumian Ali, won the silver medal with a weight of 71 kilograms, Sunday, March 29, in the Antalya International Open Championship, which concluded its competitions in Turkey with wide participation from the champions of the game at the level. Arab, regional and international. The head of the Federation, Hassan Al-Ali, explained that this medal is the result of the first participation in the sport of Syrian Muay Thai […]'),
    (47, 'حمص.. خطة خمسية لتأهيل المدينة الرياضية وإنشاء منشآت جديدة', 'Homs.. A five-year plan to rehabilitate the sports city and establish new facilities', 'أكد وزير الرياضة والشباب محمد سامح الحامض أن الوزارة تعمل على تأهيل المدينة الرياضية في حمص ضمن خطة تمتد لخمس سنوات. وتشمل الخطة إنشاء صالات متعددة الاستخدامات وملعباً رئيسياً ومرافق رياضية متكاملة، بالتوازي مع إطلاق أعمال صيانة في عدد من الملاعب، حسب وكالة سانا. وأوضح الحامض خلال جولة ميدانية في المحافظة برفقة محافظ حمص عبد […]', 'Minister of Sports and Youth, Muhammad Sameh Al-Hamid, confirmed that the ministry is working to rehabilitate the sports city in Homs within a five-year plan. The plan includes constructing multi-use halls, a main stadium, and integrated sports facilities, in parallel with the launch Maintenance work in a number of stadiums, according to SANA. Al-Hamid explained during a field tour in the governorate, accompanied by the Governor of Homs, Abdel […]'),
    (48, 'برعاية وزارة الثقافة.. انطلاق ملتقى رواق للتراث السوري في المكتبة الوطنية بدمشق', 'Under the sponsorship of the Ministry of Culture, the launch of the Rwaq Forum for Syrian Heritage at the National Library in Damascus', 'انطلقت أعمال ملتقى رواق للتراث السوري، اليوم الجمعة 27 آذار، تحت رعاية وزارة الثقافة في المكتبة الوطنية بدمشق، بهدف توثيق التراث السوري المادي واللامادي وإتاحته عبر منصات رقمية متخصصة. وأكد وزير الثقافة محمد ياسين الصالح، أن إطلاق الملتقى يعكس توجهاً استراتيجياً يعتمد على الشراكة مع المبادرات الثقافية وتمكينها لتكون رافداً أساسياً في صون الهوية الوطنية، […]', 'The work of the Rwaq Forum for Syrian Heritage was launched today, Friday, March 27, under the auspices of the Ministry of Culture at the National Library in Damascus, with the aim of documenting the tangible and intangible Syrian heritage and making it available through specialized digital platforms. The Minister of Culture, Muhammad Yassin, confirmed Al-Saleh said that launching the forum reflects a strategic direction that relies on partnership with cultural initiatives and enabling them to be an essential contributor to the preservation of national identity, […]'),
    (49, 'وزير الصحة: المرسوم 68 رسالة تقدير للكوادر الطبية', 'Minister of Health: Decree 68 is a letter of appreciation to medical personnel', 'أكد وزير الصحة الدكتور مصعب العلي، أن صدور المرسوم رقم 68 لعام 2026 القاضي بزيادة الرواتب والأجور، يشكل رسالة تقدير ووفاء حقيقية للعاملين، ولا سيما الكوادر الطبية، ويعكس التوجه نحو تحسين واقع القطاع الصحي. وأوضح العلي أن هذه الخطوة تؤكد أن الاستثمار في الإنسان هو المدخل الحقيقي لتطوير الخدمات الصحية ورفع جودتها، حسب ما نشرته […]', 'The Minister of Health, Dr. Musab Al-Ali, confirmed that the issuance of Decree No. 68 of 2026 stipulating increasing salaries and wages constitutes a true message of appreciation and loyalty to workers, especially medical personnel, and reflects the trend towards improving the reality of the health sector. Al-Ali explained This step confirms that investing in people is the real gateway to developing health services and raising their quality, according to what was published […]'),
    (50, 'الرقابة والتفتيش تكشف مخالفات إدارية وفنية في أحد مشافي ريف دمشق', 'Oversight and inspection reveal administrative and technical violations in a hospital in the Damascus countryside', 'كشفت الهيئة المركزية للرقابة والتفتيش، الإثنين 16 آذار، عن مخالفات إدارية وفنية في أحد مشافي محافظة ريف دمشق، وذلك في إطار متابعة أداء المؤسسات الصحية والتحقق من الالتزام بالأنظمة والقوانين الناظمة للعمل الطبي. ورصدت الفرق الرقابية التابعة للهيئة خلال جولة رقابية غياب آليات واضحة لتوثيق المواد الطبية المستخدمة داخل المشفى، وعدم حفظ الأضابير الخاصة بملفات […]', 'On Monday, March 16, the Central Authority for Control and Inspection revealed administrative and technical violations in a hospital in the Damascus countryside governorate, within the framework of monitoring the performance of health institutions and verifying compliance with the regulations and laws regulating medical work. And spotted The Authority’s oversight teams during an oversight tour. The absence of clear mechanisms for documenting medical materials used inside the hospital, and the failure to save files related to […]')
  ) as t(seq_no, title, title_en, content, content_en)
)
insert into public.breaking_news (
  title, title_en, content, content_en, created_at, start_time, end_time, send_notification, is_active, view_count
)
select
  b.title,
  b.title_en,
  b.content,
  b.content_en,
  now(),
  date_trunc('day', now()) + (((b.seq_no - 1) / 5)::text || ' day')::interval as start_time,
  date_trunc('day', now()) + ((((b.seq_no - 1) / 5) + 1)::text || ' day')::interval as end_time,
  true,
  true,
  0
from breaking_seed b
order by b.seq_no;

