-- =============================
-- 8) Normalize logical news locations
-- =============================
update public.news n
set location_id = case
  when lower(coalesce(n.title_en,'')) like '%washington%' then (select id from public.locations where slug = 'washington' limit 1)
  when lower(coalesce(n.title_en,'')) like '%london%' then (select id from public.locations where slug = 'london' limit 1)
  when lower(coalesce(n.title_en,'')) like '%united kingdom%' or lower(coalesce(n.title_en,'')) like '%britain%' then (select id from public.locations where slug = 'united-kingdom' limit 1)
  when lower(coalesce(n.title_en,'')) like '%united states%' or lower(coalesce(n.title_en,'')) like '%america%' then (select id from public.locations where slug = 'united-states' limit 1)
  when lower(coalesce(n.title_en,'')) like '%lebanon%' then (select id from public.locations where slug = 'lebanon' limit 1)
  when lower(coalesce(n.title_en,'')) like '%iraq%' then (select id from public.locations where slug = 'iraq' limit 1)
  when lower(coalesce(n.title_en,'')) like '%iran%' then (select id from public.locations where slug = 'iran' limit 1)
  when lower(coalesce(n.title_en,'')) like '%jordan%' then (select id from public.locations where slug = 'jordan' limit 1)
  when lower(coalesce(n.title_en,'')) like '%palestin%' then (select id from public.locations where slug = 'palestine' limit 1)
  when lower(coalesce(n.title_en,'')) like '%gaza%' then (select id from public.locations where slug = 'gaza' limit 1)
  when lower(coalesce(n.title_en,'')) like '%israel%' then (select id from public.locations where slug = 'israel' limit 1)
  when lower(coalesce(n.title_en,'')) like '%kuwait%' then (select id from public.locations where slug = 'kuwait' limit 1)
  when lower(coalesce(n.title_en,'')) like '%united arab emirates%' then (select id from public.locations where slug = 'uae' limit 1)
  when lower(coalesce(n.title_en,'')) like '%qatar%' then (select id from public.locations where slug = 'qatar' limit 1)
  when lower(coalesce(n.title_en,'')) like '%saudi%' then (select id from public.locations where slug = 'saudi-arabia' limit 1)
  when lower(coalesce(n.title_en,'')) like '%egypt%' then (select id from public.locations where slug = 'egypt' limit 1)
  when lower(coalesce(n.title_en,'')) like '%germany%' then (select id from public.locations where slug = 'germany' limit 1)
  when lower(coalesce(n.title_en,'')) like '%turkey%' then (select id from public.locations where slug = 'turkey' limit 1)
  when lower(coalesce(n.title_en,'')) like '%damascus countryside%' then (select id from public.locations where slug = 'rif-dimashq' limit 1)
  when lower(coalesce(n.title_en,'')) like '%damascus%' then (select id from public.locations where slug = 'damascus' limit 1)
  when lower(coalesce(n.title_en,'')) like '%aleppo%' then (select id from public.locations where slug = 'aleppo' limit 1)
  when lower(coalesce(n.title_en,'')) like '%homs%' then (select id from public.locations where slug = 'homs' limit 1)
  when lower(coalesce(n.title_en,'')) like '%hama%' then (select id from public.locations where slug = 'hama' limit 1)
  when lower(coalesce(n.title_en,'')) like '%latakia%' then (select id from public.locations where slug = 'latakia' limit 1)
  when lower(coalesce(n.title_en,'')) like '%tartus%' then (select id from public.locations where slug = 'tartus' limit 1)
  when lower(coalesce(n.title_en,'')) like '%idlib%' then (select id from public.locations where slug = 'idlib' limit 1)
  when lower(coalesce(n.title_en,'')) like '%raqqa%' then (select id from public.locations where slug = 'raqqa' limit 1)
  when lower(coalesce(n.title_en,'')) like '%deir ez-zor%' then (select id from public.locations where slug = 'deir-ez-zor' limit 1)
  when lower(coalesce(n.title_en,'')) like '%hasakah%' then (select id from public.locations where slug = 'al-hasakah' limit 1)
  when lower(coalesce(n.title_en,'')) like '%daraa%' then (select id from public.locations where slug = 'daraa' limit 1)
  when lower(coalesce(n.title_en,'')) like '%suwayda%' then (select id from public.locations where slug = 'as-suwayda' limit 1)
  when lower(coalesce(n.title_en,'')) like '%quneitra%' then (select id from public.locations where slug = 'quneitra' limit 1)
  else (select id from public.locations where slug = 'syria' limit 1)
end;

commit;

